-- Juuls.dk import (staging) - 419 rom
-- Kilde: juuls.dk/rom (47 katalogsider + 419 produktsider), scrapet 2026-11-08
-- Koer: 1) hele denne fil, 2) SELECT * FROM import_shop('Juuls Vine', 'https://www.juuls.dk', 'stg_juuls_dk', 'Rom');

DROP TABLE IF EXISTS stg_juuls_dk;

CREATE TABLE stg_juuls_dk (
    name TEXT,
    url TEXT,
    price_dkk NUMERIC,
    in_stock BOOLEAN,
    volume_cl NUMERIC,
    abv NUMERIC,
    image_url TEXT,
    description TEXT,
    scraped_at TIMESTAMPTZ
);


-- Kontrol:
SELECT COUNT(*) AS total,
       COUNT(*) FILTER (WHERE in_stock) AS paa_lager,
       COUNT(*) FILTER (WHERE NOT in_stock) AS udsolgt,
       COUNT(*) FILTER (WHERE volume_cl IS NULL) AS uden_volumen,
       COUNT(*) FILTER (WHERE abv IS NULL) AS uden_abv,
       MIN(price_dkk) AS billigste,
       MAX(price_dkk) AS dyreste
FROM stg_juuls_dk;
