INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Original Dark Rum', 'https://www.juuls.dk/rom/varekort/planteray-original-dark-rum', 229, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50648020.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648020-Planteray-Original-Dark-Rum.jpg', 'Her kan man virkelig tale om en klassiker! Planteray Original Dark Rum er fast inventar på verdens bedste barer; der findes bare ikke ret mange flasker, der kan konkurrere på kvaliteten til den pris! Rommen har to komponenter: en del fra Barbados og en del fra Jamaica. Begge er lavet på melasse og fra Barbados kommer de bløde karamel- og kokosagtige noter, mens Jamaica (Long Pond Distillery) leverer den velkendte frugtige kvalitet og lidt ekstra intensitet. Rommen er afrundet med lidt sukker – 15 gram per liter – hvilket giver en sødmefuld smagsoplevelse, uden at rommens karakter overdøves. Farve : Mahogni. Duft : Rige noter af brændt karamel, mælkechokolade, ristet kokos og tropisk frugt. Smagsnoter : Blød og sødmefuld på tungen, men med masser af smag. Varme krydderier, eksotiske frugtnoter og vanilje. Mediumlang eftersmag. Serveringsforslag : En vinder i alt fra Mai Tais til Dark n Stormy.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Original Dark Rum ECO Pouch', 'https://www.juuls.dk/rom/varekort/planteray-original-dark-rum-eco-pouch-1', 709, TRUE, 280, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641377.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641377-Planteray-Original-Dark-Rum-ECO-Pouch.jpg', 'Planterays ECO Pouch er løsningen til dig der gerne vil gøre dine romdrinks lidt mere bæredygtige. Tunge glasflasker er en stor post på klimaregnskabet, men det findes der nu råd for. Planteray har tappet deres ikoniske Original Dark (og 3 Stars) i en pouch – tænk bag-in-box without the box – som indeholder 2,8 liter (hvad der svarer til 4 flasker). Pouchen er væsentligt lettere end en glasflaske – den vejer faktisk kun 45 gram. Og så fylder den også mindre, så der er virkelig noget at spare på transport og i produktionen. Samlet er emballagens carbon footprint reduceret med 80%. Selvfølgelig sparer man endda også noget på literprisen! Rommen er den samme, som vi kender og elsker: et caribisk festfyrværkeri af smag og god stemning! Farve : Rødbrun. Duft : Karamelliseret sukker, nelliker og kanel. Smagsnoter : En fed og cremet fornemmelse i munden, med søde noter af rosiner og kirsebær. Finishen er mere tør og krydret med hints af peberkorn og appelsin. Serveringsforslag : Oplagt til cocktails der kræver mørk, smagfuld rom. Prøv den evt. i en Planter’s Punch.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray 3 Stars White Rum', 'https://www.juuls.dk/rom/varekort/planteray-3-stars-white-rum-1', 229, TRUE, 70, 41.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50648030.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648030-Planteray-3-Stars-White-Rum.jpg', 'Planteray 3 Stars er en blanding af rom fra 3 af ”stjernerne” i den caribiske romproduktion: Barbados, Trinidad og Jamaica – og deraf navnet. Blandingen består af ulagret Barbados-rom, 2-3 år gammel Trinidad-rom, ulagret Jamaica-rom og et touch af vellagret Jamaica-rom, som giver en dybde i smagen man normalt sjældent finder i ”cocktailrom”. Farve : Klar, med et svagt gyldent skær. Duft : Vanilje, banan og nelliker. Smagsnoter : Diskret sødme, tropisk frugt og let græssede noter. Serveringsforslag : Essentiel i barskabet og fuldstændig genial i daiquiris.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray XO 20th Anniversary', 'https://www.juuls.dk/rom/varekort/planteray-xo-20th-anniversary-3', 479, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641306.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641306-Planteray-XO-20th-Anniversary.jpg', 'Planteray ( the rum formerly known as Plantation ) XO 20th Anniversary er én af Barbados'' mest kendte og elskede rom. Rommen er lagret på flere forskellige fadtyper, deriblandt det efterhånden velkendte cognacfad (Planterays signatur, om man vil) men også helt nye, ubrugte fade af amerikansk hvid-eg. Disse fade giver yderligere vaniljenoter til Barbados-rommen, som i forvejen svømmer i tropisk frugt og kokosnød. Farve : Bronze. Duft : Meget aromatisk og frugtig, med ananas, vaniljestang og kokostoppe. Smagsnoter : Rommen er blid og venlig i munden og udfolder sig flot med mazarin, tørret mango og Bounty. Serveringsforslag : Bør drikkes rent. Har du en ven, som ikke bryder sig om ren spiritus? Vis ham/hende denne rom!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray 3 Stars White Rum ECO Pouch', 'https://www.juuls.dk/rom/varekort/planteray-3-stars-white-rum-eco-pouch-1', 709, TRUE, 280, 41.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641378.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641378-Planteray-3-Stars-White-Rum-ECO-Pouch.jpg', 'Vil du gøre din daiquiri en tand mere bæredygtig, så er Planterays smarte ECO Pouch svaret! Tunge glasflasker er en stor post på klimaregnskabet, men det findes der nu råd for. Planteray har tappet deres populære 3 Stars White Rum i en praktisk pouch, som indeholder 2,8 liter (hvad der svarer til 4 flasker). Pouchen er betydeligt lettere end en glasflaske – den vejer faktisk kun 45 gram – og fylder også mindre, så der er virkelig noget at spare på transport – og også i produktionen. Samlet er emballagens carbon footprint reduceret med 80%. Og så sparer man endda også på literprisen! Rommen er selvfølgelig den samme, som vi kender og elsker. Den kan du evt. læse mere om her . Farve : Klar, med et svagt gyldent skær Duft : Milde noter af vanilje, banan og nelliker. Smagsnoter : Diskret sødme, tropisk frugt og let græssede noter. Serveringsforslag : Essentiel i barskabet og fuldstændig genial i daiquiris.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau Supreme Juuls single cask', 'https://www.juuls.dk/rom/varekort/damoiseau-supreme-juuls-single-cask', 369.5, TRUE, 70, 47.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50616520.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50616520-Damoiseau-Supreme-Juuls-single-cask.jpg', 'Damoiseau Supreme (eller Subprime) Juuls Single Cask er et enkelt fad med agricole-rom udvalgt af Juuls Vin og Spiritus og udelukkende frigivet på det danske marked. Rommen er destilleret i 2008 år, hvorefter den har ligget på bourbonfade i Guadeloupes tropiske klima indtil aftapningen cirka 8 år senere. Rommen holder anstændige 47,9% alkohol. Farve: Dyb rav Duft: Mørke kirsebær, ceylonkanel, ristet kokos. Smagsnoter: Flot, kompleks smag med noter af ginseng, tranebær, cedertræ og brændt karamel. Serveringsforslag: Bør drikkes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Grande Reserve', 'https://www.juuls.dk/rom/varekort/planteray-grande-reserve', 269, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50648040.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648040-Planteray-Grande-Reserve.jpg', 'Planteray Grande Reserve er en blanding af forskellige rom fra West Indies Rum Distillery på Barbados. Master Blenderen har ramt en charmerende og helt klassisk profil med masser af kokosnoter, tropisk frugt og vanilje. En del af rommen er destilleret på den gamle kobber-pot still, Old Gregg’s, som er lavet helt tilbage i 1850. Rommen lagres først i et tropisk klima på bourbonfade, og bliver dernæst skibet til Ferrand i Frankrig hvor den flyttes til Ferrands egne fade. Den er tappet med 16 gram sukker tilsat per liter, så du kan forvente en blød og sødmefuld rom. Farve : Rav. Duft : Moden, tropisk frugt. Kokosnød og vanilje. Smagsnoter :  Bløde og sødmefulde noter af kandiseret frugt. Den samme kokosnote, vi fandt i duften, går igen i smagen. Mediumlang eftersmag. Serveringsforslag : Kan drikkes rent, on the rocks eller i romcocktails', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Goslings Black Seal Rum', 'https://www.juuls.dk/rom/varekort/goslings-black-seal-rum', 299, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646000.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646000-Goslings-Black-Seal-Rum.jpg', 'Goslings Black Seal er en rombaseret spiritus fra Bermuda. Den er lavet på sukkerrørsmelasse og er tappet ved 40%. Goslings Black Seal Bermuda Black Rum har en god fylde, og masser af kompleksitet i smagen, hvor man blandt andet finder nuancer af varme krydderier, krydderurter og karamel. Kan nydes både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray OFTD', 'https://www.juuls.dk/rom/varekort/planteray-oftd', 389, TRUE, 70, 69, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641024.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641024-Planteray-OFTD.jpg', 'O.F.T.D. står for ”Old Fashioned Traditional Dark” - selvom nogen har foreslået den alternative fortolkning, ”Oh Fuck, That’s Delicious”. Den er et moderne take på en gammeldags overproof-rom, og for at lave den helt rigtige blanding måtte Alexandre Gabriel hverve nogle af spiritusbranchens mest garvede romnørder. I panelet sad blandt andre tiki-eksperterne Jeff Berry og Martin Cate og cocktailhistoriker David Wondrich og den endelige blanding blev sammensat af rom fra Jamaica, Guyana og Barbados. Farve : Mørk mahogni. Duft : Ristet kokos, brun farin, vanilje og modne bananer. Smagsnoter : Alkoholprocenten fornægter sig ikke i munden. Kraftig smag af kokos, melasse og chokolade. Serveringsforslag : Udmærker sig i tiki-cocktails som Zombies, mai tais osv.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray XO 20th Anniversary PX Sherry Finish', 'https://www.juuls.dk/rom/varekort/planteray-xo-20th-anniversary-px-sherry-finish', 529, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641307.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641307-Planteray-XO-20th-Anniversary-PX-Sherry-Finish.jpg', 'Man kan ikke forbedre det fuldendte… og dog! Planteray XO 20th Anniversary Rum har længe været en af de mest populære rommer i verden, og nu har teamet hos Planteray videreudviklet opskriften. Den har fået navnet PXXO, og som du måske har regnet ud, så refererer de ekstra versaler til Pedro Ximenez , en sød sherrytype på druen af samme navn. Rommen er destilleret på West Indies Rum Distillery på Barbados på både pot- og column stills. Blendet består af ”extra old rums” lagret på både nye fade, bourbonfade og Ferrand-fade, først i troperne og så i Frankrig. Til sidst sætter en finish på sherryfadene prikken over i’et. Farve : Mahogni. Duft : Sød og krydret duft af især kokos og vanilje, efterfulgt af honningagtige noter, engelsk christmas cake, tobak og banan. Smagsnoter : Stor, fyldig og sød på tungen. Noter af kokos, chokolade, svesker og kaffe. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Paranubes', 'https://www.juuls.dk/rom/varekort/paranubes', 429, TRUE, 70, 54, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625253.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625253-Paranubes.jpg', 'Kåret til Best Spirit  ved Mixology Bar Awards  2020 Gold Medal ved Nordic Rum Fest 2019 I Oaxacas tågede bjergskove finder man det lille håndværksdestilleri hvor rommen Paranubes kommer til live. Den laves på frisk sukkerrørssaft, ligesom man kender det fra fx rhum agricole , og destilleres på små kobberkolonner. Alkoholprocenten på 54 er ”still proof”, hvilket vil sige, at den ikke er vandet ned efter destillation – og i øvrigt heller ikke tilsat noget som helst andet. Smagen er fuldstændig unik, og det er ikke tit vi er så begejstrede for en ny rom. Det her er verdensklasse! Farve: Klar. Duft: Fantastisk intens og aromatisk, fyldt med funky noter af overmoden frugt, tomat, urter og limejuice. Smagsnoter: Vi var målløse da vi første gang smagte den. Som destilleret umami: østers, oliven, soltørret tomat, grapefrugt og citrus. Serveringsforslag: Smager fantastisk rent – men vær ikke bange for at eksperimentere med cocktails. En klassisk daiquiri med 5 cl Paranubes, 2 cl frisk limesaft og 1,5 cl sukkersirup er himmelsk.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Calados Dark Rom', 'https://www.juuls.dk/rom/varekort/calados-dark-rom', 149, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640110.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640110-Calados-Dark-Rom.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Xaymaca Special Dry', 'https://www.juuls.dk/rom/varekort/planteray-xaymaca-special-dry', 359, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50648060.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648060-Planteray-Xaymaca-Special-Dry.jpg', 'Planteray Xaymaca Special Dry er ægte Jamaica pot still-rom, med masser af romnørdernes elskede ”funk” eller ”hogo” – den klassiske, kraftige Jamaica-smag af overmodne bananer og ananas, gamle gummibånd og motorrum. Lyder det mærkeligt? Vent til du prøver det! Selve blendet er sammensat af rom fra to destillerier, Clarendon og Long Pond. Rommen er destilleret udelukkende på pot stills og er ikke tilsat sukker. Farve : Rav. Duft : Funky! Alle de ultraklassiske Jamaica-noter af overmoden banan og grillet ananas, samt et hint af diesel og røg. Smagsnoter : Selvom rommen ikke er tilsat sukker, er den ikke helt uden sødme. I smagen finder man allehånde, orangeblomst, abrikos og et syrligt element. Serveringsforslag : Kan nydes ren og er oplagt til tiki-cocktails som mai tais eller fx Smuggler’s Coves version af en Planter’s Punch : 3 cl frisk limesaft 2 cl demerarasukkersirup 1 cl Allspice Dram 9 cl Plantation Xaymaca 2 dash Angostura Bitters Blendes med is. Garnish med mynte.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray XO 20th Anniversary kasse med 2 glas', 'https://www.juuls.dk/rom/varekort/planteray-xo-20th-anniversary-kasse-med-2-glas', 529, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50648073.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648073-Planteray-XO-20th-Anniversary-kasse-med-2-glas.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Smith & Cross Traditional Jamaica Rum 57%', 'https://www.juuls.dk/rom/varekort/smith-cross-traditional-jamaica-rum-57', 279, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644300.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644300-Smith-&-Cross-Traditional-Jamaica-Rum-57%.jpg', 'Smith & Cross Traditional Jamaica Rum 57% er en rom fra Jamaica. Den er lavet på sukkerrørsmelasse. En enormt fyldig sag med stor power, koncentration og noter af tropisk frugt, funky og varme krydderier. Kan sagtens drikkes rent, gerne med et par dråber køligt vand, men prøv den også i en cocktail ! Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Reserva Exclusiva', 'https://www.juuls.dk/rom/varekort/diplomatico-reserva-exclusiva', 339, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643350.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643350-Diplomatico-Reserva-Exclusiva.jpg', 'Diplomatico Reserva Exclusiva er en rom fra Venezuela. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. De lækre noter af vanilje, karamel og kaffe gør den til en favorit hos mange. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Anejo 7 Anos', 'https://www.juuls.dk/rom/varekort/havana-club-anejo-7-anos', 289, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643840.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643840-Havana-Club-Anejo-7-Anos.jpg', 'Havana Club Añejo 7 Años er endnu en fuldstændig uundgåelig og ikonisk cubansk rom. I blendet indgår rom med forskellige aldre: mindst syv år, men nogle af komponenterne er ”flere årtier gamle”. En del af det færdige blend puttes så tilbage på fade, og indgår i den næste batch. Denne ”continuous aging”-teknik er hjertet af Havana Club 7 Años. Farve:  Rav. Duft:  En duft af tobak, overmoden frugt og melasse. Smagsnoter:  Smagen er til den lette og tørre side. Noter af vanilje, tobak og krydderier. Serveringsforslag:  Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Barbados 5 Years Old', 'https://www.juuls.dk/rom/varekort/planteray-barbados-5-years-old', 339, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641051.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641051-Planteray-Barbados-5-Years-Old.jpg', 'Planteray Barbados 5 Years Old er en klassisk Barbados-rom med et twist. Først ligger rommen på bourbonfade i Caribien i mellem 3 og 4 år, hvorefter den undergår Ferrands berømte finish på gamle, franske Cognacfade i 1-2 år, nøje overvåget af de dygtige kældermestre ved Chateau Bonbonnet. Farve : Rav. Duft : Brunkager, pibetobak og marshmallows med en velkendt og ærketypisk Barbados-kokos. Smagsnoter :  En chokoladeagtig og bittersød ankomst med harpiks, rosiner og vanilje. Serveringsforslag : Drikkes rent, med gingerbeer eller i cocktails. Prøv fx tiki-baren Smuggler’s Coves udgave af en  Barbados Rum Punch : 3 cl frisk limesaft 3 cl demerarasukkersirup 6 cl Plantation Grande Reserve 5 Years 1 dash Angostura Bitters Shakes og serveres over knust is. Garnish med revet muskatnød.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Solera 23', 'https://www.juuls.dk/rom/varekort/ron-zacapa-solera-23', 459, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644700.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644700-Ron-Zacapa-Solera-23.jpg', 'Ron Zacapa Solera 23 er en blød og sød rom fra Guatemala. Navnet ”Solera” refererer til en lagringsmetode, som er meget anvendt i Jerez hvor man laver sherry. I rom-verdenen har ordet ikke nogen officiel definition, men betyder som regel, at flere tønder med rom af forskellige årgang og alder blandes. 23 menes at referere til den ældste komponent i blendet – men vi ved det ærligt talt ikke. Farve:  Gylden. Duft:  Mild duft af toffee, vanilje, karamel og honning. Smagsnoter:  Sød og venlig på tungen. Igen masser af karamel, strejf af eg, abrikos og mælkechokolade. Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Calados White Rom', 'https://www.juuls.dk/rom/varekort/calados-white-rom', 149, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640100.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640100-Calados-White-Rom.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation XO 20th Anniversary', 'https://www.juuls.dk/rom/varekort/plantation-xo-20th-anniversary-2', 259, TRUE, 35, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641303.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641303-Plantation-XO-20th-Anniversary.jpg', 'Plantation XO 20th Anniversary er sandsynligvis Plantations mest kendte og elskede rom, denne gang på 35 cl. Rommen er lagret på flere forskellige fadtyper, deriblandt det efterhånden velkendte cognacfad (Plantations signatur, om man vil) men også helt nye, ubrugte fade af amerikansk hvid-eg. Disse fade giver yderligere vaniljenoter til Barbados-rommen, som i forvejen svømmer i tropisk frugt og kokosnød. Farve : Bronze Duft : Meget aromatisk og frugtig, med ananas, vaniljestang og kokostoppe. Smagsnoter : Rommen er blid og venlig i munden og udfolder sig flot med mazarin, tørret mango og Bounty Serveringsforslag : Bør drikkes rent. Har du en ven, som ikke bryder sig om ren spiritus? Vis ham/hende denne rom!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnifica Cristal Cachaca', 'https://www.juuls.dk/rom/varekort/magnifica-cristal-cachaca', 329, TRUE, 100, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646839.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646839-Magnifica-Cristal-Cachaca.jpg', 'Magnifica Cristal Cachaca er en Cachaca fra Brasilien, hvor den produceres ca 110 kilometer fra Rio de Janeiro. Den laves af saft fra sukkerrør, og lagres på ståltanke efter destillation. Farve : Klar. Duft : Floral, grønt græs. Smagsnoter : Frugtig og krydret. Serveringsforslag : Nyd den i Brasiliens nationalcocktail caipirinha eller andre long drinks.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate 8 years 46%', 'https://www.juuls.dk/rom/varekort/hampden-estate-8-years-46', 739, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643781.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643781-Hampden-Estate-8-years-46%.jpg', 'Hampden Estate 8 Years Old er en jamaicansk rom fra et af Caribiens ældste og mest famøse destillerier. På Hampden produceres en karakteristisk, frugtig og kraftig stil, som er højt elsket af spiritusnørder verden over. Denne nye, officielle Hampden-aftapning har kryds i alle de rigtige felter: rommen er udelukkende lagret i troperne (8 år) og er tappet ved 46% alkohol uden tilsætning af sukker eller farvestof – det er svært at komme tættere på rom-nirvana! Farve:  Dyb guld. Duft:  I front er der fadnoter som brændt eg, vanilje og nellike. Bagved fornemmes de karakteristiske noter af tropisk frugt, men det er ikke nogen ”ester-bombe”. Smagsnoter:  Brændt banan, vanilje og ananas. Serveringsforslag:  Nydes rent eller i cocktails – hvis du kan nænne det!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Anejo 3 Anos', 'https://www.juuls.dk/rom/varekort/havana-club-anejo-3-anos', 179, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643801.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643801-Havana-Club-Anejo-3-Anos.jpg', 'Havana Club Añejo 3 Años er en klassisk cubansk rom. Den er lavet på melasse og destilleret på kolonnekedler. Inden den tappes, lagres rommen minimum 3 år på fade af amerikansk egetræ. Rommen er nærmest et ikon – og helt perfekt når der skal laves sprøde daiquiris eller mojitos. Farve : Klar med et svagt gyldent skær. Duft : Dufter af kokos, vanilje og citrus. Ikke kompleks, men vellavet. Smagsnoter : Ganske let. Svag sødme og noter af melasse, ingefær, vanilje og et hint af eg. Serveringsforslag : Oplagt til klassiske daiquiris, mojitos og andre cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Isle of Fiji', 'https://www.juuls.dk/rom/varekort/planteray-isle-of-fiji', 339, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50648050.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648050-Planteray-Isle-of-Fiji.jpg', 'Det er med stor fornøjelse vi kan præsentere den nyeste tilføjelse til Planterays ”Signature Blends”-serie: Isle of Fiji! Vi har i lang tid været enormt begejstrede over rommen fra South Pacific Distillery i Fiji, og Planterays udgave spiller på alle de rigtige tangenter, mens en fin sødme (16 gram sukker per liter) gør den nem at gå til, også for begyndere. Rommen er sammensat af komponenter destilleret på både pot stills og Coffey still, og den er lagret først på bourbonfade, for så at få Planterays karakteristiske ”finish” på cognac-fade. Det hele hænger utroligt godt sammen, og vi må endnu engang sande, at dette totalt undervurderede destilleri giver de fleste af sine caribiske konkurrenter kamp til stregen. Farve : Dyb ravfarvet. Duft : Frugtig og krydret, ”funky” – men ikke helt så vild som Jamaica. Noter af honning, melasse, rosiner, ingefær, banan og ananas. Smagsnoter : Smagen er fyldig og sødmefuld. Flot olieret mundfølelse, igen med noter af ingefær, varme krydderier og melasse, hints af røg og så denne ranke rygrad af tropisk frugt: mango, ananas og appelsin. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Mister Fogg Navy Rum Sail No. 2', 'https://www.juuls.dk/rom/varekort/planteray-mister-fogg-navy-rum-sail-no-2', 469, TRUE, 70, 55.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641385.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641385-Planteray-Mister-Fogg-Navy-Rum-Sail-No.-2.jpg', 'Den længe ventede Mister Fogg har endelig lagt til i Danmark! Dette suveræne caribiske blend er Planterays take på en klassisk ”navy rum”. Du kender sikkert historien om den rom, man skænkede ud på den britiske flåde – og hvis ikke, kan du læse om den her . Opskriften er inspireret af originalen. Dette er 2. batch (Sail No. 2), hvor 34% er fra Barbados, 35% fra Trinidad, 20% fra Guyana, 6% er fra Mauritius (lavet på frisk sukkerrørssaft) og så 5% fra Jamaica, hvor Long Pond, Hampden og Clarendon leverer the final touch til rommen. Den er først lagret på bourbonfade i de respektive oprindelseslande og efter en lang sørejse lagres den op til 3 år i ”wooden vats” – store, åbne træ-kar – i Cognac, Frankrig. Her introduceres en del ilt til spiritussen, hvilket efterligner den måde, man har blandet navyrommen i gamle dage. Den er tappet ved solide 55,7% alkohol og er tilsat 4,8 gram sukker per liter. Farve : Rav. Duft : En kraftig duft af tørret frugt, mørk chokolade, vanilje og appelsinskal vælter op af glasset. Smagsnoter : Rig, fyldig med røgede noter, melasse, karamel og moden frugt. Lang, let sødmefuld eftersmag. Serveringsforslag : Nyd den rent eller i cocktails. Splice the mainbrace!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairman''s Reserve Spiced', 'https://www.juuls.dk/rom/varekort/chairmans-reserve-spiced', 269, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615732.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615732-Chairman''s-Reserve-Spiced.jpg', 'For at lave Chairman’s Reserve Spiced, starter man med en rom, som infuseres med ”Bois Bande”, som er en særlig type bark, der i Caribien er kendt som et afrodisiakum. Kanel, vanilje, muskatnød, nellike, bitterappelsin og en række andre ingredienser fuldender blandingen. Farve : Rav. Duft : Kraftig, krydret duft af varme krydderier, vanilje og tropisk frugt. Smagsnoter : Sød og krydret, men uden at blive kvalm. Skøn kompleksitet og en lang, varmende eftersmag. Serveringsforslag : Nyd den rent over is eller i cocktails, fx med gingerbeer eller i stedet for vodka i et twist på en Espresso Martini !', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Experience Box ', 'https://www.juuls.dk/rom/varekort/plantation-experience-box', 569, TRUE, 10, 41.12, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641351.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641351-Plantation-Experience-Box.jpg', 'Plantation Experience indeholder 6 flasker af 10 cl med forskellige rom fra Plantation Rum. Du får mulighed for at smage et bredt udsnit af Caribiens forskellige stilarter.  Sættet indeholder blandt andet klassikerne; Plantation 3 Stars White ( en blanding af rom fra 3 af ”stjernerne” i den caribiske romproduktion: Barbados, Trinidad og Jamaica – og deraf navnet .),  Plantation Original Dark ( en rom sammensat af 1 til 3 år gammel Barbados-rom og 10-15 år gammel jamaicansk høj-ester rom .) og  Plantation 20th Anniversary XO ( Plantations mest kendte og elskede rom! ) - Bare for at nævne de oplagte Plantation rommer. Dem skal man bare kende! Plantation Experience skifter lidt ud i indholdet fra gang til gang - Så udover de 3 klassikere får du også 3 andre spændende smagsprøver fra deres store udvalg af Caribisk rom.  Den perfekte gaveidé til rom-elskeren eller en oplagt mulighed for at holde din egen romsmagning for dig selv og 4 venner!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau Rhum Millesime 2008 Subprime Cuvee', 'https://www.juuls.dk/rom/varekort/damoiseau-rhum-millesime-2008-subprime-cuvee', 524.5, TRUE, 70, 47.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50616521.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50616521-Damoiseau-Rhum-Millesime-2008-Subprime-Cuvee.jpg', 'Damoiseau Supreme (eller Subprime) Juuls Single Cask er et enkelt fad med agricole-rom udvalgt af Juuls Vin og Spiritus og udelukkende frigivet på det danske marked. Rommen er destilleret i 2008 år, hvorefter den har ligget på bourbonfade i Guadeloupes tropiske klima indtil aftapningen cirka 8 år senere. Rommen holder anstændige 47,9% alkohol. Farve : Dyb rav Duft : Mørke kirsebær, ceylonkanel, ristet kokos. Smagsnoter : Flot, kompleks smag med noter af ginseng, tranebær, cedertræ og brændt karamel. Serveringsforslag : Bør drikkes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Cuvee Canopée 2ed', 'https://www.juuls.dk/rom/varekort/rhum-jm-cuvee-canopee-2ed', 779.5, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614516.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614516-Rhum-JM-Cuvee-Canopée-2ed.jpg', 'Rhum JM ligger under de grønne trækroner for foden af vulkanen Mont Pelée på Martinique. Det er et af verdens smukkest beliggende destillerier, og de skønne omgivelser hyldes nu med rommen Canopée: en seks år gammel hors d’age, tappet i en utroligt flot dekanter med tilhørende kasse. Det er rhum agricole, når det er bedst: udtryksfuld og kompleks med lag efter lag af sukkerrørssaft, brændte figner, kakao og ulmende træ. Tappet ved 46%, selvfølgelig uden tilsat sukker. Farve : Rav. Duft : Ristede noter af kakaobønner og kaffe, dadler, figen og frisk sukkerrørssaft. Smagsnoter : En tør og aristokratisk rom, med røgede noter og søde krydderier: kanel, muskatnød, tørrede figner og brændt eg. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate Fresh', 'https://www.juuls.dk/rom/varekort/hampden-estate-fresh', 379, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642411.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642411-Hampden-Estate-Fresh.jpg', 'Hampden Fresh viser en helt ny side af Jamaicas ældste destilleri - ikke fordi rommen derfra normalt ikke er frisk, men fordi Fresh er den første rom fra Hampden Estate, der er beregnet til cocktails. Mange kender Hampdens ikoniske ”Rum Fire”, som tappes med et højt esterindhold og en voldsom alkoholprocent, men Fresh har en anden ambition: den er lavere i alkohol (42%) og en anelse mindre funky – om end stadig genkendeligt Jamaica! Farve : Klar. Duft : Øjeblikkeligt meget frugtig, med melon, citron, ananas og banan. Smagsnoter : Rammer tungen med klasssiske Hampden-noter af overmoden, tropisk frugt, et touch af finsk lakrids og citronmelisse. Serveringsforslag : Prøv den i Daiquiris, Piña Coladas og andre romdrinks – eller brug den i andre klassiske cocktails, som du vil give en jamaicansk twist.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kaniche XO Rum', 'https://www.juuls.dk/rom/varekort/kaniche-xo-rum', 569, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641510.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641510-Kaniche-XO-Rum.jpg', 'Kaniché XO er storebroren til Kaniché Reserve. Rommen undergår Pierre Ferrands famøse efterlagring på små og gamle cognacfade i Chateau Bonbonnets fugtige kældre, hvilket præger Barbadosrommen i en mere elegant retning. Resultatet er en sødmefuld og fyldig rom uden skarpe kanter.  Farve: Mahogni Duft: Krydret duft af peberkorn, vaniljefudge og piña colada. Smagsnoter: Saftig ananas, Werther’s Original og lys sirup. Serveringsforslag: Bør drikkes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Stroh (80)', 'https://www.juuls.dk/rom/varekort/stroh-80', 349, TRUE, 100, 80, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50647100.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50647100-Stroh-(80).jpg', 'Stroh er en østrigsk spiritus baseret på rom. Den er efterhåndenden lidt af et ikon, bl.a. på grund af sin farligt høje styrke: Stroh er tappet ved 80% alkohol! Smagen er præget af karamel og varme krydderier. Der er faktisk et ekko af Jamaica i smagen, så mon ikke en del af rommen i blandingen kommer derfra? Vi anbefaler, at man bruger Stroh i toddies og drinks.  Flasken indeholder 100 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Rum Fire 63%', 'https://www.juuls.dk/rom/varekort/hampden-rum-fire-63', 379, TRUE, 70, 63, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642410.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642410-Hampden-Rum-Fire-63%.jpg', 'Rum Fire! Vi ved snart ikke, hvad der er fedest: navnet, etiketten eller smagen? Denne flaske er en legende, et ikon og en fuldstændig uundgåelig lektion i enhver romnørds uddannelse. Rum Fire kommer fra det jamaicanske destilleri, Hampden Estate , og er indbegrebet af "funk". Tænk overmoden banan og ananas, gamle elastikker, kamfer, diesel og den karakteristiske rosenketon. Har du ikke smagt den endnu, så venter der en stor oplevelse! Farve:  Klar. Duft:  En vild og eksplosiv duft, fyldt til bristepunktet med tropisk frugt (banan, mango, ananas), grønne oliven, gummi, kamfer og diesel. Smagsnoter:  Tæt og intens. Igen masser af frugt, særligt den tropiske men også pære, mynte og kamfer, florale noter, ingefær og vi ku’ blive ved! Serveringsforslag:  Kan nydes rent eller i cocktails! Prøv fx at putte en centiliter eller to i din daiquiri sammen med en mindre kraftig rom. Eller top den med grapefrugtsodavand eller ginger beer.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnifica Bica do Alambique Cachaca', 'https://www.juuls.dk/rom/varekort/magnifica-bica-do-alambique-cachaca', 239, TRUE, 50, 48, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646840.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646840-Magnifica-Bica-do-Alambique-Cachaca.jpg', 'Glem alt – eller i hvert fald det meste af - hvad du ved om cachaça! Alt for længe har denne brasilianske rom-type været forvist til caipirinhas, for de allerbedste eksempler kan meget mere end cocktails. Bica do Alambique fra Magnìfica de Faria er et godt eksempel. En ekstremt kraftfuld og aromatisk cachaça, vildgæret på frisk sukkerrørssaft, destilleret på pot stills og tappet ved destillationsstyrke (48% alkohol). Er du fan af rhum agricole, Clairin eller Paranubes, så har du her din næste besættelse. Og så til den pris! Farve:  Klar. Duft:  Sikke en duft! Stor og aromatisk springer den op af glasset med noter af sort trøffel, kapers, frisk sukkerrørssaft, græs og halm der bager i solen. Smagsnoter:  Masser af smag og power, men uden  burn.  Noter af trøffel og skovbund og rød frugt som jordbær og kirsebær. Serveringsforslag:  Kan nydes rent eller i cocktails. Du kan bruge den i en caipirinha,  det er klart, men prøv den også i klassiske rom-cocktails som Daiquiris eller Mai Tais.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Communal', 'https://www.juuls.dk/rom/varekort/clairin-communal', 389, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625196.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625196-Clairin-Communal.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Creol Blanc 52', 'https://www.juuls.dk/rom/varekort/savanna-creol-blanc-52-1', 459, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615489.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615489-Savanna-Creol-Blanc-52.jpg', 'Savanna Creol Blanc er en rom fra øen La Réunion. Savanna laver rom i mange stilarter, og navnet ”Creol” indikerer, at denne rom er lavet på frisk sukkerrørssaft og destilleret på kolonnekedler. En relativt kort gæring, som forløber over 2 dage, betyder, at denne rom ikke er den mest ”funky” i Savannas sortiment, men misforstå ikke: det er stadig rom med masser af karakter, der vil gøre de fleste romnørder bløde i knæene. Den er tappet ved 52% alkohol. Farve : Klar. Duft : Flot, grøn duft af anis, safran, vanilje og sukkerrørssaft. Smagsnoter : Livlig, krydret og let sødmefuld, med peber, sukkerrørssaft, oliven og tropisk frugt. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cachaca 51', 'https://www.juuls.dk/rom/varekort/cachaca-51', 169, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646945.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646945-Cachaca-51.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate HLCF Single Cask Juuls 100th Anniversary', 'https://www.juuls.dk/rom/varekort/hampden-estate-hlcf-single-cask-juuls-100th-anniversary', 1395, TRUE, 70, 64.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643691.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643691-Hampden-Estate-HLCF-Single-Cask-Juuls-100th-Anniversary.jpg', 'At få lov at vælge et helt fad fra Jamaicas bedste destilleri, Hampden Estate, er en stor ære. Vi fik chancen i forbindelse med vores 100-års jubilæum i år. Rommen, vi valgte, er en såkaldt HLCF (Hampden Light Continental Flavoured), hvilket betyder, at den ligger cirka midt på Hampdens skala for esterindhold: 400-600 gr/HLPA. Det høje esterindhold opnås via destilleriets unikke blanding af melasse, dunder, muck og sukkerrørssaft, samt en 7 dage lang gæring. Det er et ikonisk "mark" for Hampden, og smagen er bare helt rigtig .  Lagringen foregår i tropisk klima på destilleriet, men her sker der også noget usædvanligt: Den ligger nemlig 2 år på topklassse sherryfade fra Bodegas Fundador! Rommen er selvfølgelig tappet ved fadstyrke: 64,3% alkohol. Det er opskriften på en rom, der brager igennem med uhyrlig intensitet, koncentration og kompleksitet. Farve : Dyb gylden. Duft : Frugtige noter af abrikos og ananas møder kakao, valnød og citrusskal. Smagsnoter : Superintens som kun high ester Hampden kan være det, fyldt med funk, mynte, dadler, tørret frugt og mango. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Latino - Rum from Molasses - Venezuela', 'https://www.juuls.dk/rom/varekort/cdi-latino-rum-from-molasses-venezuela', 289, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640556.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640556-CDI-Latino---Rum-from-Molasses---Venezuela.jpg', 'Compagnie des Indes Latino kommer fra Venezuelas ældste familieejede destilleri, Destilería Sofa. Rommen er lavet på melasse og er destilleret på kolonnekedler – sidstnævnte giver den klassiske, lette stil. Den er lagret 4 år på amerikanske bourbonfade i et tropisk klima og tappet ved 40% alkohol med 15 gram sukker tilsat per liter. Farve : Lys gylden. Duft : Let og frugtig med noter af mandel og marcipan. Smagsnoter : Sødmefule noter af kandiseret ananas, friskmalet kaffe, lakrids og honning. Serveringsforslag : Rommen kan nydes rent eller i simple cocktails, fx som erstatning for bourbon i en Old Fashioned.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('J Wray and Nephew White Overproof', 'https://www.juuls.dk/rom/varekort/j-wray-and-nephew-white-overproof', 259, TRUE, 70, 63, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642400.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642400-J-Wray-and-Nephew-White-Overproof.jpg', 'J Wray and Nephew White Overproof er en rom fra Jamaica. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 63%. Du kan forvente en kraftig og fyldig smag med strejf af funky og Tropisk frugt. Nyd den gerne rent, evt. med en dråbe køligt vand eller to, eller i en god cocktail . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Montebello Rhum Vieux 6 ans', 'https://www.juuls.dk/rom/varekort/montebello-rhum-vieux-6-ans', 629, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50620730.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50620730-Montebello-Rhum-Vieux-6-ans.jpg', 'Efter 6 år på bourbonfade i tropisk klima, er denne agricole-rom fra Montebello blevet et lille mesterværk: kompleks, spændende og stiltypisk. Tappet ved 42%, selvfølgelig uden tilsat sukker. Farve : Gylden. Duft : Dufter næsten som en friskbagt æbletærte, varme krydderier og rosin. Smagsnoter : Lækre noter af varm brioche med smør, honning og bagt æble. Serveringsforslag : Nyd den rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Finest Caribbean Rum', 'https://www.juuls.dk/rom/varekort/black-tot-finest-caribbean-rum', 479, TRUE, 70, 46.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642249.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642249-Black-Tot-Finest-Caribbean-Rum.jpg', 'Black Tot Finest Caribbean er et blend af rom fra forskellige caribiske øer, naturligvis inspireret af den rom, som man indtil 1970 serverede ombord på den britiske flåde. Black Tot er nøje komponeret af master blender Oliver Chilton, som efter mange prøvesmagninger af den originale flåderom har sammensat et blend af 40% Barbados-rom, 35% Trinidad-rom, 20% Guyana-rom og 5% jamaicarom. Al rommen er 100% tropisk lagret på ex-bourbonfade. Den er tappet uden kølefiltrering ved 46,2% og uden tilsat sukker. Splice the mainbrace! Farve : Gylden. Duft : Kompleks duft af flamberede bananer, stenfrugt, kaffe, surdejsrugbrød, lyse rosiner og kokos. Smagsnoter : I munden starter rommen sødt og blødt, men med masser af smag og bragende kommer lakrids, kaffe, ingefær og kardemomme. Serveringsforslag : Smager fantastisk rent – men kan også bruges i cocktails!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Le Rocher Haiti', 'https://www.juuls.dk/rom/varekort/clairin-le-rocher-haiti-5', 529, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625341.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625341-Clairin-Le-Rocher-Haiti.jpg', 'Le Rocher er en hvid rom fra Haiti. I modsætning til de fleste af de andre clairins i Veliers serie, er Le Rocher ikke lavet på frisk sukkerrørssaft, men på en indkogt sukkerrørssirup. Master distilleren Bethel Romulus er en religiøs mand, og han har kaldt rommen Le Rocher (Klippen) efter en passage i Matthæusevangeliet, som forkynder, at en klog mand bygger sit hus på en klippe, mens en tåbe bygger på sand. Bethel Romulus har naturligvis bygget sit destilleri på en klippe. Farve : Klar. Duft : Funky duft af sukkerrørssaft, oliven og en let røg, som af røget bacon. Smagsnoter : Meget intens, men silkeblød, med sødme og noter af lakrids, jod og overmodne frugter. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairman''s Reserve Original Rum', 'https://www.juuls.dk/rom/varekort/chairmans-reserve-original-rum', 309, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615731.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615731-Chairman''s-Reserve-Original-Rum.jpg', 'Chairman’s Reserve Original Rum er den perfekte introduktion til rom fra St. Lucia. Opskriften på netop denne rom blev skabt i 1999 af Laurie Bernard (den originale ”chairman”!) som gerne ville højne niveauet i firmaet og i øvrigt definere den essentielle St. Lucia-rom. Det må man sige er lykkedes. Rommen er en blanding af pot still- og kolonnedestilleret rom – førstnævnte er meget koncentreret i smagen mens sidstnævnte er relativt let – og det giver en perfekt balance. Den er lagret 4-5 år på bourbonfade i St. Lucias tropiske klima. Farve : Rav. Duft : Jeps, den klassiske St. Lucia-duft af karamelliseret sukker, brændt banan, krydret eg og vanilje. Fremragende! Smagsnoter : Mediumfyldig, balanceret og proppet med smag. Gule rosiner, krydrede noter af nellike, tobak og en lang finish. Serveringsforslag : Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bielle Single Cask 268 Juuls Rhum', 'https://www.juuls.dk/rom/varekort/bielle-single-cask-268-juuls-rhum', 1804.5, TRUE, 70, 46.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50622500.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50622500-Bielle-Single-Cask-268-Juuls-Rhum.jpg', 'Denne Bielle Single Cask Agricole-rom fra 2001 kommer fra den lille ø Marie Galante, just sydøst for Guadeloupe. Juuls Vin og Spiritus har fået lov at købe hele det ekstraordinært gode fad nummer 268 (et tidligere bourbonfad), og det er tappet ved 46,7% alkohol. Rommen er potent, kraftig og tør med mørke noter af brændt karamel, egetræ og krydderier. Farve: Rav Duft: Meget intens duft af ingefær, hvid chokolade, tobak og spidskommen. Smagsnoter: Kraftig og mørk i smagen af brændt karamel, mango, egetræ, nelliker og kanel. Serveringsforslag: Bør nydes rent, evt. med en dråbe vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Millonario Reserva Especial 15', 'https://www.juuls.dk/rom/varekort/ron-millonario-reserva-especial-15', 409, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644100.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644100-Ron-Millonario-Reserva-Especial-15.jpg', 'Ron Millonario Reserva Especial 15 er en rom fra Peru. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. En super smagsoplevelse med noter af vanilje og karamel. Nyd den rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado 12 years', 'https://www.juuls.dk/rom/varekort/el-dorado-12-years', 399, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646310.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646310-El-Dorado-12-years.jpg', 'El Dorado 12 Years Old er en rom fra det sidste overlevende destilleri på Guyana; Diamond Distillery. Rommen her er sammensat af destillater fra flere af deres kedler, blandt andet den berømte coffey still, Enmore. Den er lagret i minimum 12 år på amerikanske egetræsfade, og er uden tvivl ”gateway-rommen” for mange romelskere, med sin fyldige, dybe og sødmefulde stil. Farve:  Rav. Duft:  Vanilje, varme krydderier og karamel. Smagsnoter:  Meget sød, blød og rund, men med god dybde og tyngde. Noter af brun farin, toffee, vanilje og karamel. Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ypioca Cachaca Ouro Bast', 'https://www.juuls.dk/rom/varekort/ypioca-cachaca-ouro-bast', 209, TRUE, 70, 38, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646910.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646910-Ypioca-Cachaca-Ouro-Bast.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carupano Reserva 12 Exclusiva', 'https://www.juuls.dk/rom/varekort/carupano-reserva-12-exclusiva', 319, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643331.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643331-Carupano-Reserva-12-Exclusiva.jpg', 'Carúpano Reserva Exclusiva er en rom fra Venezuela lavet på sukkerrørsmelasse. Den er sammensat af rom i forskellige aldre, og i blandingen indgår rom der har ligget 12 lange år på fade af amerikansk hvideg. Hos Carúpano er der en høj fordampning fra fadene, og de har tradition for at man ikke topper fadene op løbende. Ifølge deres master blender, bevirker det at rommen modnes hurtigere, og vi må sige, at Reserva Exclusiva virkelig føles perfekt moden på dette stadie. En rom til alle lejligheder! Farve : Rav. Duft : Honningnoter blander sig med blomme, kanel og nellike. Smagsnoter : Flot fyldig, med en let, naturlig sødme og noter af ahornsirup og melasse. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Terroir Volcanique', 'https://www.juuls.dk/rom/varekort/rhum-jm-terroir-volcanique', 509, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614061.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614061-Rhum-JM-Terroir-Volcanique.jpg', 'Rhum J.M Terroir Volcanique er en rhum agricole fra Martinique. Navnet refererer selvfølgelig til øens berømte vulkan, Mt. Pelée (som ses på etiketten), og denne nye udgivelse er den perfekte forening af øens terroir og kældermester Karine Lassalles håndværk. Rommen er destilleret på kolonnekedler og lagret på fade af amerikansk eg med forskellige grader af brænding, hvilket giver en kompleks og intens rom. Den er tappet ved 43% alkohol, selvfølgelig uden tilsat sukker. Farve : Gylden. Duft : Eventyrlig duft af vanilje, honning og muskatnød. Smagsnoter : Kraftig men rund i smagen, hvor man finder de samme nuancer fra duften samt et fint af tropisk frugt. Serveringsforslag : Nyd den rent eller i en luksus-ti’ punch.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Pacifico - Rum from Molasses - Panama & Thailand', 'https://www.juuls.dk/rom/varekort/cdi-pacifico-rum-from-molasses-panama-thailand', 419, TRUE, 70, 42.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640562.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640562-CDI-Pacifico---Rum-from-Molasses---Panama-&-Thailand.jpg', 'Rommen Pacifico fra Compagnie des Indes er et lettere usædvanligt blend af to lande adskildt af Stillehavet: Panama og Thailand. Begge komponenter er lavet på melasse og destilleret på kolonnekedler, men de varierer i alder fra 6-12 år, og blendet har derfor både friskhed, dybde og kompleksitet. Den er tappet ved 42,5% alkohol med 15 gram sukker tilsat per liter. Rommen er ikke kølefiltreret. Farve : Rav. Duft : Meget aromatisk med eukalyptus, karamel og kandiseret appelsin. Smagsnoter : Krydrede noter af muskatnød, lakrids og chokolade. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Millonario XO Reserva Especial', 'https://www.juuls.dk/rom/varekort/ron-millonario-xo-reserva-especial', 709, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644150.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644150-Ron-Millonario-XO-Reserva-Especial.jpg', 'Ron Millonario XO Reserva Especial er en rom fra Peru. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Ron Millonario XO Reserva Especial har en mellemfyldig og elegant smag med nuancer af varme krydderier, vanilje, karamel og tropisk frugt. Kan nydes både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Veritas White Blended Rum', 'https://www.juuls.dk/rom/varekort/veritas-white-blended-rum', 319, TRUE, 70, 47, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644290.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644290-Veritas-White-Blended-Rum.jpg', 'Veritas White Blended Rum er en rom skabt i samarbejde mellem Richard Seale, manden bag kedlerne på Foursquare Distillery og Luca Gargano, den karismatiske italiener bag aftappervirksomheden Velier. Rommen er blandet af kraftig pot still rom fra Hampden i Jamaica, og både lagret og ulagret pot- og kolonne-destilleret rom fra Foursquare i Barbados. Den er tappet ved respektable 47% alkohol. En heftig indsprøjtning kvalitet til dine daiquiris! Farve: Bleg gylden. Duft: Fin duft af vaniljecreme, ristet kokos og et let, men klædeligt Jamaica-præg af banan og gummibånd. Smagsnoter: Cremet smag hvor der er noter af melasse, nødder og smør. Serveringsforslag: Oplagt til daiquiris og tiki-cocktails!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Centenario XO', 'https://www.juuls.dk/rom/varekort/ron-zacapa-centenario-xo', 1005, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644720.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644720-Ron-Zacapa-Centenario-XO.jpg', 'Ron Zacapa Centenario XO er en sød rom fra Guatemala. Det er næsten håbløst at tælle hvor mange medaljer og konkurrencer, denne rom har vundet. Zacapa har åbenbart ramt noget rigtigt med dette blend af 6-25 år gammel rom, som blandt andet er lagret på franske egetræsfade der før har indeholdt cognac. Farve : Mørkt rav. Duft : Dadler, rosiner, karamel og vanilje. Smagsnoter : Afrundet og sødmefuld i smagen. Også her finder man tørret frugt, med en spicy undertone af varme krydderier som kardemomme og nellike. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carupano Reserva 18 Limitada', 'https://www.juuls.dk/rom/varekort/carupano-reserva-18-limitada', 429, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643332.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643332-Carupano-Reserva-18-Limitada.jpg', 'Ron Carúpano lancerede den luksuriøse Reserva Limitada i 2020. Her er tale om en langtidslagret rom, som ligger på forseglede ex-bourbon fade i op til 18 år  uden erstatning af Angel''s Share. Til nedvandingen anvendes udelukkende Carúpanos eget kildevand. Det gode vand er en kæphest for destilleriet, som understreger hvor stor en rolle det spiller i rommens smag. En behagelig, blød og velafbalanceret rom og et flot eksempel på hvad Venezuela har at byde på. Farve : Mørk gylden Duft : En duft af kandiserede frugter, eg og honning. Smagsnoter : En behagelig varighed med noter af figen og et hint af chokolade. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnifica XP Dupla Maturaçao Cachaca', 'https://www.juuls.dk/rom/varekort/magnifica-xp-dupla-maturacao-cachaca', 379, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646842.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646842-Magnifica-XP-Dupla-Maturaçao-Cachaca.jpg', 'Magnìfica de Faria Extra Premium er en cachaça fra staten Rio de Janeiro. Navnet  Extra Premium  er ikke bare en kvalitetserklæring, det betyder også, at cachaçaen lever op til kravet om minimum 3 års lagring. Den er lavet på frisk sukkerrrøssaft, som vildgæres og destilleres på pot stills. Først ligger den 1 år i store kar af det lokale ipêtræ, og dernæst 3 år på fade af amerikansk eg. Den årlige angel’s share er relativt høj, så allerede på 4 år har man en flot moden og kompleks spiritus. Den er tappet ved 43% alkohol. Se videoen, hvor Romhatten kårer årets rom 2023 - her ! Farve:  Let gylden. Duft:  Lad den åbne sig et par minutter i glasset, så bliver du belønnet med en elegant duft af cedertræ, sort peber, saltede citroner, frisk sukkerrørssaft og… vi ku’ blive ved! Smagsnoter:  Minder næsten lidt om en god rhum agricole fra Martinique: elegant, sprød og balanceret. Serveringsforslag:  Nydes rent eller i cocktails hvis du virkelig skal forkæle dig selv!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Come Hell or High Water XO Giftpack', 'https://www.juuls.dk/rom/varekort/come-hell-or-high-water-xo-giftpack', 379, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643491.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643491-Come-Hell-or-High-Water-XO-Giftpack.jpg', 'Come Hell or High Water XO er en sød og fyldig rom skabt af One Eyed Spirits. Bag selve rommen står dog Don Pancho Fernandez, en vaskeægte rom-legende med 50 års erfaring som master blender! Han har kreeret det perfekte blend bestående af destillater fra Barbados, Guyana, Trinidad og Jamaica. Ikke noget dårligt udgangspunkt! Rommen er lagret op til 15 år i amerikanske egetræsfade der tidligere har indeholdt bourbon. Farve : Rav. Duft : I næsen er rommen blød og rund men også ret koncentreret, med noter af karamelliseret sukker, peanutbutter og mælkechokolade.  Smagsnoter : Olieret mundfølelse og stor sødme. Noter af rosiner, chokolade og fudge. Serveringsforslag : Kan nydes rent eller i cocktails .', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Montebello Rhum Vieux 8 ans Winch', 'https://www.juuls.dk/rom/varekort/montebello-rhum-vieux-8-ans-winch', 394.5, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50620740.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50620740-Montebello-Rhum-Vieux-8-ans-Winch.jpg', 'Montebellos særlige cuvée, Winch, er altid noget ekstraordinært, og denne 8-årsudgave har langt mere at byde på, end man skulle tro ved første øjekast. Både duft og smag er et overflødighedshorn af mørk chokolade, kaffe, karamel, nelliker og en masse andet – her er virkelig kompleksitet for alle pengene! Rommen er lagret 8 år på bourbonfade i tropisk klima, og tappet ved 42% alkohol uden tilsat sukker. Farve : Gylden. Duft : En skøn blanding af mellemristet kaffe, appelsin stukket med nelliker og rigtig god chokolade. Smagsnoter : Kraftig og koncentreret på trods af den relativt lave alkohol, med mange af de samme noter fra duften samt karamel og et touch af tannin. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Anejo Especial', 'https://www.juuls.dk/rom/varekort/havana-club-anejo-especial', 199, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643835.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643835-Havana-Club-Anejo-Especial.jpg', 'Havana Club Anejo Especial er en rom fra Cuba. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 37,5%. Smagen er mellemkraftig med noter af karamel, vanilje og egetræ. Nyd den rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnifica Tradicional Ipe Cachaca', 'https://www.juuls.dk/rom/varekort/magnifica-tradicional-ipe-cachaca-1', 359, TRUE, 100, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646849.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646849-Magnifica-Tradicional-Ipe-Cachaca.jpg', 'Magnìfica de Faria Tradicional Ipê er en cachaça fra Rio de Janeiro. Altså staten, ikke byen. Den er lavet på frisk sukkerrørssaft, som vildgæres og destilleres på pot stills. Navnet Ipê refererer til en særlig, brasiliansk træsort, som ofte bruges til lagring af cachaça. I dette tilfælde har spiritussen tilbragt minimum 1 år i store vats af ipê-træ. Farve : Klar, men med det fjerneste gyldne skær. Duft : Virkelig aromatisk. Sort peber, sukkerrørssaft og et touch af trøffel. Smagsnoter : Spicy og sødmefuld i starten, med noter af græs og grøn banan. Ikke superkompleks, men balanceret smag i en flot integreret alkohol. Tørrer let ud i eftersmagen. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Intense 41.3%', 'https://www.juuls.dk/rom/varekort/savanna-intense-41-3', 319, TRUE, 70, 41.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615433.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615433-Savanna-Intense-41.3%.jpg', 'Den afrundede, elegante Savanna Intense 41.3 er en rhum traditionnel fra Reunion i Det Indiske Ocean. I denne sammenhæng betyder ”traditionel”, at den er lavet på melasse, ikke frisk sukkerrørssaft, som destilleriet også gør sig i. Forvent en fantastisk frugtig, let floral og vanvittigt lækker rom. Tappet uden fadlagring ved 41,3% uden tilsat sukker. Farve : Klar. Duft : Frugtige noter af banan, hvide blomster og sukkerrør. Smagsnoter : Tør, elegant og igen meget frugtig smag, som holder ved længe. Serveringsforslag : Brug den i cocktails der lige skal have et ekstra skud kvalitet. Det kunne fx være en mai tai eller en daiquiri.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Metis', 'https://www.juuls.dk/rom/varekort/savanna-metis-1', 359, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615434.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615434-Savanna-Metis.jpg', 'Métis er en rom fra La Réunion i det indiske ocean. Her finder man destilleriet Savanna, som både laver rom på frisk sukkerrørssaft og melasse. Savanna Métis hører til i sidstnævnte kategori: en såkaldt rhum traditionnel, som er lavet på melasse og lagret op til 4 år på franske egetræsfade og store trækar, hvorfra den får en let gylden kulør og subtile noter af vanilje, kokos og egetræ. Farve : Bleg gylden. Duft : Rar duft med hyggelige noter af kokos og vaniljestang, cedertræ og pebermynte.  Smagsnoter : Blød, men karakterfuld. Friske sukkerrørsnoter, vanilje, lidt kakao sniger sig ind. Serveringsforslag : En blæret rom til cocktails – prøv den fx i en Mai Tai eller bare et ordentligt skvæt i tropisk frugtjuice.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Black Cask 2024 Barbados & Paraguay', 'https://www.juuls.dk/rom/varekort/planteray-black-cask-2024-barbados-paraguay', 379, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641027.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641027-Planteray-Black-Cask-2024-Barbados-&-Paraguay.jpg', 'Black Cask er en af Planterays mest elskede aftapninger, og med årets udgivelse kan Black Cask-serien fejre 10-års jubilæum! Derfor er det også en særlig godte i år: Rommen er en blanding af Barbados-rom fra West Indies Rum Distillery – Planterays eget – og en lettere usædvanlig komponent fra Fortín, et destilleri i Paraguay. De to dele lagres ved deres respektive destillerier i en årrække, før de skibes til Frankrig og får Planterays luksusbehandling: en ekstra lagring på 350-liter Ferrand-fade. Den tappes med en dosage på 19 gram per liter, så der er tale om en blød og sødmefuld rom i bedste Black Cask-stil. Farve : Rav. Duft : Mange nuancer af tropisk frugt, karamel, kokos, vanilje og ristede hasselnødder. Smagsnoter : Rund, frugtig og sødmefuld, med krydrede noter af ingefær, melasse, kaffe og mælkechokolade. Serveringsforslag : Kan nydes rent eller i drinks og cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Blanc', 'https://www.juuls.dk/rom/varekort/clement-rhum-blanc', 259, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610100.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610100-Clement-Rhum-Blanc.jpg', 'Clément Rhum Blanc er den helt klassiske hvide agricole-rom. Den har en meget typisk martinikansk karakter med citrus og et urtet, græsagtigt strejf i duften. Fra øjeblikket du hælder den i glasset er du ikke i tvivl om, at det her er agricole! Clément Rhum Blanc er oplagt at bruge i cocktails der kræver en hvid rom med masser af smag og en stærk personlighed. Farve: Klar Duft: En duft af nyslået græs, appelsinblomst og grønne urter; basilikum og oregano Smagsnoter: Sort te, kakaobønner og citrusagtig finish. Serveringsforslag: Prøv den i daiquiris eller den franske klassiker, ti’punch: 6 cl Clément Blanc (eller Vieux) 1 barske rørsukkersirup 1 god skive lime Pres limen i et rocks-glas, tilsæt sukkersirup, rom og isterninger efter smag.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Tres Vieux Rhum Agricole XO', 'https://www.juuls.dk/rom/varekort/rhum-jm-tres-vieux-rhum-agricole-xo', 789, TRUE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614400.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614400-Rhum-JM-Tres-Vieux-Rhum-Agricole-XO.jpg', 'Rhum JM X.O Tres Vieux er en rhum agricole fra Martinique. Den er lavet på frisk sukkerrørssaft og har ligget minimum 6 år på egetræsfade, der før har været brugt til bourbonlagring. Til sidst er den tappet ved ganske fornuftige 45% alkohol. Resultatet er en helt klassisk agricole-rom, der kombinerer det bedste fra den tropiske fadlagring med friske noter af sukkerrør og det martinikanske terroir. Farve: Rav. Duft: Egetræsnoter (brunet smør og vanilje), tørret frugt og ingefær. Smagsnoter: Fyldig og krydret i munden, med noter af ingefær, nødder og hints af vanilje. Serveringsforslag: Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Matusalem Solera 15 Gran Reserva', 'https://www.juuls.dk/rom/varekort/ron-matusalem-solera-15-gran-reserva', 279, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50645610.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50645610-Ron-Matusalem-Solera-15-Gran-Reserva.jpg', 'Ron Matusalem Solera 15 Gran Reserva er en rom fra Dominikanske Republik. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado 15 years', 'https://www.juuls.dk/rom/varekort/el-dorado-15-years', 599, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646320.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646320-El-Dorado-15-years.jpg', 'El Dorado 15 Years Old er en rom fra det sidste overlevende destilleri på Guyana; Diamond Distillery. Rommen her er sammensat af destillater fra flere af deres kedler, blandt andet Port Mourant, Enmore og Versailles. Dette blend giver, sammen med en lidt lavere sukkertilsætning, en væsentligt kraftigere, tørrere og mere krydret smagsoplevelse, end man fx får ved lillebroren 12 Year Old eller storebroren 25 Year Old. Farve:  Rav. Duft:  Mørk og kompleks duft af kaffe, melasse, nelliker og brun farin. Smagsnoter:  Stor smag af brændt eg, varme krydderier, vanilje og sveske. Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Mantuano', 'https://www.juuls.dk/rom/varekort/diplomatico-mantuano', 279, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643342.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643342-Diplomatico-Mantuano.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pura Vida XO Ron', 'https://www.juuls.dk/rom/varekort/pura-vida-xo-ron', 529, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641693.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641693-Pura-Vida-XO-Ron.jpg', 'Costa Ricas nye rom-stjerne! Costa Rica er en af verdens bedste sukkerrørsproducenter, og det udnytter man virkelig her: Pura Vida XO er lavet på både melasse, sugarcane honey og frisk sukkerrørssaft. Den er lagret primært i Costa Rica på bourbonfade, og får en finish på gamle cognac tuns. En fyldig og kompleks rom for både kendere og nybegyndere. Farve : Rav. Duft : Rig duft af crème brûlée og karamel, ingefær, ananas og banan. Smagsnoter : Silkeblød med intense noter af brændt sukker, tropisk frugt, nellike og cedertræ. Serveringsforslag : Bør nydes rent eller i gode romcocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray XO 20th Anniversary', 'https://www.juuls.dk/rom/varekort/planteray-xo-20th-anniversary-2', 1049, TRUE, 175, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648072-Planteray-XO-20th-Anniversary.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Gran Anejo Guatemala Belize No Giftbox', 'https://www.juuls.dk/rom/varekort/planteray-gran-anejo-guatemala-belize-no-giftbox', 359, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641073.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641073-Planteray-Gran-Anejo-Guatemala-Belize-No-Giftbox.jpg', 'Planteray Grand Añejo er et klassisk mellemamerikansk blend af rom fra Guatemala og rom fra Belize, som efter mellem 3 og 6 år på bourbonfade i troperne lærer hinanden at kende på franske egetræsfade i Cognac. Med blandingen af mellemamerikansk charme og fransk raffinement er Grand Añejo en poleret og let drikkelig sipping-rom som også gør sig godt i cocktails.  Farve : Dyb kobber. Duft : Duften er proppet med vanilje, pærer og grønne æbler. Smagsnoter : Cremet smag af bagt æble, karamelsovs og bittersød melasse. Serveringsforslag : En rom som kan nydes rent, men som også har mange anvendelsesmuligheder i cocktails, fx rum swizzles, punches eller hot buttered rum!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Great House Distillery Edition 2025', 'https://www.juuls.dk/rom/varekort/hampden-great-house-distillery-edition-2025', 1189, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643821.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643821-Hampden-Great-House-Distillery-Edition-2025.jpg', 'Hampden Estate frigiver hvert år en ny udgave af deres populære ”Great House” – en hyldest til den grandiose, gamle residens bygget i 1779, som stadig står på grunden. Førstesalen blev brugt til opbevaring af rom indtil 1900-tallet. I dag er huset her, man tager imod gæster og romnørder, som har taget pilgrimsrejsen til Jamaica . Rommen er 100% tropisk lagret, pot still rom (en blanding af forskellige marks). Tappet ved 57% alkohol. Der er som sædvanlig en begrænset mængde tilgængelig. Farve : Dyb gylden. Duft : Tæt og rig med noter af fermenteret ananas, vanilje og kandiseret ingefær. Smagsnoter : Intens rom med masser af tropisk frugt, især banan, lakrids og et touch af chili. Lag, kompleks og krydret eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Vieux Agricole XO', 'https://www.juuls.dk/rom/varekort/clement-rhum-vieux-agricole-xo', 729, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610610.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610610-Clement-Rhum-Vieux-Agricole-XO.jpg', 'Clément XO er en del af Cléments ”Grand Reserve”-serie, som dækker over destilleriets ældre og mere eksklusive aftapninger. Rommen bærer betegnelsen XO, som efter Martiniques AOC-forskrifter betyder, at den er lagret minimum 6 år. I dette tilfælde er der tale om både ”virgin” (ubrugte) fade, og brugte, re-charred fade. Rommen er naturligvis lavet på frisk sukkerrørssaft. Farve: Rav Duft: Modne æbler og ægte kanel ledsages af en diskret røget note af forkullet træ. Smagsnoter: Rommen er meget elegant i munden, med noter af vanilje, lakrids og hvid peber. Serveringsforslag: Bør drikkes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Single Cask Joie de Vivre 16 Ans', 'https://www.juuls.dk/rom/varekort/clement-rhum-single-cask-joie-de-vivre-16-ans', 789, TRUE, 50, 44, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50611834.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50611834-Clement-Rhum-Single-Cask-Joie-de-Vivre-16-Ans.jpg', 'Clément Rare Cask Collection ”Joie de Vivre” er den første af 3 nye single casks fra Clément tappet udelukkende til Danmark. Navnet betyder ”livsglæde” – en garanteret følgevirkning af at indtage disse sjældne dråber. Rommen er lagret hele 16 år og 4 måneder under tropiske forhold og det har givet en utrolig kompleksitet. Joie de Vivre er tappet ved 44% alkohol, som er den styrke man ser på de gamle, legendariske Clement-aftapning som fx 1952, 1970 og 1976. På trods af den ”lave” styrke savner man absolut ikke intensitet eller dybde i hverken duft eller smag! Flasken kommer i øvrigt i en flot original trækasse. Farve: Dunkel bronze - overraskende mørk! Duft: En berusende og dybt fascinerende duft af lak, tobak og kaffe. Der er også en syrlig fornemmelse af limeskal og syltede pærer. Desuden noter af sandeltræ, salmiak og pistacienødder. Smagsnoter: I munden er rommen blødere end man skulle tro ud fra den superintense næse. Stadig en behagelig syrlighed, sød lakrids, sort te og et strejf af mentol i eftersmagen. Serveringsforslag: Bør nydes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Vieux Rhum Rhum Agricole VSOP', 'https://www.juuls.dk/rom/varekort/rhum-jm-vieux-rhum-rhum-agricole-vsop', 559, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614100.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614100-Rhum-JM-Vieux-Rhum-Rhum-Agricole-VSOP.jpg', 'Rhum JM VSOP er en 4 år gammel agricole-rom fra Martiniques mindste ”rhumerie”, beliggende for foden af vulkanen Mont Pelée. Denne aftapning hviler først en kort periode på ståltanke efter destillationen, dernæst lagres den 3 år på brugte bourbonfade og afslutningsvis cirka et år i nye, amerikanske egetræsfade. En fin forening af ”græssede” agricole-noter og fadpræg. Farve: Lys mahogni. Duft: Meget aromatisk: grillede citroner, nellike, kanel og brændende græs. Smagsnoter: Blød nougat, egetræ, mørkristet kaffe og toffee. Serveringsforslag: God at nyde rent eller som erstatning for bourbon i en Old Fashioned.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau Rhum VSOP', 'https://www.juuls.dk/rom/varekort/damoiseau-rhum-vsop', 409, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50616250.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50616250-Damoiseau-Rhum-VSOP.jpg', 'Damoiseau Rhum VSOP er en rom lavet på frisk sukkerrørssaft og lagret minimum 4 år på bourbonfade. Guadeloupes varme og fugtige klima giver en væsentligt hurtigere modning end man har i fx Europa, og allerede efter 4 år har denne rhum agricole fået masser af smag fra fadet, der er perfekt balanceret med destillatets frugtighed. Farve:  Mørk gylden. Duft:  Meget frisk i duften med ananas og appelsiner  galore . Smagsnoter:  Banan, vanilje, peanut butter og sirup med en lang, tør finish. Serveringsforslag:  Bør nydes rent eller i enkle cocktails', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Nicaragua DK 12 years NS10', 'https://www.juuls.dk/rom/varekort/cdi-nicaragua-dk-12-years-ns10', 939, TRUE, 70, 66, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640900.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640900-CDI-Nicaragua-DK-12-years-NS10.jpg', 'Compagnie des Indes Nicaragua 12 Years #NS10 er en single cask fra et hemmeligt nicaraguansk destilleri (en oplagt anledning til at øve sin google-fu). Rommen er efter 12 års lagring tappet ved en fadstyrke der, traditionen tro for CDIs Nicaragua-rom, er tårnhøj! Den holder 66%, så vær ikke bange for at eksperimentere med vand og pipette. Farve: Gylden. Duft: Kaffe, vanilje og noter af tropisk frugt. Smagsnoter: Toffee, brændt toast og papaya. Serveringsforslag: Nydes rent, men tilsæt gerne et par dråber køligt vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kaniche Reserve', 'https://www.juuls.dk/rom/varekort/kaniche-reserve', 289, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641450.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641450-Kaniche-Reserve.jpg', 'Kaniché Reserve er en rom fra Barbados, lagret først i Barbados’ tropiske klima på bourbonfade af amerikansk hvid-eg, og dernæst i det kontinentale Frankrig i gamle cognacfade. Med denne metode - Pierre Ferrands yndede ”élevage” - forfines den ungdommelige rom med raffinerede noter fra en langsom modning på de franske fade. Farve: Mørk rav Duft: En overflod af vanilje, pistacie og Key Lime Pie. Smagsnoter:   Ristede nødder, orangeblomst og macarons. Serveringsforslag: Nydes rent eller i klassiske cocktails', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Dictador 20 Years Solera System Rum', 'https://www.juuls.dk/rom/varekort/dictador-20-years-solera-system-rum', 499, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641810.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641810-Dictador-20-Years-Solera-System-Rum.jpg', 'Dictador 20 Years Solera System Rum er en rom fra Colombia. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Du kan forvente en flot fyldighed og noter af især lakrids, kaffe og Chokolade. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Seleccion de Maestros', 'https://www.juuls.dk/rom/varekort/havana-club-seleccion-de-maestros', 459, TRUE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643850-Havana-Club-Seleccion-de-Maestros.jpg', 'Seleccion de Maestros er en del af Havana Clubs ”Iconica”-serie. Fadene, der indgår i denne cubanske rom, er særligt udvalgt af Havana Clubs ”Guild of Masters of Cuban Rum”. Præcis hvor længe eller hvordan, den er lagret, forbliver, i vanlig cubansk stil, hemmeligt, men Havana Club nævner dog, at den er ”Triple Barrel Aged”. Desuden er Seleccion de Maestros tappet ved en højere styrke, end de fleste andre fra Havana Club: 45%. Farve:  Rav. Duft:  Dyb og mørk duft, med masser af melasse, nærmest lidt røgede noter af brændt eg, tobak og læder. Smagsnoter:  Brun farin, egetræ, vanilje og mørke krydderier. Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Mount Gay Eclipse Rum', 'https://www.juuls.dk/rom/varekort/mount-gay-eclipse-rum', 209, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644200.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644200-Mount-Gay-Eclipse-Rum.jpg', 'Mount Gay Rum er en rom fra Barbados. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Smagen er mellemkraftig med noter af specielt kokos og vanilje. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate Reserve Blend 8yo', 'https://www.juuls.dk/rom/varekort/appleton-estate-reserve-blend-8yo', 359, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644355.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644355-Appleton-Estate-Reserve-Blend-8yo.jpg', 'Appleton Estate Reserve Blend er en lagret rom fra Jamaica. Dette blend er sammensat af master blender Joy Spence, som udvælger fade med minimum 8 år gammel rom, både fra pot- og kolonne-kedler. Den er lavet på melasse og lagringen foregår på amerikansk hvideg. Tappet ved 43% alkohol uden tilsat sukker. Farve : Topas. Duft : Flot krydret og nøddeagtig duft: honning, hasselnød, egetræ og vanilje. Smagsnoter : Appelsin, banan, hasselnødder og vanilje. Enormt flot, ”aristokratisk” Jamaica-rom med både finesse og fylde. Serveringsforslag : Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado 8 years', 'https://www.juuls.dk/rom/varekort/el-dorado-8-years', 279, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646300.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646300-El-Dorado-8-years.jpg', 'El Dorado 8 Years Old er en rom fra Guyana. Rommen er lagret på bourbonfade i minimum 8 år, og den er sammensat af destillater fra Demerara Distillers’ forskellige destillationsapparater. Det er særligt Enmore, en coffey-still af træ, som producerer en meget smagfuld rom, der dominerer i blendet. En forrygende ”all-round” der både kan drikkes rent og i cocktails. Farve : Rav. Duft : Mørk chokolade og tørret frugt. Smagsnoter : Fin kompleksitet for en relativt ung og billig rom. Noter af rosin, banan, peber og chokolade. Serveringsforslag : Kan nydes rent eller i cocktails. Prøv den for eksempel i en Rum Old Fashioned.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ypioca Cachaca Prata', 'https://www.juuls.dk/rom/varekort/ypioca-cachaca-prata', 209, TRUE, 70, 38, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646900.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646900-Ypioca-Cachaca-Prata.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Atelier Fumée Volcanique', 'https://www.juuls.dk/rom/varekort/rhum-jm-atelier-fumee-volcanique', 459, TRUE, 70, 49, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614070.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614070-Rhum-JM-Atelier-Fumée-Volcanique.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Atelier Jardin Fruité', 'https://www.juuls.dk/rom/varekort/rhum-jm-atelier-jardin-fruite', 429, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614080.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614080-Rhum-JM-Atelier-Jardin-Fruité.jpg', 'Rhum JM L’Atelier des Rhums Jardin Fruité er en rhum agricole fra Martinique. Denne nye udgivelse fra JM består af 2 år gammel rom, lagret på både amerikansk og fransk eg. Den er én af 3 udgivelser i Atelier-serien, og som navnet antyder, er den ganske rigtigt præget af frugtige og eksotiske noter. Et flot glas rom til en meget attraktiv pris! Farve:  Gylden. Duft:  Flot duft af ananas, banan, vanilje, sukkerrørssaft og egetræ. Smagsnoter:  Elegant og frugtig. Ligger let og smidigt på tungen, igen med noter af tropisk frugt, vanilje og muskatnød. Serveringsforslag:  Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Atelier Epices Créoles', 'https://www.juuls.dk/rom/varekort/rhum-jm-atelier-epices-creoles', 479, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614090.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614090-Rhum-JM-Atelier-Epices-Créoles.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Stroh (80)', 'https://www.juuls.dk/rom/varekort/stroh-80-1', 189, TRUE, 50, 80, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50647105.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50647105-Stroh-(80).jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Alegre XO', 'https://www.juuls.dk/rom/varekort/ron-alegre-xo', 519, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644090.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644090-Ron-Alegre-XO.jpg', 'Ron Alegre XO er en rom fra Den Dominikanske Republik. Den har tilbragt intet mindre end 10 år på fade af amerikansk eg, der inden da har indeholdt vores yndlingshedvin, sherry. Fra sherryen får Alegre de lækre noter af tørret frugt og mørk karamel. Det er en rom med den perfekte blanding af modenhed, sødme og friskhed, hvilket hurtigt har gjort den til en favorit hos os. Farve : Mahogni. Duft : Kirsebær i sirup, blomme og brændt sukker. Smagsnoter : De samme noter fra duften fortsætter, ledsaget af tørret frugt og lune karamelnoter. På tungen er der klart en gammel roms raffinement, men også en friskhed og så den perfekt afstemte alkohol, der indbyder til endnu en tår. Og endnu en… Serveringsforslag : Nyd den rent, helst i godt selskab.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Guyana Armagnac Cask Finish High Proof Denmark', 'https://www.juuls.dk/rom/varekort/cdi-guyana-armagnac-cask-finish-high-proof-denmark', 939, TRUE, 70, 61.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640926.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640926-CDI-Guyana-Armagnac-Cask-Finish-High-Proof-Denmark.jpg', 'Demerara-rom lagret på armagnac-fade er usædvanligt, men aftapperen Compagnie des Indes er jo fransk, så hvis nogen skulle gøre det, må det være Florent og Compagnie! Inden de 36 måneders affinage på armagnac-fadet, har rommen ligget på bourbonfad i 11 år. Den er tappet ved 61,2% uden tilsat sukker eller kølefiltrering. Fadet, som havde nummer GDA61, gav i alt 479 flasker og selvom det ikke står på etiketten, er den tappet udelukkende til det danske marked! Farve : Gammelt guld. Duft : Duften er ikke tung og dyster, men overraskende frisk bag den kraftige alkohol (den er 61%!) med noter af citronmelisse, kastanjecreme, brændt sukker, tørrede blomster og urter (mynte). Smagsnoter : Tør og powerful i starten, men udvikler så lidt mere sødmefulde noter af honningkage, nybagt brød, kardemomme og ristede kastanjer. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Le Must', 'https://www.juuls.dk/rom/varekort/savanna-le-must', 629, TRUE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615435.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615435-Savanna-Le-Must.jpg', 'Savanna Le Must er en rom fra La Réunion, der kombinerer to stilarter fra Savanna: traditionnel og den kraftige grand arôme . Le Must er et blend af de to slags rom, lagret op til 9 år i tropisk klima. En kompleks og spændende rom, der udtrykker Savannas identitet og vil tiltale både nørderne og nybegyndere. Rommen er tappet ved 45% og er ikke tilsat sukker. Farve : Mørkt rav. Duft : Skøn, udtryksfuld duft af saftig, moden pære, banan og kakaonibs. Smagsnoter : Flot balance mellem det frugtige og krydrede. Noter af tropisk frugt, honning og chokoladeganache. Serveringsforslag : Vi anbefaler at den nydes rent – men den er nu også fremragende i cocktails, hvis du nænner det.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Don Gustavo Limited Edition Extra Anejo', 'https://www.juuls.dk/rom/varekort/ron-don-gustavo-limited-edition-extra-anejo', 499, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643462.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643462-Ron-Don-Gustavo-Limited-Edition-Extra-Anejo.jpg', 'Diaz de Vivar Don Gustavo er mesterstykket fra Ron Fortin i Paraguay, lavet som limited edition for at fejre virksomhedens 25-års jubilæum. Den gæres og destilleres på frisk sukkerrørssaft og lagres i alt 12 år på fad: de første 10 på barriques af fransk eg og dernæst 2 år på sherryfade. Farve : Rav. Duft : Krydrede noter af vanilje, rosin, sor te og muskatnød. Smagsnoter : Mediumfyldig, elegant og med en lang finish. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Barbados Foursquare FBD14 Btld for DK 2022', 'https://www.juuls.dk/rom/varekort/cdi-barbados-foursquare-fbd14-btld-for-dk-2022', 1049, TRUE, 70, 57.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640936.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640936-CDI-Barbados-Foursquare-FBD14-Btld-for-DK-2022.jpg', 'Vi har tappet to søsterfade fra samme batch , fordi vi ved I bare elsker Barbados rom fra Foursquare destilleriet. Rommen er lige efter bogen og fyldt med masser noter af kokos, vanilje, orange og mørk chokolade, samt sprøde toffee noter. Yderst behageligt bekendtskab. Rommen er tappet ved fuld fadstyrke, uden tilsætning af sukker eller farve, eksklussivt til det danske marked. Farve : Mørk. Duft : Behagelig krydret duft. Smag : Powerfuld med noter af kokos, vanilje, orange og mørk chokolade, samt sprøde toffee noter. Serveringsforslag : Bør nydes rent. Se søsterfadet  CDI Barbados Foursquare FBD15 Btld for DK 2022 .', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sepé Ron Anejo ØKO', 'https://www.juuls.dk/rom/varekort/sepe-ron-anejo-oeko', 199, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643469.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643469-Sepé-Ron-Anejo-ØKO.jpg', 'Sepé Ron Añejo er en ung rom fra Paraguay. Den er lavet på frisk sukkerrørssaft, som koges ind til sirup inden den gæres og destilleres på kolonnekedel. Herefter lagres rommen 2 år på bourbonfade i Paraguays subtropiske klima. Den tappes uden tilsat sukker eller farvestof i en flaske, som faktisk fortjener sin egen lille introduktion. Mens det meste af rommen i vores sortiment er tappet enten ved destilleriet eller hos en såkaldt ”uafhængig aftapper”, så er Sepé tappet lige her i Danmark, nærmere bestemt på Oremandsgaard. Rommen blev sendt hertil i tank, for så at komme på en ”wild glass”-flaske, som er den mest bæredygtige, vi kunne finde (100% post consumer recycled glass), stoppet med en Corkcoal-prop, som også er mere bæredygtig end normale korkpropper og til sidst etiketteret med genbrugspapir. Farve : Svagt gylden. Duft : Spændende og anderledes duft af grapefrugt, agave og limejuice, varme sten og nærmest lidt røg.  Smagsnoter : Rommen er let og tør på tungen, præget af friske sukkerrørsnoter og citrus. Slutter med det mindste strejf af smeltende rørsukker. Serveringsforslag : En oplagt rom til cocktails – den vil virkelig gøre det godt både i daiquiris og diverse tiki-drinks.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Renegade Rum 2020', 'https://www.juuls.dk/rom/varekort/habitation-velier-renegade-rum-2020', 989, TRUE, 70, 55, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643693.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643693-Habitation-Velier-Renegade-Rum-2020.jpg', 'Renegade er Grenadas nyeste romdestilleri, og med Mark Reynier fra Bruichladdich på holdet, ved man, at de har styr på destillationen. Men kan de også lave rom? Svaret er ja, det kan de i dén grad. Og der findes næppe noget større skulderklap for et nyt romdestilleri , end at få sin rom tappet under den fane, der hedder Habitation Velier. Luca Gargano har udvalgt en 3 år gammel rom fra 2020, tappet ved fadstyrke (55%) – selvfølgelig uden sukker tilsat. Farve : Gylden. Duft : Noter af honning, mint, vaniljestænger og mørk chokolade. En skøn duft. Smagsnoter :  Tæt og cremet på tungen, med rimeligt fyldige noter af varme krydderier (kardemomme, ingefær, kanel) tropisk frugt og et touch af noget floralt. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Seleccion de Familia', 'https://www.juuls.dk/rom/varekort/diplomatico-seleccion-de-familia', 499, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643365.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643365-Diplomatico-Seleccion-de-Familia.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Single Vintage 2008', 'https://www.juuls.dk/rom/varekort/diplomatico-single-vintage-2008', 999, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643394.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643394-Diplomatico-Single-Vintage-2008.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Merser Reserve Rum Aged for up to 8 Years', 'https://www.juuls.dk/rom/varekort/merser-reserve-rum-aged-for-up-to-8-years', 319, TRUE, 70, 40.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642200.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642200-Merser-Reserve-Rum-Aged-for-up-to-8-Years.jpg', 'Merser Reserve er en rund, blød og fyldig rom lavet på et blend af caribiske og sydamerikanske destillater, lagret op til 8 år og hvilet 6 uger i London. En perfekt rom at nyde over is eller i cocktails! Farve : Rav. Duft : Skøn duft af karamel og honning med hints af varme krydderier, tørret ananas og rosin. Smagsnoter : Blød og rund med en god sødme og noter af chokolade, tørret frugt og vanilje. Serveringsforslag : Nyd den over is eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate 1753', 'https://www.juuls.dk/rom/varekort/hampden-estate-1753', 629, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643692.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643692-Hampden-Estate-1753.jpg', 'Hampden Estate 1753 er det nyeste skud på stammen hos det gamle destilleri på Jamaica. Rommen er navngivet efter året for destilleriets grundlæggelse – det er det ældste på øen! Og tingene har ikke ændret sig ret meget: de bruger stadig kobber-pot stills, naturligt gær, fuld tropisk lagring og nul sukker. 1753 er lagret 3 år, og har et højt ”ester-niveau”, som Hampden jo er særligt kendt for. En perfekt introduktion til destilleriets unikke stil! Farve : Lyst rav. Duft : Umiskendelig Hampden-profil med overmoden, tropisk frugt, muskatnød, maskinrum og citrus. Smagsnoter : Potent rom, som bærer de 46% rigtig flot. Varme krydderier, et let vaniljestrejf og løftede noter af mango, ananas og banan. Serveringsforslag : Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Black Cask 2025 Barbados & Trinidad', 'https://www.juuls.dk/rom/varekort/planteray-black-cask-2025-barbados-trinidad', 379, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641028.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641028-Planteray-Black-Cask-2025-Barbados-&-Trinidad.jpg', 'Planteray Black Cask 2025 er landet! I år er rommen en blanding af Barbados og Trinidad, som først lagres i Caribien på fade af amerikansk hvideg, og følgende efterlagres på små fade i Cognac, som har en højere grad af ”toasting” end normalt, hvorfra den får en ganske let røget note. Det er denne særlige lagring, navnet ”Black Cask” kommer fra. Rommen er tilsat 19 gram sukker per liter, og fremstår derfor blød, rund og behageligt sødmefuld, men stadig med masser af personlighed. Farve : Rav. Duft : En duft af tropisk frugt med nuancer af krydderier, karamel, kokos, vanilje og hasselnødder. Smagsnoter : Rund, frugtig og med god sødme, masser af melasse, rosin, frugt og et strejf af kaffe. Serveringsforslag : Nyd den rent eller over is.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Gran Anejo Guatemala Belize Giftbox', 'https://www.juuls.dk/rom/varekort/planteray-gran-anejo-guatemala-belize-giftbox', 359, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641072-Planteray-Gran-Anejo-Guatemala-Belize-Giftbox.jpg', 'Planteray Grand Añejo er et klassisk mellemamerikansk blend af rom fra Guatemala og rom fra Belize, som efter mellem 3 og 6 år på bourbonfade i troperne lærer hinanden at kende på franske egetræsfade i Cognac. Med blandingen af mellemamerikansk charme og fransk raffinement er Grand Añejo en poleret og let drikkelig sipping-rom som også gør sig godt i cocktails. Farve :  Dyb kobber. Duft : Duften er proppet med vanilje, pærer og grønne æbler. Smagsnoter : Cremet smag af bagt æble, karamelsovs og bittersød melasse. Serveringsforslag : En rom som kan nydes rent, men som også har mange anvendelsesmuligheder i cocktails, fx rum swizzles, punches eller hot buttered rum!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Grenada Distillers Ping 17', 'https://www.juuls.dk/rom/varekort/planteray-grenada-distillers-ping-17', 1559, TRUE, 70, 58.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404483.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404483-Planteray-Grenada-Distillers-Ping-17.jpg', 'Som mange af jer nok ved, er Ping -prædikatet garanti for en særligt god kvalitet. Serien startede i 2005 og indtil videre har 16 aftapninger vist sig værdige til at bære navnet. Her er den 17. Fadet er valgt vores kyndige romeksperter, Max Scott og Jakob Bunch, i januar 2025. Der er tale om en sjælden rom fra Grenada Distillers, melassebaseret og destilleret på kolonne før 13 års lagring på bourbonfade i Grenada og 1 år på cognacfade i Frankrig. Det er måske den bedste Grenada-rom, vi har smagt! Tappet uden tilsat sukker eller farvestof og ved 58,3% alkohol. Farve : Rav. Duft : Stor, intens duft af tropisk frugt, muskatnød, vaniljestænger og ingefær. Smagsnoter : En smagsbombe! Enormt fyldig og frugtig karakter, nærmest lidt agricole-agtig, med en lang, kompleks eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Barbados 5 years', 'https://www.juuls.dk/rom/varekort/planteray-barbados-5-years-1', 699, TRUE, 175, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641041-Planteray-Barbados-5-years.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Jamaica - Rum from Molasses - Jamaica Navy Strength', 'https://www.juuls.dk/rom/varekort/cdi-jamaica-rum-from-molasses-jamaica-navy-strength', 449, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640559.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640559-CDI-Jamaica---Rum-from-Molasses---Jamaica-Navy-Strength.jpg', 'En vaskeægte Jamaica-rom fra Compagnie des Indes, lavet på melasse og destilleret på både pot stills og column stills, før 4 års modning på bourbonfade. Tappet ved 57% - såkaldt ”navy strength” – uden kølefiltrering. Farve : Lyst rav. Duft : En gavmild duft af moden banan, kandiseret frugt, nougat og ananas. Smagsnoter : Fyldig og potent rom, der emmer af Jamaica-funk: overmoden tropefrugt, syrlig chokolade og en lang eftersmag. Serveringsforslag : Nyd den rent eller som trumf i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairman''s Reserve Vintage 2011 Limited Ed.', 'https://www.juuls.dk/rom/varekort/chairmans-reserve-vintage-2011-limited-ed', 669, TRUE, 70, 46.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615734.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615734-Chairman''s-Reserve-Vintage-2011-Limited-Ed..jpg', 'Top-aftapningen hos Chairman''s Reserve er en vintage rom, der frigives løbende. Den nuværende årgang hedder 2011, og rommen repræsenterer alt det, vi godt kan lide ved St. Lucia: power, kompleksitet, dybde og typicitet. De laver bare ikke rom, som det her, andre steder... Rommen er lagret på bourbonfade ved destilleriet og er tappet ved 46,8% uden tilsat sukker. Farve : Lys mahogni. Duft : En potent sag, der nærmest eksploderer op af glasset med karamelliseret banan, toffee, vaniljestænger, tobak og rosin. Smagsnoter : Fyldig, tung og kompleks. Rommen er tør, men føles cremet i munden med noter af tropisk frugt, læder, honning og mørk chokolade. Uendeligt lang eftersmag. Serveringsforslag : Nyd den rent, evt. som avec efter et godt måltid.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier Foursquare Indomitas', 'https://www.juuls.dk/rom/varekort/velier-foursquare-indomitas-1', 1795, TRUE, 70, 62, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643664.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643664-Velier-Foursquare-Indomitas.jpg', 'Dette produkt er ekskluderet fra alle rabatkoder. Max 1 fl. per kunde. Indomitas er navnet på den nyeste rom i samarbejdet mellem Richard Seale fra Foursquare Distillery og Luca Gargano fra Velier. Flaskerne er nogle af rommarkedets mest eftertragtede, og Indomitas er endnu en exceptionel tilføjelse. Rommen er en blanding af to forskellige rom fra Foursquare: den ene del er destilleriet på en pot-still og er lagret 15 år på bourbonfade. Den anden del er fra en kolonnekedel, og den er lagret 6 år på bourbonfade og 9 år på cognacfade. Til sidst er de to komponenter blandet og tappet ved 62% alkohol. Der er lavet i alt 4.800 flasker. Farve : Rav. Duft : Tørret frugt, nødder, citrus og toastet eg. Bag ved karamel og moden stenfrugt. Smagsnoter : Højintens rom med velkendte Barbados-noter af ristet kokos og kandiseret frugt med kakao, peber og ædeltræ i eftersmagen, som er imponerende lang. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Jamaica Long Pond STCE Vintage 1995 Juuls 100th Anniversary', 'https://www.juuls.dk/rom/varekort/planteray-jamaica-long-pond-stce-vintage-1995-juuls-100th-anniversary', 2579, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404484.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404484-Planteray-Jamaica-Long-Pond-STCE-Vintage-1995-Juuls-100th-Anniversary.jpg', 'Planteray har disket op med et ekstraordinært godt fad i anledning af Juul’s Vin og Spiritus’ 100-års jubilæum! Der er tale om en gammel Jamaica-rom fra de fjerne halvfemsere – nærmere bestemt en såkaldt STCE fra Long Pond Distillery destilleret i 1995: en fyldig og intens sag, som er lagret 23 år på bourbonfad i troperne og 8 år på Ferrands fade i Europa. Den holder 52% alkohol. Farve : Mahogni. Duft : Den helt rigtige duft af overmoden tropefrugt: mango, ananas og banan, men også de mørke noter af kaffe, ristet kokos og cedertræ. Smagsnoter : Tung Jamaica, når det er bedst! En lang og drøj smag, der gemmer varme krydderier, lakrids, mango og et touch af røg. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Eminente Ambar Claro', 'https://www.juuls.dk/rom/varekort/eminente-ambar-claro', 359, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643953.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643953-Eminente-Ambar-Claro.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Fiji Vintage 2012 Oceana Series', 'https://www.juuls.dk/rom/varekort/planteray-fiji-vintage-2012-oceana-series', 599, TRUE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641200.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641200-Planteray-Fiji-Vintage-2012-Oceana-Series.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Australia Vintage 2016 Oceana Series', 'https://www.juuls.dk/rom/varekort/planteray-australia-vintage-2016-oceana-series', 679, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641201.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641201-Planteray-Australia-Vintage-2016-Oceana-Series.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Mauritius Vintage 2014 Oceana Series', 'https://www.juuls.dk/rom/varekort/planteray-mauritius-vintage-2014-oceana-series', 649, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641202.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641202-Planteray-Mauritius-Vintage-2014-Oceana-Series.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Multivintage', 'https://www.juuls.dk/rom/varekort/rhum-jm-multivintage', 629, TRUE, 50, 42.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614903.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614903-Rhum-JM-Multivintage.jpg', 'Rhum JM Multivintage er en rom sammensat af destillater fra 3 årgange – 2002, 2007 og 2009. Der er som sådan ikke noget usædvanligt i, at man blander årgange – til gengæld er det sjældent at de opgives på etiketten. Disse årgange ”giftes” i store fade hvor de ligger et stykke tid så det endelige blend bliver balanceret og integreret. Fælles for dem alle er, at de er lavet på frisk sukkerrørsjuice og oprindeligt lagret på bourbon barrels. Farve: Dyb gylden. Duft: En fornemmelse af vanilje, appelsin, svesker og tobak. Smagsnoter: Relativt tør i smagen med et let bid af tannin, noter af ristede nødder, tørret frugt og en snert af mentol. Serveringsforslag: Drikkes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Creol Blanc 52', 'https://www.juuls.dk/rom/varekort/savanna-creol-blanc-52', 479, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615448.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615448-Savanna-Creol-Blanc-52.jpg', 'Savanna Creol Blanc er en rom fra øen La Réunion, lavet på frisk sukkerrørssaft og destilleret på kolonnekedler. En relativt kort gæring, som forløber over 2 dage, betyder, at denne rom ikke er den mest funky i Savannas sortiment, men stadig med masser af karakter. Den er tappet ved 52% alkohol, og der er kun lavet 2800 flasker af denne aftapning. Farve: Klar. Duft: Flot, grøn duft af anis, safran, vanilje og sukkerrørssaft. Smagsnoter: Livlig, krydret og let sødmefuld, med peber, sukkerrørssaft, oliven og tropisk frugt. Serveringsforslag: Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Fiji South Pacific DK 11 Years Cask no. SF15', 'https://www.juuls.dk/rom/varekort/cdi-fiji-south-pacific-dk-11-years-cask-no-sf15', 989, TRUE, 70, 66.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640886.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640886-CDI-Fiji-South-Pacific-DK-11-Years-Cask-no.-SF15.jpg', 'Compagnie des Indes South Pacific 11 Years Old er en rom fra en af de fremspirende stjerner på romscenen, Fiji. Her kan stilen minde om Jamaica- eller St. Lucia-rom, men kan også have agricole-agtige noter. Rommen er lavet på melasse og lagret på bourbonfade, og denne flaske er tappet ved en formidabel alkoholprocent – 66,8% - så hav gerne lidt vand og en brandslukker klar… Farve: Gylden. Duft: Kraftig alkohol, ingen tvivl om det! Noter af citronskal og kandiseret appelsin, sesamfrø, grønt græs og æble. Smagsnoter: Cremet smag med græsk yoghurt, gurkemeje, havvand, kanel og melasse. Serveringsforslag: Bør drikkes rent – men tilsat gerne et par dråber vand!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Nicaragua DK 17 Years Cask no NCR 30', 'https://www.juuls.dk/rom/varekort/cdi-nicaragua-dk-17-years-cask-no-ncr-30', 1449, TRUE, 70, 64.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640893.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640893-CDI-Nicaragua-DK-17-Years-Cask-no-NCR-30.jpg', 'Compagnie des Indes Nicaragua 17 Years Cask #NCR30 er endnu en enkeltfadstapning fra Florent Beuchet der kun er tilgængelig i Danmark. Denne er fra et ”hemmeligt” destilleri i Nicaragua, men er du en dygtig googler burde gåden kunne løses. Dette fad er tappet ved en styrke, 64,9%, der kun er en anelse mere civiliseret end lillebroren fra fad #SN18. Farve: Gylden. Duft: Melon, vindruer, grønne bananer og et hint af kokos. Smagsnoter: En let mundfølelse med noter af karamel, appelsinsaft, nelliker og dåsefersken. Serveringsforslag: Nydes rent – evt. med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kaniche Perfeccion Panama', 'https://www.juuls.dk/rom/varekort/kaniche-perfeccion-panama', 569, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641520.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641520-Kaniche-Perfeccion-Panama.jpg', 'I modsætning til de andre rom fra Kaniché-serien kommer Perfeccion ikke fra Barbados, men fra Panama. Den er en anelse mindre sødmefuld og har lidt mere dybde og kant, om end vi stadig befinder os i den lette ende af rom-spektret. Kaniché Perfeccion er melasse-baseret og destilleret på kolonnestills. En rom med en flot struktur og mundfølelse, og alle de rigtige mellemamerikanske smagsnoter! Farve: Medium rav Duft: Kokosblomstsukker, hibiscus og julekrydderier. Smagsnoter: Let eksotisk frugt, kanel og akaciehonning. Serveringsforslag: Bør drikkes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diamond of Frederiksberg Demerara no 34', 'https://www.juuls.dk/rom/varekort/diamond-of-frederiksberg-demerara-no-34', 1139, TRUE, 70, 57.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642081.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642081-Diamond-of-Frederiksberg-Demerara-no-34.jpg', 'Diamond of Frederiksberg Demerara er en rom fra det legendariske Diamond Distillery i Guyana. Rommen er tappet af Ian MacLeod eksklusivt til Juuls Vin og Spiritus, selvfølgelig ved fuld fadstyrke og uden kølefiltrering. Smagsoplevelsen er enorm og byder på masser af frugt og en tæt, mørk sukkerkarakter. I eftersmagen fornemmes mørke krydderier, lakrids og kraftige, olierede toner. Alt i alt en rom med tyngde og flot kompleksitet. Farve: Mørk melasse. Duft: Karamel, overmoden frugt, gæret sukkerrør, vanilje, kanel og friske bær. Smagsnoter: Kraftfuld, varm og voluminøs karakter med masser af frugtnuancer! En behagelig karamelsødme åbner smagen op og ikke én smagsreceptor går urørt! Serveringsforslag: Nydes rent, evt. med et par dråber vand. Demerara-regionen i Guyana har produceret verdens måske bedste sukker og rom siden starten af 1700-tallet. I over 250 år producerede mere end 300 sukkerplantager, udover gyldent rørsukker og sirup, den fineste rom som blev eksporteret til hele verden. Den engelske flåde var den største aftager af den kraftige mørke rom, fra bl.a. Port Mourant-plantagen, som indgik i den famøse britiske Navy Rum. I dag er de fleste af plantagerne og alle destillerierne desværre borte. Heldigvis lever de bedste destillerier videre i hvad der bedst kan beskrives som et ”levende museum”; Diamond Distillery. Demerara Distillers bragte de bedste af de lukkede plantagedestilleriers produktionsudstyr til Georgetown, hvor der i dag produceres 20 forskellige romstilarter på 9 forskellige gamle kolonne- og pot stills.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Angostura 1919', 'https://www.juuls.dk/rom/varekort/angostura-1919', 309, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643620.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643620-Angostura-1919.jpg', 'Angostura 1919 er en rom fra Trinidad. Den er lavet på melasse. Rommen er tappet ved 40%. Smagen er mellemkraftig med noter af specielt vanilje, varme krydderier, honning og tørret frugt. Nyd den rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Forsyths WPM 2006', 'https://www.juuls.dk/rom/varekort/habitation-velier-forsyths-wpm-2006', 1139, TRUE, 70, 57.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643718.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643718-Habitation-Velier-Forsyths-WPM-2006.jpg', 'Forsyths WPM er en rom fra Jamaica, udvalgt og flasket af den uafhængige aftapper Velier. Rommen har ligget 11 år på bourbonfade i tropisk klima (den kommer fra nogle af de ældste fade i Worthy Parks lager), og er ved destillationen målt til 209 gram estere per hektoliter ren alkohol, hvilket tyder på en pænt smagfuld rom med god chance for masser af klassisk Jamaica-smag. Den er tappet ved fadstyrke: 57,5% alkohol. Farve: Gylden. Duft: Stor aroma af tropisk frugt, oliven, acetone og ingefær. Smagsnoter: Tørret mango, eukalyptus og mentol. Serveringsforslag: Bør nydes rent, evt. med en dråbe vand eller to.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate Rare Blend 12 Year Old', 'https://www.juuls.dk/rom/varekort/appleton-estate-rare-blend-12-year-old', 459, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644360.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644360-Appleton-Estate-Rare-Blend-12-Year-Old.jpg', 'Appleton Estate Rare Blend 12 Year Old er en rom fra Jamaica. Den er lavet på melasse, destilleret på både pot- og kolonnestills og lagret minimum 12 år på amerikanske egetræsfade. Og det er værd at huske, at disse 12 års lagring foregår i Jamaicas tropiske klima, og at denne rom derfor med rette kan betragtes som ”gammel”! Farve:  Bronze. Duft:  Dyb aroma der afslører kakao, tropisk frugt, egetræ og melasse. Smagsnoter:  Smagen er blød, men holder ikke de store frugtnoter af banan og mango tilbage. Bagved fornemmes vanilje, kaffe og brændt eg. Serveringsforslag:  Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Royal', 'https://www.juuls.dk/rom/varekort/ron-zacapa-royal', 2205, TRUE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644755.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644755-Ron-Zacapa-Royal.jpg', 'Med Royal nærmer vi os toppen af Ron Zacapas portfolio. Denne luksuriøse karaffel indeholder rom lagret mellem 8 og 30 år, blandet andet på franske egetræsfade fra ”Le Bois du Roy” – Kongens Træ, makker! Desuden byder Zacapa Royal på en meget velkommen, om end lille, stigning i alkoholprocenten som her rammer 45. Det giver mere bund og mere power. Og det kan vi godt lide. Farve:  Mahogni. Duft:  Smukt krydret duft af nelliker, chokolade, kokos og muskatnød. Smagsnoter:  Fin dybde og kompleksitet, pakket ind i behersket sødme. Tørret frugt og krydderier i eftersmagen, som hænger længe i munden uden at trænge sig på. Serveringsforslag:  Nyd den rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado 21 years', 'https://www.juuls.dk/rom/varekort/el-dorado-21-years', 999, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646330_box.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646330-El-Dorado-21-years.jpg', 'El Dorado 21 Years Old er en rom fra det sidste overlevende destilleri på Guyana; Diamond Distillery. Rommen her er sammensat af destillater fra flere af deres kedler, og særligt deres ”French Savalle still” – en kolonnekedel, man forbinder med Uitvlugt og Albion – spiller en stor rolle i blendet. Kompleksiteten er en tand højere end i mange af de andre udgivelser i serien. Sødmen er der, men er ikke overdøvende. Den er lagret minimum 21 år på fade af amerikansk eg og tappet ved 43% alkohol. Farve:  Rav. Duft:  Dyb duft af valnødder, chokolade og melasse. Smagsnoter:  Smagen fortsætter i rosiner, diverse nødder, muskatnød. Lang eftersmag Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Glens Dark Rum', 'https://www.juuls.dk/rom/varekort/glens-dark-rum', 169, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642386.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642386-Glens-Dark-Rum.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnifica Reserva Soleira Cachaca', 'https://www.juuls.dk/rom/varekort/magnifica-reserva-soleira-cachaca', 759, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646843.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646843-Magnifica-Reserva-Soleira-Cachaca.jpg', 'Blandt de fornemmeste udgivelser fra Magnìfica de Faria finder vi deres  Reserva Soleira.  Denne cachaça er, som noget ganske unikt, lagret i et såkaldt  soleira- system. Denne brasilianske fortolkning af sherryproducenternes lagringsmetode i Andalusien består af otte rækker af fade af amerikansk eg. De øverste fade fyldes med frisk cachaça, som langsomt flyttes til de nedre rækker. Èn gang om året (efter mellem 10 og 14 måneder) tappes halvdelen af fadene i den nederste række og Magnìfica Reserva Soleira ender således med en alder på mindst 6 år, men med dele som er meget ældre. Systemet indeholder stadig cachaça fra 2001! Farve:  Gylden. Duft:  Fed duft af kokos, egetræ og vanilje. Figenstænger, varme krydderier og appelsinskal. Smagsnoter:  Tørret frugt, vanilje og amerikansk eg i smagen. Behagelig sødme og perfekt integreret alkohol. Lang eftersmag. Skønt glas! Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Gelas Panama Old Ron 18y', 'https://www.juuls.dk/rom/varekort/gelas-panama-old-ron-18y', 839, TRUE, 70, 46.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50631100.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50631100-Gelas-Panama-Old-Ron-18y.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate 21 Year Old', 'https://www.juuls.dk/rom/varekort/appleton-estate-21-year-old-1', 1205, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644371.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644371-Appleton-Estate-21-Year-Old.jpg', 'Appleton Estate 21 Year Old er én af de fornemmeste rommer i firmaets portfolio. Master Blender Joy Spence udvælger nøje de fade, som får lov at indgå i denne eksklusive aftapning. De er alle lagret minimum 21 år i Jamaicas tropiske klima, men nogle af komponenterne er også ældre. Den er tappet ved 43% og er ikke tilsat sukker. Farve : Kobber-gylden. Duft : Kraftig men også delikat duft af vanilje, kaprifolie, kakao, kaffe og muskatnød. Smagsnoter : Lang og raffineret smag af brun farin, kakao, vanilje og andre krydderier, et touch af stenfrugt og, langt ude i horisonten, brændt egetræ. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation XO 20th Anniversary 10 cl.', 'https://www.juuls.dk/rom/varekort/plantation-xo-20th-anniversary-10-cl', 89, TRUE, 10, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/70506463.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=70506463-Plantation-XO-20th-Anniversary-10-cl..jpg', '10 sødmefulde centiliter af Plantations smashhit af en rom: XO 20th Anniversary. Den decideret nuttede flaske passer perfekt i inderlommen til en Allan Olsen-koncert eller hvis du skal i Ikea. Du kan læse mere om rommen her', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Captain Morgan White', 'https://www.juuls.dk/rom/varekort/captain-morgan-white', 149, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643565.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643565-Captain-Morgan-White.jpg', 'Captain Morgan White er en spiced rum fra Barbados/Guyana/Jamaica. Den er lavet på sukkerrørsmelasse. En fin smagsoplevelse med noter af vanilje. Kan nydes både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Rhum Vieux Juuls Single Barrel 172972', 'https://www.juuls.dk/rom/varekort/rhum-jm-rhum-vieux-juuls-single-barrel-172972', 849, TRUE, 70, 53.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614908.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614908-Rhum-JM-Rhum-Vieux-Juuls-Single-Barrel-172972.jpg', 'Det er altid en stor fornøjelse at kunne præsentere en enkeltfadsaftapning fra ét af vores yndlingsdestillerier: Rhum JM på Martinique. Denne gang er fornøjelsen dog særligt stor, for vi synes virkelig, vi har fundet en perle! Der er tale om en rom fra 2015, som har tilbragt sine 6 år på et bourbonfad, indtil vi var så heldige at få lov at pille den ud af JMs kælder. Selvom 6 år ikke lyder af så meget, så er der ingen umodenhed at spore i rommen, hvilket bl.a. skyldes den tropiske lagring. Det er ganske enkelt et fuldendt glas, og vi glæder os til at dele den med alle de danske fans af rhum agricole! Tappet ved fadstyrke, som har ramt 53,9%, uden kølefiltrering. Farve : Mørk ravfarvet. Duft : En overdådig blanding af tobak, tørrede blomster, lak og karamel. En rigtig ”nørde-næse”! Smagsnoter : Stor power, men helt i balance, med masser af dybde og lækker, naturlig sødme. I eftersmagen fornemmes et let funky touch, ikke som Jamaica-rom, men nærmere fermenteret sukkerrørssaft. Serveringsforslag : Nyd den rent. Lad den gerne stå i glasset 10 minutters tid – så åbner den sig flot.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate The Younger 2022', 'https://www.juuls.dk/rom/varekort/hampden-estate-the-younger-2022', 3279, TRUE, 300, 47, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643745.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643745-Hampden-Estate-The-Younger-2022.jpg', 'Max 1 flaske per kunde Denne aftapning er ekskluderet fra alle rabatkoder Hampden Estate The Younger LROK er en 5 år gammel rom fra Jamaica. Som navnet antyder, er rommen ung – kun 5 år – men lagringen er foregået i troperne, så den føles imponerende moden allerede. Og hvad den ikke har i alder, har den så sandelig i kvantitet: det her er nemlig hele 3 liter jamaicansk herlighed! Rommen er en såkaldt LROK, hvilket står for Light Rum Owen Kelly, og betegner et ester-indhold på mellem 200 og 400 gram per hektoliter ren alkohol. Den er tappet ved 47% alkohol. Farve : Gylden.  Duft : Delikat duft af mango, banan, peber og lak. Smagsnoter : Ananas, appelsinskal og nellike. Serveringsforslag : Bør nydes rent, evt. med en dråbe vand eller to.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Foursquare LFT White', 'https://www.juuls.dk/rom/varekort/habitation-velier-foursquare-lft-white', 749, TRUE, 70, 62, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643699.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643699-Habitation-Velier-Foursquare-LFT-White.jpg', 'Denne flaske er begrænset til én per kunde. ​Produktet er ekskluderet fra alle rabatkoder.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Barbados Vintage 2007 Bottled 2023', 'https://www.juuls.dk/rom/varekort/plantation-barbados-vintage-2007-bottled-2023', 679, TRUE, 70, 48.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641196.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641196-Plantation-Barbados-Vintage-2007-Bottled-2023.jpg', 'Så er der nyt i Vintage-serien fra Plantation Rum! Denne gang stifter vi bekendtskab med en Barbados-rom, hvor tingene er vendt en smule på hovedet. Som regel lagrer Plantation rommen længst tid i troperne, hvorefter den får en kortere ”finish” i Frankrig. Men her har rommen tilbragt ”blot” to år i bourbonfade på Barbados og hele 14(!) år på cognacfade hos Ferrand i Cognac! Der er altså tale om en 16 år gammel rom!  Den korte tropiske lagring på giver en dejlig, blød og frisk karakter med masser af kokos, citrus, flamberede bananer, vanilje og marcipan. Herefter 14 år på franske egefade som tidligere har indeholdt Ferrands Grande Champagne-cognac. Den europæiske eg rammer ganen med alt det vi, godt kan lide, nemlig de mørke, varme krydderier som kanel, muskatnød, peber, blomsterpollen, crême brûlée og saftige stenfrugt. Alt i alt en skøn Barbados-rom, destilleret både på pot still og kolonne. Rommen har en stor elegance og lag på lag af duft og smag fra de mange års fadlagring. En overlegen kvalitet til en meget attraktiv pris. Farve : Rav. Duft : Intens og krydret med kanel og muskatnød, vanilje, ristede mandler, banan og kokos. Smagsnoter : Krydret, men elegant og let sødmefuld. Her er noter af peber, stenfrugt og crême brûlée. I eftersmagen kommer vaniljen igen, sammen med flere krydderier, honning og prikkende lakrids og mere kokos. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Neisson L´Esprit Bio ØKO', 'https://www.juuls.dk/rom/varekort/neisson-lesprit-bio-oeko', 1049, TRUE, 70, 70, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615167.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615167-Neisson-L´Esprit-Bio-ØKO.jpg', 'Neisson L’Esprit er en økologisk rhum agricole fra et af Martiniques allerfineste destillerier. Det er Neissons første økologiske rom, lavet på gamle sorter af sukkerrør, som yder mindre end de moderne, men smager og dufter bedre i rom! Den er tappet efter at have hvilet på ståltank (men uden fadlagring) ved en ret flot alkoholprocent. Farve : Klar. Duft : Helt rigtig duft af græs, æble, mint og grønne urter. Smagsnoter : Meget kraftig smag, kræver måske en dråbe vand, medmindre man er hardcore romnørd!  Serveringsforslag : Nyd den i cocktails som fx ti’ punch, daiquris eller mai tais.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna ORIGINE 1870', 'https://www.juuls.dk/rom/varekort/savanna-origine-1870', 1999, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615484.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615484-Savanna-ORIGINE-1870.jpg', 'Savanna Origine 1870 er en limited edition rum fra La Reunion, frigivet for at fejre destilleriets grundlæggelse i 1870. Det er en såkaldt Hors d’Age: en gammel rom uden nærmere aldersangivelse, fordi det er en blanding af flere fade med forskellig alder. Der indgår både rhum traditionnel og grand arôme, fra både cognac- og portvinsfade, så der er garanti for en intens smagsoplevelse. Leveres i en imponerende kasse. Farve : Rav. Duft : Elegance og kompleksitet er nøgleordene. Her er mintagtige noter, ædeltræ, melasse, lakrids, bivoks og tropefrugt. Smagsnoter : En harmonisk blanding af søde frugtnoter, varme krydderier og træ samt en lang, kompleks finish. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Creol Straight', 'https://www.juuls.dk/rom/varekort/savanna-creol-straight', 224.5, TRUE, 50, 68.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615486.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615486-Savanna-Creol-Straight.jpg', 'Savanna Creol Blanc Straight er en rom fra øen La Réunion, lavet på frisk sukkerrørssaft og destilleret på kolonnekedler. En relativt kort gæring, som forløber over 2 dage, betyder, at denne rom ikke er den mest funky i Savannas sortiment, men stadig propfyldt med smag – blandt andet takket være aftapningen ved destillationsstyrke, eller ”straight from the still”: 68,7% alkohol. Farve : Klar. Duft : Voldsomt intens duft af tropisk frugt, oliven citrusskal og peber. Smagsnoter : Napper lidt pga. den høje alkohol, men leverer flot på smagen af oliven, limejuice, havsalt og hvid peber. Serveringsforslag : Kan nydes rent, evt. med et par dråber vand, eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Brugal 1888 Ron Gran Reserva', 'https://www.juuls.dk/rom/varekort/brugal-1888-ron-gran-reserva', 459, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642971.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642971-Brugal-1888-Ron-Gran-Reserva.jpg', 'Brugal 1888 Ron Gran Reserva old bottle er en rom fra Dominikanske Republik. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. De lækre noter af karamel, tørret frugt, chokolade og tobak gør den til en favorit hos mange. Kan nydes både rent eller i cocktails. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Mauritius Vintage 2013', 'https://www.juuls.dk/rom/varekort/planteray-mauritius-vintage-2013', 739, TRUE, 70, 46.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641198.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641198-Planteray-Mauritius-Vintage-2013.jpg', 'Planterays limited edition Vintage Collection bliver nu beriget med en rom fra Mauritius! Ikke verdens mest kendte romdestination, men utroligt spændende og med sin helt egen stil. Rommen her er destilleret i 2013 på base af melasse (på Mauritius ser man både sukkerrørssaft og melasse), på en column still. Den har tilbragt 9 år på bourbonfade i Mauritius, suppleret af 2 år hos Ferrand på franske fade. Den er tappet ved 46,5% alkohol, med en dosage på 4,5 gram sukker per liter, hvilket netop afrunder smagen og bidrager med en ganske let sødme. Farve : Rav. Duft : Her er tropiske noter af passionsfrugt, banan og kokosnød, understøttet af lys karamel og krydrede noter af tobak og muskatnød. Smagsnoter : Let sødmefuld med tørret frugt, rose, sort te og peber. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Papalin 6 Ans Haiti Ex Sherry Cask', 'https://www.juuls.dk/rom/varekort/papalin-6-ans-haiti-ex-sherry-cask', 939, TRUE, 70, 54.1, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643707.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643707-Papalin-6-Ans-Haiti-Ex-Sherry-Cask.jpg', 'Papalin 6 Years Old Haiti er et blend af 7 fade med rom fra 3 forskellige destillerier: Sajous, Vaval og Casimir. Rommen er lagret 6 år på oloroso-sherryfade fra den meget fine bodega, Lustau, og tappet ved fadstyrke (54,1%). Ren tropisk lagring på et exceptionelt godt fad giver en fyldig, intens og kompleks rom, som virkelig imponerer! Farve : Rav. Duft : Krydrede noter af mørk chokolade, rancio, valnød og ædeltræ. Smagsnoter : Stor og kompleks med noter af ingefær, chokolade igen, karry, safran og muskatnød. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier Last Ward Barbados 2007', 'https://www.juuls.dk/rom/varekort/velier-last-ward-barbados-2007', 2769, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404481.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404481-Velier-Last-Ward-Barbados-2007.jpg', 'Last Ward er opkaldt efter Frank Ward, som var managing director på Mount Gay Distillery. Denne aftapning er sammensat af 13 fade, alle med tripeltdestilleret rom fra 2007. Lagringen foregik på ex-bourbonfade og vi snakker altså hele 16 år i Barbados ’ tropiske klima! Det betyder, at ”the angel’s share” er oppe på hele 70%. Rommen er tappet ved 60% alkohol og vi snakker seriøs kompleksitet og power! Farve : Dyb gylden. Duft : Intens, kompleks duft af abrikos, kokosnød, muskatnød og tropisk frugt som mango og banan. Smagsnoter : Store fyldige noter, både af krydderier, ingefær, kaffe, nødder og tobak. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna L''Absolu 2023 Rhum Traditionnel', 'https://www.juuls.dk/rom/varekort/savanna-labsolu-2023-rhum-traditionnel', 2079, TRUE, 70, 55.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615478.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615478-Savanna-L''Absolu-2023-Rhum-Traditionnel.jpg', 'Savanna L’Absolu er hvad der sker, når man giver Savannas masterblender, Thierry Grondin, frie hænder til at vælge præcis de fade, han bedst kunne li’; hvor ingenting er off limits , heller ikke de allerældste fade på lageret. Resultatet er denne rhum traditionnel (lavet på melasse) extra vieux tappet ved skønne 55,5% alkohol. Vi ved ikke præcis hvilke fade, der indgår, men Savanna antyder at der er bl.a. portvinsfade og Grand Arôme i blandingen. Helt, helt ekstraordinær rom fra Reunion ! Farve : Rav. Duft : Frugtige noter i front: kandiseret citrus, stenfrugt, nødder og gammel Madeira. Smagsnoter : Flot balance mellem krydrede fadnoter, friskhed og frugt. Lækker naturlig sødme og en lang, kompleks eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Land Selection 12 Years Juuls Vin & Spir', 'https://www.juuls.dk/rom/varekort/planteray-land-selection-12-years-juuls-vin-spir', 739, TRUE, 70, 46.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404828.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404828-Planteray-Land-Selection-12-Years-Juuls-Vin-&-Spir.jpg', 'Planteray Land Selection er et vaskeægte world blend bestående af, hold nu fast: • 46% Trinidad-rom fra Trinidad Distillers (dem, som laver Angostura) • 15% Panama-rom fra Don José Distillery • 11% Barbados-rom fra West Indies Rum Distillery • 9% Australisk rom fra Beenleigh Artisan Distillery • 7% Jamaica-rom – fra Clarendon Distillers og Long Pond (et blend) • 6% Fiji-rom fra Rum Co. of Fiji • 6% Guyana-rom Lagringen er foregået både på bourbonfade i troperne, Ferrand-fade i Frankrig, og som prikken over i’et, er blendet lagret 1,5 år på moscatelfade. Der er tilsat 15 gram sukker per liter, for at give rommen en fin sødme. Tappet ved 47,5% alkohol. Farve : Rav. Duft : Balanceret, indbydende duft af mango, vanilje, muskatnød og milde kanelnoter. Smagsnoter : Karamelagtig sødme indleder en lang, kompleks smag af marcipan, abrikos og banan. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Jamaica Vintage 2017 Denmark', 'https://www.juuls.dk/rom/varekort/planteray-jamaica-vintage-2017-denmark', 739, TRUE, 70, 51.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404835.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404835-Planteray-Jamaica-Vintage-2017-Denmark.jpg', 'Long Pond behøver ikke den store introduktion; lad os blot nævne, at det er et af Jamaicas allerbedste destillerier. Og det er her, denne Jamaica-rom kommer fra! Der er tale om en single cask-aftapning med en tredobbelt fadlagring: først 6 måneders tropisk lagring på bourbonfade, så 5 år og 10 måneder på Ferrands fade i Frankrig og til sidst yderligere 8 måneder igen på bourbonfade. En bourbon-sandwich! Tappet ved omtrent 52% alkohol uden tilsat sukker eller farvestof. Farve : Rav. Duft : Intens, frugtig og funky duft: moden ananas, banan og cantaloup, tobak og hints af karamel og muskatnød. Smagsnoter : Igen masser af tropisk frugt, især ananas, citrongræs, æblecider og allehånde. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Barbados Vintage 2017 Adriatico Cask', 'https://www.juuls.dk/rom/varekort/planteray-barbados-vintage-2017-adriatico-cask', 579, TRUE, 70, 41.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404842.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404842-Planteray-Barbados-Vintage-2017-Adriatico-Cask.jpg', 'Planteray har altid været eksperter i spændende fadlagringer, og her er virkelig en fadtype, vi ikke ser ret tit! I en lille byttehandel med den bedste producent af amaretto på jorden, Adriatico, har de skaffet et amarettofad og efterlagret en allerede velvoksen Barbados-rom på det. En usædvanlig kombination, der bare fungerer. Og mon ikke Adriatico har noget spændende i ærmet også... ... det havde de sørme! Rommen er tappet ved 41,4% alkohol. Farve : Gylden. Duft : Brændte mandler, kakao, vanilje, ristet kokos og tropisk frugt. Smagsnoter : Fyldig, sødmefuld smag af saltkaramel, marcipan og ristede nødder. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Jamaica Long Pond Distillery ITP Ping 16', 'https://www.juuls.dk/rom/varekort/planteray-jamaica-long-pond-distillery-itp-ping-16', 2009, TRUE, 70, 58.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404482.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404482-Planteray-Jamaica-Long-Pond-Distillery-ITP-Ping-16.jpg', 'Ping-familien får et nyt medlem! Gammel Jamaica-rom står vores hjerte meget nært, og da Planteray tilbød os dette ekstraordinære fad fra Long Pond anno 2000, var vi ret hurtige til at sige merci beaucoup . Rommen er en såkaldt ITP, hvilket er en betegnelse, Long Pond giver rom der produceres med et esterindhold mellem 90-120 gram estere per hektoliter ren alkohol. Det tal kan dog godt stige under fadlagringen, og denne rom ligger på 219 g/hLAA og 1120 g/hLAA volatile compounds. Den har tilbragt 17 år på bourbonfad og 7 år på et Ferrand-fad. Tappet ved fadstyrke: 58,4%. Alle flasker er nummererede. Hvis du har fulgt Ping-serien, så ved du, at vi prøver kun at tappe det ypperligste under denne fane. Hvis du ikke har, så kan du læse mere her Farve : Mørkt rav. Duft : Afgrundsdyb aroma af tørret frugt, stenfrugt og tropisk frugt. Varme krydderier, ingefær og raffinerede fadnoter. Smagsnoter : God power, flot integreret alkohol og en profil der emmer af klassisk, vellagret Jamaica. Lang eftersmag med masser af kompleksitet, der indbyder til endnu en tår. Serveringsforslag : Bør nydes rent, evt. med en dråbe køligt vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Historic Solera Rum', 'https://www.juuls.dk/rom/varekort/black-tot-historic-solera-rum', 759, TRUE, 70, 46.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642253.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642253-Black-Tot-Historic-Solera-Rum.jpg', 'Black Tot Historic Solera Rum er landet! Denne lidt usædvanlige aftapning startede som et hyggeprojekt for Master Blender Oliver Chillton. Han ville gerne give rommen nogle af de dybe, mørke noter, som man forbinder med sherry, men en ganske almindelig sherry finish var bare ikke nok. Derfor besluttede Oliver at benytte sig af rigtig solera-lagring, ligesom i Jerez! Basen er altså rom fra Guyana, Jamaica og Barbados-rom, som er lagret først på oloroso- og pedro ximenez-sherryfade. Dernæst lagres blendet i en 3-lags-solera, hvor den yngste rom gradvist blandes med den ældre.  Fadene er der indgår i soleraen, er ægte ”solera casks”. Det betyder at de har været en del af en fungerende solera i Jerez, i dette tilfælde i over 70 år! Sådanne fade er ret svære at skaffe, for sherryproducenterne er ikke meget for at skille sig af med dem. Går de i stykker, reparerer man dem, nærmest i det uendelige, hellere end at inkorporere et nyt fad i soleraen. Et typisk sherryfad har ikke været brugt til lagring af sherry , men er et nyt fad, som behandles med sherry for at det skal få nogle af vinens karakteristika. Resultatet er en helt unik rom – og noget vi må anbefale alle romnørder at prøve. Tappet ved 46,2%, uden kølefiltrering eller tilsat sukker. Farve : Rav. Duft : Dekadent aroma af figner, blommer, chokolade og varme krydderier. Smagsnoter : Fløjlsbløde noter af mørk chokolade, kaffe og tropisk frugt. I eftersmagen – som virkelig er lang – fornemmes tørret frugt og varme, krydrede noter. Serveringsforslag : Nyd den rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnum Series #2 Hampden LROK 13 years old 2010', 'https://www.juuls.dk/rom/varekort/magnum-series-2-hampden-lrok-13-years-old-2010', 1999, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601100.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601100-Magnum-Series-#2-Hampden-LROK-13-years-old-2010.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Vieux Sajous 5 ans 2019', 'https://www.juuls.dk/rom/varekort/vieux-sajous-5-ans-2019', 1069, TRUE, 70, 58.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643667.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643667-Vieux-Sajous-5-ans-2019.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ærø Single cask Rum cask no.2 2021', 'https://www.juuls.dk/rom/varekort/aeroe-single-cask-rum-cask-no-2-2021-1', 839, TRUE, 50, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50647140-Ærø-Single-cask-Rum-cask-no.2-2021.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Pagos Batch 3 2024', 'https://www.juuls.dk/rom/varekort/hampden-pagos-batch-3-2024', 809, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643811.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643811-Hampden-Pagos-Batch-3-2024.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Art of Rum Yann Le Gall 2023', 'https://www.juuls.dk/rom/varekort/savanna-art-of-rum-yann-le-gall-2023', 1389, TRUE, 70, 54, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615494.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615494-Savanna-Art-of-Rum-Yann-Le-Gall-2023.jpg', 'Intet destilleri laver federe limited editions end Savanna. Det sætter de en tyk streg under med det seneste kuld, som blandt andet inkluderer denne Art of Rum-aftapning, designet af kunstneren Yann le Gall. Her er der virkelig garanti for en flaske der gør sig bemærket på hylden! Der er lavet 2.500 flasker. Og nu til det vigtige: flasken indeholder en blanding af Agricole og Rhum Traditionnel (melassebaseret rom) destilleret i årene 2014, 2015 og 2016 og lagret på gamle, franske cognacfade. Den er tappet ved 54% alkohol og som sædvanligt uden sukker eller andet snavs! Farve : Rav. Duft : Frugtig duft, også med let urtede noter (mynte), vanilje og mandel. Smagsnoter : Vanlig Savanna-intensitet uden at kamme over. Noter af ristet egetræ, nødder og en fin frugtighed. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Art of Rum REPY#3 ', 'https://www.juuls.dk/rom/varekort/savanna-art-of-rum-repy-3', 1339, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615501.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615501-Savanna-Art-of-Rum-REPY#3.jpg', 'Vi elsker Art of Rum-serien fra Savanna, og særligt med denne 3. edition har de gjort det godt: Flasken, som er udsmykket af kunstneren Repy (det er temaet for serien) indeholder en rom, der er sammensat af både rhum agricole og grand arôme, blandet i direkte i fadet af kældermesteren hos Savanna. Og det er cognacfade, vel at mærke. Den er tappet ved 57% alkohol og ikke tilsat sukker eller farvestof. 2.400 flasker på verdensplan. Farve : Lys kastanje. Duft : MInty, frugtig og kompleks duft. Æble, havbrise og ædeltræ. Smagsnoter : Kraftigt bid med let sødmefuld tropisk frugt, salt og en lang eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Doorly''s Fine Old 12yo Barbados Rum', 'https://www.juuls.dk/rom/varekort/doorlys-fine-old-12yo-barbados-rum', 439, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641760.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641760-Doorly''s-Fine-Old-12yo-Barbados-Rum.jpg', '', '2026-11-08 09:30:00+01');
