INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Sajous Haiti', 'https://www.juuls.dk/rom/varekort/clairin-sajous-haiti-5', 529, TRUE, 70, 55.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625326.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625326-Clairin-Sajous-Haiti.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI La Sirene - Rum from Cuba & Paraguay - Limited Edition', 'https://www.juuls.dk/rom/varekort/cdi-la-sirene-rum-from-cuba-paraguay-limited-edition', 669, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640566.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640566-CDI-La-Sirene---Rum-from-Cuba-&-Paraguay---Limited-Edition.jpg', 'La Sirène er er limited editon-rom fra Compagnie des Indes. Den er sammensat af to lidt usædvanlige komponenter: den første er en cubansk rom fra 2009, som har ligget 3 af sine år på ratafia-fade. Ratafia er en sød hedvin fra Champagne, og det er nok første gang, vi ser den type fade brugt til lagring af rom. Den anden komponent kommer fra Paraguay, og den har en 12 måneders finish på franske whiskyfade. Det endelige blend er tappet ved 43% alkohol i 500 eksemplarer. Farve : Gylden. Duft : Kompleks duft af gammelt ædeltræ, bivoks og blød karamel med et krydret touch i baggrunden. Smagsnoter : Elegant rom, der lægger sig blødt på tungen med ristede noter, kirsebær, lakrids og milde, eksotiske krydderier. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chairman''s Reserve The Forgotten Casks', 'https://www.juuls.dk/rom/varekort/chairmans-reserve-the-forgotten-casks', 479, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615733.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615733-Chairman''s-Reserve-The-Forgotten-Casks.jpg', 'I 2007 udbrød der brand på destilleriet i Saint Lucia. Under genopbygningen måtte kældermesteren hos Chairman’s være kreativ med hvor han gemte fadene, og i forvirringen blev nogle fade glemt. Da de dukkede op 4 år senere, havde de ligget væsentligt længere end planlagt og smagsprofilen var ganske unik. Chairman’s Reserve har derfor lavet en ekstra-lagret rom, The Forgotten Casks, som en hyldest til disse fade. Rommen er en blanding af destillater fra kolonne-still og en John Dore pot still. Den er lagret 7-8 år (tropisk) på ex-bourbonfade, og tappet uden tilsat sukker ved 40% alkohol. Farve : Rav. Duft : Dyb og intens på næsen med noter af brændt sukker, havannacigarer, varme krydderier og grillet ananas. Smagsnoter : Flot intensitet og en lækker, naturlig sødme. Mørke noter af krydderier og melasse, valnød og vanilje. Serveringsforslag : Nyd den rent eller i cocktails – måske en Mai Tai?', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Art of Rum by Xandro Limited Edition', 'https://www.juuls.dk/rom/varekort/savanna-art-of-rum-by-xandro-limited-edition', 1329, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615508.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615508-Savanna-Art-of-Rum-by-Xandro-Limited-Edition.jpg', 'Art of Rum er Savannas særlige rom-serie hvor hver flaske og kasse udsmykket af en kunstner fra Reunion. Denne release, udsmykket af kunstneren Xandro, er en blanding af gammel rhum traditionnel og HERR – Savannas ikoniske højester-rom. Komponenterne er destilleret i 2006, 2015 og 2018.Den er tappet ved høj styrke, 57%, i blot 1.700 eksemplarer.   Farve : Lyst rav. Duft : Intens tropisk frugt og ristet eg. Smagsnoter : En kraftig rom, der emmer af eksotisk frugt a la ananas og mango, men også med mørke krydderier og brændt karamel. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Ansyen Single Cask #CA21MG-104 Coalition DK 2026', 'https://www.juuls.dk/rom/varekort/clairin-ansyen-single-cask-ca21mg-104-coalition-dk-2026', 819, TRUE, 70, 55, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625244.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625244-Clairin-Ansyen-Single-Cask-#CA21MG-104-Coalition-DK-2026.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin Ansyen Single Cask #VA20BR-1 Coalition DK 2026', 'https://www.juuls.dk/rom/varekort/clairin-ansyen-single-cask-va20br-1-coalition-dk-2026', 819, TRUE, 70, 53.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625245.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625245-Clairin-Ansyen-Single-Cask-#VA20BR-1-Coalition-DK-2026.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Blanc BiB', 'https://www.juuls.dk/rom/varekort/clement-rhum-blanc-bib', 1039, TRUE, 300, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610155.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610155-Clement-Rhum-Blanc-BiB.jpg', 'Der har altid været ét problem ved rommen fra Clement. Flaskerne er for små! Det rådes der nu bod på med denne martinikanske klassiker: rom i bag-in-box! Clément Rhum Blanc er den helt klassiske hvide agricole-rom. Den har en meget typisk Clement-karakter med citrus og et urtet, græsagtigt strejf i duften. Fra øjeblikket du hælder den i glasset er du ikke i tvivl om, at det her er agricole! Farve: Klar. Duft: En duft af nyslået græs, appelsinblomst og grønne urter; basilikum og oregano. Smagsnoter: Sort te, citrus og grønne, græssede noter. Serveringsforslag: Clément Rhum Blanc er oplagt at bruge i cocktails der kræver en hvid rom med masser af smag og en stærk personlighed.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Blanc Canne Bleue', 'https://www.juuls.dk/rom/varekort/clement-rhum-blanc-canne-bleue', 369, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610160.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610160-Clement-Rhum-Blanc-Canne-Bleue.jpg', 'Clement Blanc Canne Bleue er lidt af en sjældenhed i romverdenen, nemlig en rom hvor fokus ikke ligger på destillationen eller fadlagringen, men på råmaterialet: sukkerrøret. Rommen er lavet udelukkende på én type sukkerrør, en variant kaldet ”Canne Bleue” på grund af den blålige farve, hvilket gør den til en “single cane” eller “single varietal”-rom. Denne type sukkerrør giver et meget aromatisk destillat og er derfor oplag at fremhæve i en single-cane udgave. Farve:  Klar Duft:  Intens, frugtig duft med hints af mynte og citronfromage. Smagsnoter:  Frisk og sprød, medium fylde, sommeragurker og et touch af salt. Serveringsforslag:  Kan drikkes rent eller i cocktails – særligt ti’punch eller fra tiki-genren.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Vieux Agricole Select Barrel', 'https://www.juuls.dk/rom/varekort/clement-rhum-vieux-agricole-select-barrel', 399, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610350.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610350-Clement-Rhum-Vieux-Agricole-Select-Barrel.jpg', 'Clément Select Barrel er en agricolerom lagret minimum 3 år i fade med hvad Clément kalder en ”particularly heavy toasting”. Fade, der skal bruges til lagring af rom eller whisky, brændes eller toastes normalt indvendigt - dette gøres både for at spiritussen lettere kan trænge ind i træet og for at ændre de smage, som ekstraheres. Med disse fade får Clément Select Barrel en mere udpræget vaniljenote i duft og smag. Farve: Rav Duft: Cedertræ, krydderier og madagaskarvanilje. Smagsnoter: En let og blød mundfølelse med afdæmpet sødme, abrikos, toffee og rosmarin. Serveringsforslag: En virkelig god rom til mai tais og ti’punch, men kan også nydes rent eller over is.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Vieux Agricole VSOP', 'https://www.juuls.dk/rom/varekort/clement-rhum-vieux-agricole-vsop', 529, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610400.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610400-Clement-Rhum-Vieux-Agricole-VSOP.jpg', 'Clément Rhum Vieux Agricole VSOP er en agricolerom lagret minimum 4 år på fade af både ny, fransk eg og brugte bourbonfade. Det giver en delikat kombination af krydrede noter, blandt andet muskatnød og nelliker, og de klassiske, mere vaniljeagtige noter fra bourbonfadene. Dette er en rom, som kan drikkes rent eller bruges i cocktails når niveauet skal hæves et trin eller to! Farve: Let kobber Duft: Kraftig, frugtig duft med appelsinskal og grønne æbler, samt et hint af jord, vanilje og mandler. Smagsnoter: Kompleks smag med noter af muskatnød og creme brulée. Serveringsforslag: Drikkes rent eller i cocktails hvis du kan nænne det!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Vieux Agricole Cuvee Homere', 'https://www.juuls.dk/rom/varekort/clement-rhum-vieux-agricole-cuvee-homere', 1339, TRUE, 70, 44, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50611000.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50611000-Clement-Rhum-Vieux-Agricole-Cuvee-Homere.jpg', 'Clément Cuvée Homere er Cléments kældermesters hjertebarn, sammensat af udvalgte vintages fra kælderen med op til 15 års lagring. Blendet indeholder rom der har ligget på fade af fransk Limousin-eg og bourbonfade, og resultatet kalder Clément selv for en af firmaets mest komplekse rom. En passende hyldest til den berømte Homère Clément, husets grundlægger. Farve : Mørk gylden Duft : En lækker og dyb næse, med noter af estragon, frisk frugt og Håkonskager. Smagsnoter : I smagen finder man blandt andet brændte mandler, hasselnød, lakrids og vanilje. Serveringsforslag : Bør drikkes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Vieux Agricole Vintage 1970', 'https://www.juuls.dk/rom/varekort/clement-rhum-vieux-agricole-vintage-1970', 8769, NULL, 70, 44, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50611500.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50611500-Clement-Rhum-Vieux-Agricole-Vintage-1970.jpg', 'Der er kun få rom-producenter der kan præstere så bedagede årgange som Clément (uden at snyde, vel at mærke), og med denne Vintage Rhum 1970 nærmer vi os de rigtig gamle sager. Ligesom de andre udgivelser fra Clément, er denne rom produceret på frisk sukkerrørsjuice og lagret cirka 21 år - rommen er nemlig tappet på flaske helt tilbage i 1991! En romoplevelse af de helt store, for nørder såvel som nyudklækkede romnydere. Farve: Mahogni Duft: Vanvittig kompleks duft, med bølger af etiopisk kaffe, sandeltræ, overmoden ananas, lakrids og menthol. Smagsnoter: Grøn te og kastanjelikør med hints af grapefrugt og tjære i eftersmagen. Serveringsforslag: Drikkes rent!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Blanc Agricole', 'https://www.juuls.dk/rom/varekort/rhum-jm-blanc-agricole', 329, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614000.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614000-Rhum-JM-Blanc-Agricole.jpg', 'I Rhum JM Blanc er sukkerrørene fra JMs berømte marker på fuldt display. Der er flotte og intense noter af moden, tropisk frugt (ananas, mango og banan) og lette, grønne græsnoter. Aftapningsprocenten på 50 klæder virkelig rommen. Den ekstra power mærkes både i aromaen og smagen, og så sikrer den, at der ingen risiko er for at rommen bliver væk i din mai tai! Farve: Klar. Duft: Skønne sukkerrørsnoter; græs og olivenolie, flankeret af moden ananas og mango. Smagsnoter: Sødmefuld og vældig frugtig. Dertil et salt touch samt en smule våd jord. Serveringsforslag: En oplagt rom til ti’punch eller mai tais!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Rhum Vieux Single Barrel 1999 Ping 14', 'https://www.juuls.dk/rom/varekort/rhum-jm-rhum-vieux-single-barrel-1999-ping-14', 3069, TRUE, 50, 43.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614906.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614906-Rhum-JM-Rhum-Vieux-Single-Barrel-1999-Ping-14.jpg', 'Findes der noget skønnere end gammel rhum agricole ? Det er noget af det bedste, vi ved, så derfor blev vi ellevilde da vi fik mulighed for at føje denne sjældne J.M fra 1999 til vores PING-serie. Her tapper vi de allerbedste fade, vi kan finde, og denne smukke, gamle rom er bestemt værdig til at være PING 14 – det er faktisk det ældste J.M, vi nogensinde har set! Den er lavet på frisk sukkerrørssaft på Martiniques mindste destilleri, og det fugtige klima, hvor J.M lagrer rommen, betyder, at alkoholprocenten falder med op til 2% ABV om året. Derfor kan rommen efter 20 års lagring tappes ved en fadstyrke på kun 43,6%! Læs i øvrigt også Mads Heitmanns begejstrede anmeldelse på  Romhatten.dk ! "... når man bare at lyst til at blive kælet for, så er dette himlen" Farve: Rav. Duft: En enorm dybde med lag efter lag af kakao, tobak, brændt eg og kandiseret viol. Smagsnoter: Elegant og rank – nærmest aristokratisk – i munden, med noter af tørret frugt der smukt komplimenterer de mørke noter af varme krydderier, egetræ og brændt sukker. Serveringsforslag: Nyd den rent, eller med enkelte dråber køligt vand. Giv gerne rommen god tid til at åbne sig i glasset.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Lontan Blanc 57', 'https://www.juuls.dk/rom/varekort/savanna-lontan-blanc-57', 419, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615437.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615437-Savanna-Lontan-Blanc-57.jpg', '"Det er imponerende, at man har formået at lave et produkt som dette til kun 400 kr. ... [den er] nærmest et must have i barskabet" - Romhatten.dk Se anmeldelsen her Et monster af en rom! Mere er der næsten ikke at sige… eller jo, der er masser, men vi skal gøre det kort: ”Lontan” betegner Savannas langtidsgærede, ultrafunky high-ester rom. Det er måske ikke for sarte sjæle, men for de udvalgte få, er det fantastisk. Denne aftapning er destilleret i marts 2019 efter 6 dages gæring, og har et esterindhold på 811,87 gram per liter absolut alkohol. Det er højt, og det kan smages. Og lugtes. På 10 meters afstand. Farve: Klar. Duft: En eksplosion af overmodne, spontangærede ananasser, oliven og varm plastic, som en lejetøjslastbil i en sandkasse en eftermiddag i juli. Smagsnoter: Kraftig og intens smag, stadig præget af overmoden tropisk frugt, oliven og havvand. Serveringsforslag: Det er et must at smage den rent – og prøv derefter en centiliter eller to i din daiquiri eller mai tai.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Millenium', 'https://www.juuls.dk/rom/varekort/savanna-millenium', 3299, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615441.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615441-Savanna-Millenium.jpg', 'Savanna Millenium er én af destilleriets fornemmeste udgivelser. Rommen er gæret på sukkerrørsmelasse og destilleret i 1999, hvorefter den har slumret de næste 15 år på egetræsfade indtil Savannas kældermester besluttede, at dens zenit var nået. Rommen er tappet ved 43% alkohol og viser den elegante og sofistikerede side af Savanna. Farve: Rav. Duft: Læder, egetræ, kanel, Havanna-cigarer, nelliker og ingefær. Smagsnoter: Dyb, fyldig og elegant. Noter af vanilje, figner og krydderier og så en meget lang eftersmag med kakaopuler og ingefær. Serveringsforslag: Bør nydes rent, evt. med en dråbe vand eller to.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Boulet de Canon No. 4 Ex Peated Whisky Barrels', 'https://www.juuls.dk/rom/varekort/cdi-boulet-de-canon-no-4-ex-peated-whisky-barrels', 739, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640641.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640641-CDI-Boulet-de-Canon-No.-4-Ex-Peated-Whisky-Barrels.jpg', 'Compagnie des Indes Boulet de Canon No. 4 er fjerde udgivelse i en serie af aftapninger der sætter fokus på røgede elementer. Denne gang er det et 5 år gammelt jamaicaromsblend, som er efterlagret på fade der tidligere har indeholdt skotsk whisky fra øen Islay – en region som er kendt netop for sine røgede, tjærede, tørvede whiskies. Præcis hvilken whisky, der er tale om, opgives ikke, men vi ved dog, at rommen er tappet uden tilsætning af sukker eller kølefiltrering, og ved respektable 46%. Farve: Rav. Duft: Jamaicarommen fornægter sig ikke: modne bananer og ristede nødder træder tydeligt frem. Smagsnoter: I munden mærkes ”whiskyen” mere – her er diskrete røgede noter af lapsang souchong og brændt karamel. Serveringsforslag: Kan nydes rent eller i cocktails – hvis du har fantasien! En sjov rom til et riff på en Penicillin -cocktail: 6 cl Boulet de Canon (vælg din favorit) 2 cl frisk citronsaft 2 cl honning-ingefær-sirup Rom, citron og sirup shakes og serveres over is i et rocks-glas. Farvel influenza! Honning-ingefær-sirup : Lige dele vand og honning koges op sammen med et par stykker frisk ingefær. Lad blandingen infusere i 10 minutter, hvorefter ingefæren sies fra og siruppen køles ned.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Boulet de Canon No. 6 Ex Peated Whisky Barrels', 'https://www.juuls.dk/rom/varekort/cdi-boulet-de-canon-no-6-ex-peated-whisky-barrels', 679, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640643.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640643-CDI-Boulet-de-Canon-No.-6-Ex-Peated-Whisky-Barrels.jpg', 'Efter den temmelig excentriske – ja, nærmest bizarre – Boulet de Canon No. 5, er 6. udgave mere ”normal”. Denne gang er det et blend af rom fra Panama og Nicaragua, som får en 6 måneder lang finish på fade, der tidligere har indeholdt røget whisky fra Islay i Skotland. Efterlagringen giver en rommen en diskret røget note, men uden at overvælde dens frugtige karakter. Farve: Gylden. Duft: Eksotisk frugt og krydderier springer op af glasset, efterfulgt af en let røg. Smagsnoter: Ristede hasselnødder og Nutella på brændt toast. Serveringsforslag: Kan nydes rent eller i cocktails. Servér den evt. for dine whisky-venner! En sjov rom til et riff på en Penicillin -cocktail: 6 cl Boulet de Canon (vælg din favorit) 2 cl frisk citronsaft 2 cl honning-ingefær-sirup Rom, citron og sirup shakes og serveres over is i et rocks-glas. Farvel influenza! Honning-ingefær-sirup : Lige dele vand og honning koges op sammen med et par stykker frisk ingefær. Lad infusere i 10 minutter, hvorefter ingefæren sies fra og siruppen køles ned.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Guyana 21 years DK', 'https://www.juuls.dk/rom/varekort/cdi-guyana-21-years-dk', 2269, TRUE, 70, 51, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640820.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640820-CDI-Guyana-21-years-DK.jpg', 'Denne Compagnie des Indes Guyana 21 Year Old er én af de eftertragtede ”Denmark Exclusive”-aftapninger. Den er destilleret i oktober 1993 ved Uitvlugt, et destilleri som var aktivt indtil december 1999, hvorefter deres destillationsapparat blev flyttet til sit nuværende hjem hos Demerara Distillers. Det er derfor, man stadig ser aftapninger med navnet ”Uitvlugt”. Men nok historieundervisning! Det her er en kæmpestor og kompleks rom, hvis smag fortjener at tale for sig selv. Farve: Rav. Duft: Manukahonning, sorte oliven, tørret tang, brændt karamel og motorrum. Wow! Smagsnoter: Rosiner, kandiserede mandler og en snert af saltlakrids. Serveringsforslag: Bør nydes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Guyana DK 24 years Enmore', 'https://www.juuls.dk/rom/varekort/cdi-guyana-dk-24-years-enmore', 3089, TRUE, 70, 58.1, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640823.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640823-CDI-Guyana-DK-24-years-Enmore.jpg', 'Compagnie des Indes Guyana 24 Year Old Enmore er en enkeltfadsaftapning udelukkende til det danske marked. Så gammel demerara-rom er efterhånden et sjældent syn og romnørder klapper i hænderne når flasker som denne frigives! Den kommer fra et gammelt, legendarisk destillationsapparat, Enmore, som er en kolonne-still lavet af træ, der er berømt for at producere en helt særlig stil. Og den er selvfølgelig er tappet ved fadstyrke (58,9%!). Et monster af en rom! Farve: Gylden. Duft: En næse med mange facetter: både nougat, kakao, brune bananer, trækul og brændende rosmarinkviste! Smagsnoter:  Både sødmefulde noter af creme brulée og marcipan, samt mere tertiære noter af svampe og muld. Serveringsforslag: Bør nydes rent. Tilsæt evt. et par dråber køligt vand hvis du ikke kan klare mosten!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Uitvlugt Guyana DK 18 Years MGA5', 'https://www.juuls.dk/rom/varekort/cdi-uitvlugt-guyana-dk-18-years-mga5', 1649, TRUE, 70, 57.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640889.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640889-CDI-Uitvlugt-Guyana-DK-18-Years-MGA5.jpg', 'Compagnie des Indes Uitvlugt Single Cask #MGA5 kommer fra en såkaldt Savalle-still, der i dag står hos Diamond Distillery – det eneste destilleri, der er tilbage i Guyana. Rommen er lagret i 18 år mellem 1997 og 2016, og der blev tappet i alt 387 flasker fra fadet – alle i ”cask strength”. En imponerende, tør og smagfuld rom fra Florent og Co. Farve: Let gylden. Duft: Anis, kirsebær og grapefrugt. En snert af varm asfalt. Smagsnoter: Moden mango, akaciehonning, brændt sukker og sort te. Serveringsforslag: Bør nydes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Cuba DK 18 years CSS7', 'https://www.juuls.dk/rom/varekort/cdi-cuba-dk-18-years-css7', 2059, TRUE, 70, 59, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640908.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640908-CDI-Cuba-DK-18-years-CSS7.jpg', 'Compagnie des Indes Cuba 18 Years #CSS7 er en enkeltfads aftapning af 18 år gammel rom fra det cubanske destilleri, Sancti Spiritus. Rommen er tappet udelukkende til det danske marked og den er hverken vandet ned eller tilsat sukker inden aftapningen. Destilleriet er kendt som ”den lette roms vugge”, men denne aftapning har masser af power og tyngde i smagen og er desuden tappet ved en alkoholstyrke, man sjældent ser mage til når det gælder cubansk rom! Farve: Let gylden. Duft: Elegant duft af æbler, ferskner, jordbær og vanilje. Smagsnoter: En fin tyngde i munden, med noter af sød lakrids, nedfaldsæbler og rosmarin. Serveringsforslag: Bør nydes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Port Mourant Guyana 9 Years Old GDDD34', 'https://www.juuls.dk/rom/varekort/cdi-port-mourant-guyana-9-years-old-gddd34', 839, TRUE, 70, 58.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640909.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640909-CDI-Port-Mourant-Guyana-9-Years-Old-GDDD34.jpg', 'Compagnie des Indes Port Mourant 9 Years Old Cask # GDDD34 er en single cask rom fra Guyana. Denne flaske er én af de velrenommerede enkeltfadsaftapninger til Danmark, som vi hvert år venter spændt på. Rommen har ligget 9 år på fad, en del af tiden i Guyana og en del i Europa, og den er tappet ved fadstyrke (58,7%) uden tilsat sukker. Farve: Gylden. Duft: Blommer, marmelade, forkullet eg og tørret banan. Smagsnoter: Kraftig og tør, med noter af brændte mandler, ingefær, sesam, blommer og melasse. Serveringsforslag: Bør nydes rent, evt. med en dråbe vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Secrete Jamaica 9 Years Old JWSP1', 'https://www.juuls.dk/rom/varekort/cdi-secrete-jamaica-9-years-old-jwsp1', 499, TRUE, 70, 53.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640912.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640912-CDI-Secrete-Jamaica-9-Years-Old-JWSP1.jpg', 'Compagnie des Indes Secrete Jamaica 9 Years Old cask #JWSP1 er en enkeltfadsaftapning fra Jamaica. Selve producenten er ikke oplyst – under ”destilleri” har flasken påskriften ”Secrete”.  Det er ikke ualmindeligt, at aftapperen underskriver en fortrolighedsaftale om, at man ikke afslører hvilket destilleri, der har leveret rommen. Men det er naturligvis også smagen der tæller, og her skuffer denne Jamaica-rom ikke! Stor og frugtig med power og en laaaang eftersmag. Farve: Lys gylden. Duft: Flot Jamaica-duft med bananer, melasse, dåseananas og nye gummisko. Smagsnoter: Limeskal, tropisk frugt og et hint af eg; vaniljesirup og mandler. Serveringsforslag: Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Veneragua Multi Distilleries Small Batch', 'https://www.juuls.dk/rom/varekort/cdi-veneragua-multi-distilleries-small-batch', 769, TRUE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640915.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640915-CDI-Veneragua-Multi-Distilleries-Small-Batch.jpg', 'Compagnie des Indes Veneragua Multi Distilleries er et small batch blend, der indeholder rom fra flere lande. I alt er fem fade blandet, hvoraf 3 stammer fra Venezuela og 2 er fra et destilleri i Nicaragua. De er alle lagret minimum 13 år, og tappet ved 45% alkohol uden kølefiltrering. En spændende rom, som har både kompleksitet og umiddelbar drikkeglæde. Farve: Ravgylden. Duft: Smørkaramel, lakridskonfekt og vanilje. Smagsnoter: Blød og imødekommende. Spicy noter af friskkværnet peber, muskatnød og toffeehints. Serveringsforslag: Kan nydes rent eller i enkle cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Navy Rum Last Consignment', 'https://www.juuls.dk/rom/varekort/black-tot-navy-rum-last-consignment', 17009, TRUE, 70, 54.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642300.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642300-Black-Tot-Navy-Rum-Last-Consignment.jpg', 'Da det britiske parlament stemte for at afskaffe flådens daglige udskænkning af rom i 1970, var sidste udskænkning d. 31. juli – blot 6 måender dage efter afstemningen. Naturligvis kunne man ikke nå at drikke hele flådens  enorme beholdning af rom på den tid (selvom nogle sikkert forsøgte), og resten blev opmagasineret. Black Tot Last Consignment kommer fra de originale stentøjsflakoner, der blev fyldt efter Black Tot Day , så her får du chancen for at smage den oprindelige navy-rom. Flydende historie, ganske enkelt. Farve: Lys mahogni. Duft: Fyldig og kompleks duft af krydderier som nellike, sort peber og kanel, mørke bær, melasse og balsamico. Smagsnoter: Tæt og intens med enormt mange lag. Hints af tobak, melasse, lakrids, mørke krydderier og et strejf af kaffe i eftersmagen. Serveringsforslag: Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot 40 years', 'https://www.juuls.dk/rom/varekort/black-tot-40-years', 17519, TRUE, 70, 44.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642370.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642370-Black-Tot-40-years.jpg', 'Black Tot Rare Old Aged 40 Years er noget så sjældent som en 40 år gammel rom fra Guyana. Den blev destilleret helt tilbage i 1975! Rommen er en slags efterfølger til Black Tot Last Consignment, og selvom den britiske flåde nok sjældent fik serveret ren Guyana-rom (og da slet ikke ved denne alder), så synes vi bestemt det er en værdig successor. Mørk, kraftig og koncentreret som få andre! Rommen er selvfølgelig tappet ved fadstyrke, som i dette tilfælde er kommet ned på 44,2% alkohol. Farve: Tæt mahogni. Duft: Tæt duft af lakrids, stjerneanis, sort peber, brændt eg og melasse. Virkelig mange lag! Bagerst fornemmes cigarrøg og tjære. Heavy stuff. Smagsnoter: Superkoncentreret med masser af melasse, egetræ, tobak, lakrids, brændt kanel og nærmest alle krydderier, vi kan komme i tanke om. Serveringsforslag: Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Botran Co Gran Reserva 75th Anniversary Edition', 'https://www.juuls.dk/rom/varekort/botran-co-gran-reserva-75th-anniversary-edition', 1705, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642452.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642452-Botran-Co-Gran-Reserva-75th-Anniversary-Edition.jpg', 'Botran Co Gran Reserva 75th Anniversary Edition er en rom fra Guatemala. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Bør nydes rent. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bacardi Carta Blanca', 'https://www.juuls.dk/rom/varekort/bacardi-carta-blanca', 159, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642600.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642600-Bacardi-Carta-Blanca.jpg', 'Bacardi Carta Blanca er en rom fra Caribien. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 37,5%. Smagen er mellemkraftig med noter af specielt vanilje. Nyd den rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Chalong Bay Rum', 'https://www.juuls.dk/rom/varekort/chalong-bay-rum', 499, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643180.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643180-Chalong-Bay-Rum.jpg', 'Chalong Bay er en ulagret, thailandsk rom lavet på frisk sukkerrørssaft. På mange måder minder den lidt om rommen vi kender fra Martinique eller Haiti, med masser af frugt og de ”grønne”, græssede noter fra sukkerrøret. Det er en ret funky rom, og lidt af en speciel smagsoplevelse, hvis man ikke er vant til stilen – men når først man er bidt, så er der ingen vej tilbage. Tårnhøj klasse fra Thailand – hvem havde set det komme? Farve:  Klar. Duft:  Dufter af overmoden, tropisk frugt, urter, græs og sukkerrørsjuice. Smagsnoter:  Smagen er fyldig, kompleks og kraftig på trods af den lave alkohol. Der er en lækker naturlig sødme, funky frugtnoter, peber og honning. Serveringsforslag:  Kan nydes rent eller i cocktails. Prøv den fx i en klassisk Daiquiri!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Atlantico Rum Platino', 'https://www.juuls.dk/rom/varekort/atlantico-rum-platino', 299, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643200.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643200-Atlantico-Rum-Platino.jpg', 'Atlantico Rum Platino er en rom fra Dominikanske Republik. Den er lavet på sukkerrør. Rommen er tappet ved 40%. En glimrende smagsoplevelse med noter af vanilje og peber. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Centenario 20 anos Solera Fundacion', 'https://www.juuls.dk/rom/varekort/ron-centenario-20-anos-solera-fundacion', 499, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643250.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643250-Ron-Centenario-20-anos-Solera-Fundacion.jpg', 'Ron Centenario 20 anos Solera Fundacion er en rom fra Costa Rica. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Smagen er mellemkraftig med noter af vanilje, egetræ, tørret frugt og chokolade. Nyd den rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Angostura 1824', 'https://www.juuls.dk/rom/varekort/angostura-1824', 499, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643630.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643630-Angostura-1824.jpg', 'Angostura 1824 er en rom fra Trinidad. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. En fin smagsoplevelse med noter af karamel, chokolade, tropisk frugt, appelsinskal og varme krydderier. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('HIMMALEH White Habitation Velier', 'https://www.juuls.dk/rom/varekort/himmaleh-white-habitation-velier', 739, TRUE, 70, 56, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643723.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643723-HIMMALEH-White-Habitation-Velier.jpg', 'Velier Hampden LROK White er en Jamaica-rom aftappet i serien Habitation Velier , som udover at levere fantastiske smagsoplevelser også sætter gennemsigtighed i højsædet og tilfredsstiller selv krævende romnørders nysgerrighed. Fx bekendtgør etiketten ester-indholdet i rommen, hvilket er direkte forbundet til smagen. Denne udgave er tappet uden lagring, så du får den rene smag af Hampdens utrolige LROK-destillat! Rommen holder 62,5% alkohol. Farve: Klar. Duft: Vidunderlig duft, eksplosiv og intens, med tropisk frugt som banan og ananas, hvid peber, citrus og ingefær. Smagsnoter: Også smagen har enorm intensitet. Syrlig frugt (passionsfrugt og ananas), pære og citrus. Serveringsforslag: Bør nydes rent, evt. med en dråbe vand eller to.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Union', 'https://www.juuls.dk/rom/varekort/havana-club-union', 4275, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643897.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643897-Havana-Club-Union.jpg', 'Havana Club Union er en rom fra Cuba. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Havana Club Union har en god fylde, og masser af kompleksitet i smagen, hvor man blandt andet finder nuancer af tørret frugt, kokos og kaffe. Bør nydes rent. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Santiago de Cuba Ron Carta Blanca', 'https://www.juuls.dk/rom/varekort/ron-santiago-de-cuba-ron-carta-blanca', 189, TRUE, 70, 38, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643952.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643952-Ron-Santiago-de-Cuba-Ron-Carta-Blanca.jpg', 'Santiago de Cuba Carta Blanca er en rom lavet på sukkerrørsmelasse og destilleret på kolonnekedler i ”den lette roms vugge”, Santiago de Cuba. En kort lagring giver en diskret vaniljeagtig karakter, som sammen med den relativt lette krop skaber en oplagt rom til helt sprøde, klassiske cubanske daiquiris eller mojitos, men det er naturligvis kun fantasien der sætter grænser! Farve : Klar. Duft : Indbydende duft af sukkerrør, vanilje og helt diskret tropisk frugt. Smagsnoter : Blød og rund. En snert af vanilje, citrus og ananas.  Serveringsforslag : Prøv den i en klassisk daiquiri: 5 cl Santiago de Cuba Carta Blanca 2 cl frisk limesaft 1,5 cl sukkersirup Shaket med masser af is og dobbeltstrainet i en afkølet coupe-glas', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Mount Gay XO Triple Cask Blend Rum', 'https://www.juuls.dk/rom/varekort/mount-gay-xo-triple-cask-blend-rum', 509, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644210.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644210-Mount-Gay-XO-Triple-Cask-Blend-Rum.jpg', 'Mount Gay XO Triple Cask Blend Rum er en rom fra Barbados. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 43%. Mount Gay XO Triple Cask Blend Rum har en god fylde, og masser af kompleksitet i smagen, hvor man blandt andet finder nuancer af chokolade, kokos, karamel og tropisk frugt. Nyd den rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Edicion Negra', 'https://www.juuls.dk/rom/varekort/ron-zacapa-edicion-negra', 709, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644705.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644705-Ron-Zacapa-Edicion-Negra.jpg', 'Ron Zacapa Edicion Negra er en sød rom fra Guatemala. Rommen er et blend af destillater med forskellig alder – fra 6 år til 24 år. Den er lagret på fade, som blandt andet har indeholdt amerikansk whiskey og den søde sherrytype  Pedro Ximenez  – og ”det med småt” nævner også ”double charred oak barrels”. Tappet ved 43%. Farve:  Kobber. Duft:  Masser af tørret frugt, chokolade og vanilje – og så et strejf af røg, som klæder den godt. Smagsnoter:  Rund og sødmefuld.  Ananas, rosin og chokolade. Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Matusalem Solera 23 Gran Reserva', 'https://www.juuls.dk/rom/varekort/ron-matusalem-solera-23-gran-reserva', 509, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50645640.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50645640-Ron-Matusalem-Solera-23-Gran-Reserva.jpg', 'Ron Matusalem Solera 23 Gran Reserva er en rom fra Dominikanske Republik. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. En fin smagsoplevelse med noter af tørret frugt, honning og nødder. Kan nydes både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Abuelo Anejo Reserva Especial', 'https://www.juuls.dk/rom/varekort/ron-abuelo-anejo-reserva-especial', 209, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50645810.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50645810-Ron-Abuelo-Anejo-Reserva-Especial.jpg', 'Ron Abuelo Anejo Reserva Especial er en rom fra Panama. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. En strålende smagsoplevelse med noter af vanilje og karamel. Nyd den rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Abuelo Anejo 12 Anos', 'https://www.juuls.dk/rom/varekort/ron-abuelo-anejo-12-anos', 359, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50645840.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50645840-Ron-Abuelo-Anejo-12-Anos.jpg', 'Ron Abuelo Anejo 12 Anos er en rom fra Panama. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Smagen er mellemkraftig med noter af specielt vanilje, tobak, karamel og varme krydderier. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Amrut Two Indies Rum', 'https://www.juuls.dk/rom/varekort/amrut-two-indies-rum', 289, TRUE, 70, 42.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50645970.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50645970-Amrut-Two-Indies-Rum.jpg', 'Amrut Two Indies Rum kommer fra Bangalore i Indien. Herhjemme er Amrut mere kendt for single malt whisky, men de har lavet rom mindst lige så længe! I modsætning til Amruts Old Port-rom, er Two Indies ikke udelukkende indisk, men en blanding af rom fra Jamaica, Barbados, Guyana og pot still-destilleret rom fra Indien – det kan umuligt gå galt! Den er tappet ved 42,8% alkohol. Farve: Ravgylden. Duft: Overmoden mango, nelliker og muskatnød. Smagsnoter: Tung og med en let sødme. Lakrids, banan, cashewnødder og honning. Serveringsforslag: Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pampero Seleccion 1938 Ron Anejo', 'https://www.juuls.dk/rom/varekort/pampero-seleccion-1938-ron-anejo', 199, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646220.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646220-Pampero-Seleccion-1938-Ron-Anejo.jpg', 'Pamero Selección 1938 er en rom fra Venezuela. Rommen blev første gang blev fremstillet af en fiskersøn i 1938. Den smukke ravfarve skyldes fem-seks års lagring i egetræsfade, som tidligere blev brugt til bourbonfremstilling. Farve : Mørk rav. Duft : Vanilje, karamel og trænoter. Smagsnoter : Klassisk smag med vanilje, karamel og noter af træ. Serveringsforslag : Smagsfacetterne i Pamero Selección gør den raffineret som base i cocktail. Nyd den også alene over is, som man gør det i Venezuela, suppleret med en limeskive dyppet i kaffe og rørsukker.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado 25 years', 'https://www.juuls.dk/rom/varekort/el-dorado-25-years', 5960, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646360.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646360-El-Dorado-25-years.jpg', 'El Dorado 25 Years Old er en rom fra det sidste overlevende destilleri på Guyana; Diamond Distillery. Dette er en af El Dorados top-udgivelser; en sjælden og yderst eftertragtet rom, som efter ekstraordinært lang lagring – 25 år i troperne er  meget  længe – har fået stor dybde og kompleksitet. I flasken indgår rom destilleret på flere af Diamond Distillerys apparater; især Enmore og La Bonne Intention træder frem i rampelyset. El Dorado 25 Years Old er én af kun få flasker, der har fået 100/100 point på romhatten.dk. Farve:  Mahogni. Duft:  Mørk og intens aroma af brændt karamel, banan, appelsin, valnødder og tørret frugt. Smagsnoter:  Massiv sødme og en superfed mundfølelse – skal næsten fortæres med kniv og gaffel. Noterne fra duften går igen, og eftersmagen fortsætter i det uendelige. Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kiyomi White Rum Okinawa', 'https://www.juuls.dk/rom/varekort/kiyomi-white-rum-okinawa', 479, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646710.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646710-Kiyomi-White-Rum-Okinawa.jpg', 'Kiyomi White Rum er en rom fra Okinawa lavet på melasse af lokale sukkerrør, langtidsgæret og destilleret på kolonne-kedler. Rommen er ikke lagret på egetræsfade, men hviler 3-6 måneder på tanke af rustfri stål, og i den periode vandes den gradvist og nænsomt ned til de 40% alkohol. Navnet ”Kiyomi” kan oversættes til ”Pure Beauty”, og det synes vi egentlig er meget passende. Farve:  Klar. Duft:  Spændende duft af tropisk frugt, hvid peber og agurk. Smagsnoter:  Smagen er på én gang ren og meget karakterfuld. Vi bemærker florale noter, oliven og mynte. Serveringsforslag:  Kan nydes rent eller i cocktails. Har god gavn af ti minutter i glasset til at ”åbne sig”, hvis den drikkes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Teeda 21 years Rum Okinawa', 'https://www.juuls.dk/rom/varekort/teeda-21-years-rum-okinawa', 6709, TRUE, 70, 48, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646795.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646795-Teeda-21-years-Rum-Okinawa.jpg', 'Teeda 21 Years Old er en rom fra Okinawa i Japan lavet på lokal sukkerrørsmelasse. Den blev destilleret på pot still i 1998 af 3. generation af Matsuda-familien. Med hele 21 år på fade af ny, amerikansk eg, er dette det ældste Japanske rom, vi har set indtil nu – og bestemt også noget af det bedste. Den er tappet ved 48% alkohol, hvilket klæder den meget flot. Der er kun produceret 2.500 flasker. Farve:  Rav. Duft:  Stor duft med mange lag af abrikos, banan, vanilje og kanel. Smagsnoter:  Afrundet og elegant men med masser af karakter. Noter af stenfrugt, chokolade og krydderier. En superlang og kompleks eftersmag. Serveringsforslag:  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Rare Collection Port Mourant', 'https://www.juuls.dk/rom/varekort/el-dorado-rare-collection-port-mourant', 2259, TRUE, 70, 61.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646381.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646381-El-Dorado-Rare-Collection-Port-Mourant.jpg', 'El Dorado Rare Collection Port Mourant 1999 er en rom fra det sidste overlevende destilleri på Guyana: Diamond Distillery. I ”Rare Collection” udgiver El Dorado sjælden rom med særlige ”marques” – stilarter fra gamle dage, som de kan efterligne på deres forskellige destillationsapparater. Port Mourant er en pot still af træ – et af romverdenens mest legendariske destillationsapparater! Rommen er tappet i 2015 ved fadstyrke, 61,5%, uden tilsat sukker. Farve:  Rav. Duft:  Kæmpe! Brændt karamel, toastet eg, hindbærmarmelade og et hint af røg. Smagsnoter:  Koncentreret smag af engelsk lakrids, melasse og nelliker. Lang eftersmag. Serveringsforslag:  Bør nydes rent, evt. med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Mulata Silver', 'https://www.juuls.dk/rom/varekort/ron-mulata-silver', 159, TRUE, 70, 38, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644002.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644002-Ron-Mulata-Silver.jpg', 'Ron Mulata Silver er en rom fra Cuba. Rommen er tappet ved 38%. En glimrende smagsoplevelse med noter af vanilje, græs og tropisk frugt. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau Vintage 1953', 'https://www.juuls.dk/rom/varekort/damoiseau-vintage-1953', 51519, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50616700.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50616700-Damoiseau-Vintage-1953.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Glens White Rum', 'https://www.juuls.dk/rom/varekort/glens-white-rum', 169, TRUE, 70, 37.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640120.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640120-Glens-White-Rum.jpg', 'Glens White Rum er en rom fra Caribien. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 37,5%. I smagen fornemmes både vanilje og kokos. Der er en fin fylde og en behagelig, lang eftersmag. Kan nydes både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Caroni 15 years', 'https://www.juuls.dk/rom/varekort/caroni-15-years', 5169, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643675.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643675-Caroni-15-years.jpg', 'Caroni 15 Years Old er en rom fra et lukket destilleri på Trinidad. Den er tappet ved 52% alkohol af den ultimative rom-guru, Luca Gargano og hans firma Velier. Enhver rom-entusiast bør smage Caroni mindst én gang på sin romrejse. Denne flaske er et skoleeksempel på god Caroni, hvor tjære, røg, brændt karamel og tørret frugt går op i en højere enhed. Farve : Kobber. Duft : Duften er mørk og kraftfuld. Nylagt asfalt, harpiks, bacon og peber. Smagsnoter : Klassisk, tung Caroni, men ikke den mest brutale af slagsen. De typiske tjære-noter får selskab af tørret frugt og rosiner. Serveringsforslag : Bør drikkes rent, men hvis du er modig, smager den godt som erstatning for ginnen i en Negroni.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Havana Club Maximo', 'https://www.juuls.dk/rom/varekort/havana-club-maximo', 26950, TRUE, 50, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643896.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643896-Havana-Club-Maximo.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Guyana Ocho Tequila Limited Edition', 'https://www.juuls.dk/rom/varekort/plantation-guyana-ocho-tequila-limited-edition', 2059, TRUE, 70, 44.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404615.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404615-Plantation-Guyana-Ocho-Tequila-Limited-Edition.jpg', 'Plantation Guyana Ocho Tequila Cask Finish er en limited edition rom med en yderst usædvanlig fadlagring. Efter 17 år på bourbonfade i Guyana og 2 år på cognacfade i Frankrig, har rommen fået prikken over i’et: 1 år på tequila-fade fra Ocho – et af verdens mest velrenommerede tequila-brands, som kun producerer tequila på 100% agave. Denne type fadlagring er yderst usædvanlig – decideret sjælden endda – og vi kan love det er en oplevelse at smage! Selve rommen kommer fra Port Mourant, så der er masser af power til at stå imod tequilafadets indflydelse. Et drøn af en rom! Farve : Dyb rav. Duft : En kompleks duft der bærer bræg af ultra-fin, gammel añejo-tequila med bagt agave, limeskal, peber og ristede mandler. Så brager Guyana-rommen igennem med sin kaffe, nougat, sorte oliven og mango. Smagsnoter : Uendeligt stor og fedmefuld, med melasse, tobak og kakaonoter. Toffee med havsalt i eftersmagen. Serveringsforslag : Nyd den rent. En rom der fortjener fuld opmærksomhed!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Peru 2010 White Pineau Denmark 2019', 'https://www.juuls.dk/rom/varekort/plantation-peru-2010-white-pineau-denmark-2019', 399, TRUE, 70, 43.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404679-Plantation-Peru-2010-White-Pineau-Denmark-2019.jpg', 'Plantation Peru 2010 White Pineau Cask Finish er en single cask rom, tappet eksklusivt til det danske marked. Selvom der ikke ligger mange destillerier i Peru, produceres der enorme mængder rom i landet. Denne kommer helt sikkert fra ”øverste hylde” på lageret! Her får du masser af rom for skillingen: elegant, forførende men også med stor power. Farve : Rav. Duft : Tæt og kraftig duft af mørk chokolade, brændt eg og vaniljekranse. Smagsnoter : Tyk og fedmefuld i smagen, hvor man finder noter af varme krydderier, tørret frugt og chokolade. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier Foursquare Principia', 'https://www.juuls.dk/rom/varekort/velier-foursquare-principia', 8999, TRUE, 70, 62, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601026-Velier-Foursquare-Principia.jpg', 'Foursquare Principia er en 9 år gammel rom fra Barbados – den 3. udgivelse i et samarbejde mellem master distiller Richard Seale og allround romguru Luca Gargano fra Velier. Rommen har ligget 3 år på bourbonfade og 6 år på sherryfade; en usædvanlig ”double maturation” som dog klæder den utroligt godt! Den er tappet ved 61% alkohol og selvfølgelig ikke tilsat sukker eller farvestof. Stor rom! Farve:  Dyb mahogni med rødlige skær. Duft:  Mørk frugt, rosiner og julekrydderier a la muskatnød og kanel. Smagsnoter:  Meget intens. Når man er kommet sig over det første alkoholchok, er der flotte noter af tranebær, hindbær, lakrids og blomme med krydderier igen i eftersmagen. Serveringsforslag:  Bør nydes rent, evt. med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Charanda Uruapan Blanco Pure Single Agricola Rum', 'https://www.juuls.dk/rom/varekort/charanda-uruapan-blanco-pure-single-agricola-rum', 519, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625256.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625256-Charanda-Uruapan-Blanco-Pure-Single-Agricola-Rum.jpg', 'Det er efterhånden en del år siden vi forelskede os i den mexicanske rom Paranubes , og det giver sig selv, at den vilde, komplekse og fascinerende rom har vækket vores nysgerrighed efter hvad der ellers findes af sukkerrørsdestillater i Mexico. Uruapan Charanda ”Single Agricola Rum” er lige hvad vi har hungret efter! Rommen kommer fra Michoacan og som navnet antyder, er den lavet i ”agricole-stil”: på frisk sukkerrørssaft. Den er dobbeltdestilleret på en gammel pot still af kobber og ikke tilsat sukker. Familien Pacheco har lavet Charanda i mange år, og etiketten er en kopi af en flaske fra 1928, fundet i familiens arkiv. Farve : Klar. Duft : Frisk og ”grøn” duft af friske sukkerrør, græs, peber og vanilje. Smagsnoter : Fyldig, cremet mundfølelse med noter af tropisk frugt, grønne urter og græs.  Serveringsforslag : Kan nydes rent eller i cocktails. Prøv den fx i en klassisk daiquiri!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sol Tarasco Charanda Rum 4 Years', 'https://www.juuls.dk/rom/varekort/sol-tarasco-charanda-rum-4-years', 479, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625800.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625800-Sol-Tarasco-Charanda-Rum-4-Years.jpg', 'Sol Tarasco 4 Years er en rom lavet på ”high mountain sugarcane” fra bjergene i Michoacan i Mexico. Destillationen foregår på kobber-pot stills, hvorefter rommen, der i dette område kaldes charanda , lagres i mindst 4 år på ex-bourbon og sherryfade, før den tappes uden tilsat sukker. Farve : Rav.  Duft : Ret intens duft af honning, vaniljestang og ægte kanel. Smagsnoter : Mørk og krydret smag, med noter af dadler, kanel, nellike og ristede nødder. Serveringsforslag : Nydes rent – men prøv den endelig også i en Old Fashioned!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sol Tarasco Charanda Rum 10 Years', 'https://www.juuls.dk/rom/varekort/sol-tarasco-charanda-rum-10-years', 629, TRUE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625850.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625850-Sol-Tarasco-Charanda-Rum-10-Years.jpg', 'Sol Tarasco 10 Years er en mexicansk rom fra staten Michoacan. Den er lavet på mieles de caña – sukkerrørshonning – hvilket vil sige indkogt saft af sukkerrør høstet i de omkringliggende bjerge. Efter gæringen destilleres den på en kobber-pot still, og lagringen foregår på både bourbonfade og sherryfade, i dette tilfælde mindst 10 år. Naturligvis tappet uden tilsat sukker! Farve : Mahogni.  Duft : Tæt og kompleks duft af kaffebønner, tørret frugt og vaniljestænger. Smagsnoter : Tør og kraftfuld, på trods af den lave alkohol. Varme krydderier, egetræ, vanilje og tørret frugt. Serveringsforslag : Nydes rent – men prøv den endelig også i en Old Fashioned!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Reisetbauer Rum 4x50 R.N.P.', 'https://www.juuls.dk/rom/varekort/reisetbauer-rum-4x50-r-n-p', 1659, TRUE, 70, 40.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640000.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640000-Reisetbauer-Rum-4x50-R.N.P..jpg', 'Rum 4x50 er fire venners drøm om den perfekte rom, skabt til at nyde netop i gode venners lag. En rom som er social, placeless and ageless . 4x50 udtales four-fifty (eller [fɔː ˈfɪfti] hvis du kender det fonetiske alfabet!), og 4-tallet repræsenterer disse fire venner, mens 50 repræsenterer et ”Rum Council” på 50 medlemmer, som tæller Michelin-kokke, sommelierer og andre folk med forstand på smag. X’et symboliserer to krydsede svær; et gammelt symbol på venskab blandt riddere. Den nok vigtigste af alle de involverede er Hans Reisetbauer, rommens berømte master distiller, som også står bag en række verdenskendte eau de vie’er. Selve rommen er ret international, eller placeless, som de selv siger, for mens Hans Reisetbauer destillerer cirka 80% på melasse af højeste kvalitet fra Mauritius, kommer de resterende 20% fra et blend af Jamaica, Guyana, Venezuela, Nicaragua og Guatemala. Nedvandingen sker med vand fra Hans’ ”hemmelige” kilde i Alperne, og lagringen foregår på Ysper-eg.  Værd at nævne er også ”udstyret”, for sjældent har vi set så detaljerig en indpakning! Flasken er specialdesignet af Stölzle Glass Group, etiketten er ægte gedeskindslæder og stopperen er forkromet messing fra Lanza Metallwaren. Selv flaskens indpakning er der tænkt nøje over: den kommer i en unik papsarkofag af 100% genbrugt materiale, FSC-certificeret og perfekt tilpasset flaskens form med thermoforming .  Farve : Lys gylden. Duft : Mild og let krydret duft af vaniljestænger, lys karamel og kokos. Smagsnoter : Smyger sig blødt om tungen, igen med noter af vanilje, milde krydderier, frisk fløde og karamel. Serveringsforslag : Nyd den rent eller i en fantastisk daiquiri!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Ambre', 'https://www.juuls.dk/rom/varekort/clement-rhum-ambre-1', 289, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610301.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610301-Clement-Rhum-Ambre.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Barbancourt Rhum 15 years', 'https://www.juuls.dk/rom/varekort/barbancourt-rhum-15-years', 589, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50624000.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50624000-Barbancourt-Rhum-15-years.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rivers Royale Grenadian Rum 69%', 'https://www.juuls.dk/rom/varekort/rivers-royale-grenadian-rum-69', 729, TRUE, 70, 69, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625900.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625900-Rivers-Royale-Grenadian-Rum-69%.jpg', 'Rivers Royale Grenadian Rum er en kraftig, hvid rom fra Grenada. Rommen kommer fra et af verdens mest ”old school” destillerier, hvor alt gøres som man gjorde for 200 år siden. Der er ikke engang elektricitet! Sukkerrørene dyrkes økologisk og knuses i en valse drevet af en vandmølle. Den friske saft koges ind til sirup, som vildgæres og destilleres på pot stills. Den tappes uden lagring og uden tilsætning af sukker eller karamel ved svimlende 69% alkohol! Det er rent guf for romnørder. I lang tid har rommen været næsten umulig at skaffe udenfor Grenada, for de producerer knapt nok rom nok til at tilfredsstille den lokale efterspørgsel, men nu er der endelig landet en (ganske lille) sending på dansk grund! Farve:  Klar. Duft:  Superpotent duft, fyldt med tropiske frugter, syrlige/laktiske noter, havvand og kanelstænger. Smagsnoter:  Voldsom alkohol – pas godt på! Kraftige, krydrede noter, ananas, banan og chili. Serveringsforslag:  Kan nydes rent (hvis du er hardcore romnørd) eller bruges i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Jamaica 8 Years Old Multi Distilleries Denmark', 'https://www.juuls.dk/rom/varekort/cdi-jamaica-8-years-old-multi-distilleries-denmark', 989, TRUE, 70, 64.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640925.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640925-CDI-Jamaica-8-Years-Old-Multi-Distilleries-Denmark.jpg', 'Compagnie des Indes har tappet nogle af de allerbedste Jamaica-rom , vi nogensinde har smagt, fra destillerier som New Yarmouth og Hampden. Med denne Bottled for Denmark-¬aftapning går de lidt anderledes til værks. Det er nemlig et ”multi-distillery blend”. De forskellige destillater kommer alle fra juli 2012, og er så blandet sammen i ét fad, hvor de er lagret indtil rommen blev tappet i april 2021 som 8 år gammel. Fadet (nummer JDM71) gav 247 flasker ved hele 64,9%. Og det er alt sammen til Danmark! Farve : Lyst rav. Duft : Citrusolier, klassiske romkugler og en fornemmelse af at stå i en tivolibod fyldt med kandiserede æbler, candyfloss og farvestrålende slikkepinde.   Smagsnoter : Kraftig og smækfyldt med smag. Man mærker alkoholen, men den er virkelig flot integreret for næsten 65% - rommen kan snildt drikkes ufortyndet! Lækker, naturlig sødme. I eftersmagen igen candyfloss, ristede noter og hjulspin (asfalt og brændt gummi). Jamaica, når det er bedst! Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carupano Legendario', 'https://www.juuls.dk/rom/varekort/carupano-legendario', 5419, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643335.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643335-Carupano-Legendario.jpg', 'Legendario er toppen af kransekagen hos Carúpano. Det er ganske enkelt det bedste, Venezuela kan præstere! Mens de andre rommer fra Carúpano er en blanding af flere lots med varierende alder, er Legendario en single lot lagret 25 år på amerikanske egetræsfade, tappet uden blending. Hvert år frigives blot 500 (behørigt flotte) krystalkarafler. Farve : Mahogni. Duft : Mørk frugt, nødder og ristede mandler, kandiseret ingefær, dadler og chokolade – en stor, markant og kompleks duft. Smagsnoter : Flot intensitet og dybde i smagen, med luksuriøse noter af vaniljestang, mørk chokolade, toffee og nødder. Lang eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carupano Reserve 1996', 'https://www.juuls.dk/rom/varekort/carupano-reserve-1996', 1489, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643336.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643336-Carupano-Reserve-1996.jpg', 'Ron Carúpano Reserve 1996 er blandt Venezuelas største rom-skatte. I denne luksus-aftapning indgår rom helt tilbage fra 1996, lagret på amerikanske egetræsfade, som ikke toppes op løbende når rommen fordamper. Jo mindre fyldt, tønden er, desto hurtigere fordamper rommen, og det er derfor en ret kostbar måde at gøre tingene på, men for Carúpano er det prisen værd – the proof is in the pudding. Farve : Rav. Duft : Ikke overdrevet kraftig, men kompleks og raffineret med mange lag af nødder, dadler, toffee, kokosnød og moden ananas. Smagsnoter : Sublim balance, let sødme, tropisk frugt, ristede nødder og varme krydderier. Serveringsforslag : Nyd den rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Blanc Canne Bleu mini', 'https://www.juuls.dk/rom/varekort/clement-rhum-blanc-canne-bleu-mini', 59, TRUE, 5, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610811.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610811-Clement-Rhum-Blanc-Canne-Bleu-mini.jpg', '', '2026-11-08 09:30:00+01');
