INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Barbados Partizan Brewing Denmark 2019', 'https://www.juuls.dk/rom/varekort/plantation-barbados-partizan-brewing-denmark-2019', 829, NULL, 70, 48.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404650_box.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404650-Plantation-Barbados-Partizan-Brewing-Denmark-2019.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Aged 5 Years', 'https://www.juuls.dk/rom/varekort/savanna-aged-5-years', 459, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615436.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615436-Savanna-Aged-5-Years.jpg', 'Savanna Rhum Vieux Traditionnel 5 Ans er en rom fra île de la Réunion i det Indiske Ocean. Den er lavet på melasse og lagret 5 år på fade af fransk eg fra skove i Allier og Limousin, og ved denne alder har rommen en helt perfekt balance mellem det frugtige destillat og de krydrede og vaniljeagtige noter fra egetræet. Den er tappet ved 43% alkohol. Farve : Gylden. Duft : Fin fylde i duften som bærer noter af kamfer, vanilje, tobaksblade og tørret banan. Smagsnoter : Cremet mundfølelse og livlige noter af kokos, ananas, vanilje og muskatnød. Serveringsforslag : Bør nydes rent, evt. med en dråbe vand eller to.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Providence Haitian White Rum Dunder & Syrup', 'https://www.juuls.dk/rom/varekort/providence-haitian-white-rum-dunder-syrup', 529, TRUE, 70, 56, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625197.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625197-Providence-Haitian-White-Rum-Dunder-&-Syrup.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Jamaica 5 years Navy Strength Magnum', 'https://www.juuls.dk/rom/varekort/cdi-jamaica-5-years-navy-strength-magnum', 889, TRUE, 150, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640629-CDI-Jamaica-5-years-Navy-Strength-Magnum.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Guyana Porto Cask Finish High Proof Denmark', 'https://www.juuls.dk/rom/varekort/cdi-guyana-porto-cask-finish-high-proof-denmark', 989, TRUE, 70, 62.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640929.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640929-CDI-Guyana-Porto-Cask-Finish-High-Proof-Denmark.jpg', 'En lang portvinsfinish på en allerede vellagret Demerara-rom – se dét er sjovt! Det er Compagnie des Indes der har tappet denne perle af et fad med 14 år gammel rom. De sidste 48 måneder er tilbragt på et portvinsfad og det klæ’r spiritussen rigtig flot, giver sødme og rød frugt. Alkoholprocenten ligger på 62,4, og de i alt 430 flasker er kun til Danmark. Farve : Mørk, rødlig gylden. Duft : Tæt og svulmende duft der blander saftig, rød frugt, marmelade, kakaopulver og ristede nødder. Smagsnoter : Overdådig og intens smag af moden, rød frugt med knasende perlesukker.  Servering​sforslag : Vi foreslår, at du drikker den rent, men som altid med en rom i dette luftlag (62,4%), er du velkommen til at eksperimentere med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Trinidad Ten Cane Distillery Denmark', 'https://www.juuls.dk/rom/varekort/cdi-trinidad-ten-cane-distillery-denmark-1', 5169, TRUE, 70, 60.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640930.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640930-CDI-Trinidad-Ten-Cane-Distillery-Denmark.jpg', 'Max 2 fl. per kunde Dette produkt er ekskluderet fra alle rabatkoder Hver gang vi har fået en Ten Cane-rom fra Compagnie des Indes (det er ikke ret tit), er den blevet udsolgt på et øjeblik. Det er rom, der er både spændende, sjælden og virkelig velsmagende, så vi takkede selvfølgelig ja da Florent Beuchet tilbød os fad nummer TDK83 fra dette obskure, lukkede destilleri på Trinidad. Hvis du ikke kan huske – eller aldrig har hørt om – Ten Cane, så er den korte udgave af historien, at Ten Cane blev bygget af Louis Voutton Moët Hennessy i midten af ’00’erne med det formål at lave pot still-destilleret rom på frisk sukkerrørssaft i Trinidad. Desværre bukkede destilleriet under og måtte lukke inden rommen fandt sit publikum, og derfor er fade fra Ten Cane utroligt sjældne (og eftertragtede) i dag. Denne gang er det en rom helt tilbage fra 2008, flasket ved fadstyrke (60,7%) efter 13 års lagring. Der er tappet i alt 275 flasker – kun til det danske marked! Farve : Gylden. Duft : Kompleks duft med mange lag af tørret frugt og vanilje. Smagsnoter : Både elegance og power, modne fadnoter, citrus og florale hints. Serveringsforslag : Nyd den rent – det er liquid history !', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Xaymaca Milk Punch by Kester Thomas', 'https://www.juuls.dk/rom/varekort/xaymaca-milk-punch-by-kester-thomas', 149, TRUE, 50, 21, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641383-Xaymaca-Milk-Punch-by-Kester-Thomas.jpg', 'Xaymaca Milk Punch by Kester Thomas er en færdigblandet cocktail fra Planteray Rum lavet på en af Danmarks bedste barer: Kester Thomas. Navnet henviser til rommen Xaymaca, en frugtig og funky jamaica-rom fra Planteray, som selvfølgelig spiller hovedrollen i cocktailen. Milk punch er en klassisk cocktailteknik, hvor mælk bruges til at gøre drinken silkeblød og mere eller mindre klar. Cocktailen kommer på en 50 cl flaske, og er fuldstændig klar til servering, så du kan springe shakeren over. Tappet ved 21% alkohol. Farve : Lys. Duft : Tropisk frugt og et funky rom-strejf. Smagsnoter : Blød og cremet med tropisk frugt, jamaicansk funk og laktiske noter samt en tydelig sødme. Serveringsforslag : Server den iskold, evt. over is.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement VO', 'https://www.juuls.dk/rom/varekort/clement-vo', 449, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610351.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610351-Clement-VO.jpg', 'Clément Select Barrel er en agricolerom lagret minimum 3 år i fade med hvad Clément kalder en ”particularly heavy toasting”. Fade, der skal bruges til lagring af rom eller whisky, brændes eller toastes normalt indvendigt - dette gøres både for at spiritussen lettere kan trænge ind i træet og for at ændre de smage, som ekstraheres. Med disse fade får Clément Select Barrel en mere udpræget vaniljenote i duft og smag. Farve : Rav Duft : Cedertræ, krydderier og madagaskarvanilje.  Smagsnoter : En let og blød mundfølelse med afdæmpet sødme, abrikos, toffee og rosmarin. Serveringsforslag : En virkelig god rom til mai tais og ti’punch, men den kan også nydes rent eller over is.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('ISAUTIER 7 ans', 'https://www.juuls.dk/rom/varekort/isautier-7-ans', 769, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615473.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615473-ISAUTIER-7-ans.jpg', 'Perfekt afbalanceret, denne lagrede rom fra Isautier har en helt unik stil: Frisk, frugtig, med noter af havspray. Denne melasse rom er kolonnedestilleret og lagret på franske egetræsfade, specielt designet til Maison Isautier, i 7 år. Farve : Smuk guld- og ravfarve. Duft : Generøs. Aromaer af moden frugt, kandiseret frugt og citrus blandes med ristet og vaniljesmag. Smag : Intens. Perfekt balance mellem de frugtige smage og fadet. Hint af mynte og ingefær - Enormt lækker! Serveringsforslag : Nyd den rent (evt. med en dråbe vand). Gør sig særligt godt i cocktails!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('ISAUTIER 10 ans', 'https://www.juuls.dk/rom/varekort/isautier-10-ans', 929, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615474.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615474-ISAUTIER-10-ans.jpg', 'Klassisk, vellagret agricole-rom fra Isautier! Farve : Smuk ravfarve. Duft : Rig aroma. Krydret og pebret, med noter af kandiseret frugt og moden banan. Smag : Blød. Perfekt balance mellem friskheden af ​​citrusskal og rundheden af ​​vanilje. Kraftig og kompleks med en umiskendelig karakter af ​​gammel rom. Serveringsforslag : Bør nydes rent, evt. med en dråbe vand eller to.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna SL1 Cuvée Bois Rouge 1992-2022', 'https://www.juuls.dk/rom/varekort/savanna-sl1-cuvee-bois-rouge-1992-2022', 1309, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615481.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615481-Savanna-SL1-Cuvée-Bois-Rouge-1992-2022.jpg', 'Savannas fine jubilæumsaftapning fejrer at destilleriet for 30 år siden i 2022 flyttede til Bois Rouge. Det er en blanding af flere fade med gammel rhum agricole. Der er tappet 3.200 flasker ved 57%. Farve : Rav. Duft : Kraftig, krydret duft af mint, varme krydderier og stenfrugt. Smagsnoter : Tør, kompleks og krydret rom med en lang eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Kingston 62 White Rum', 'https://www.juuls.dk/rom/varekort/kingston-62-white-rum', 199, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642391.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642391-Kingston-62-White-Rum.jpg', 'Kingston 62 White Rum er en rom fra Jamaica. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. En perfekt smagsoplevelse med noter af tropisk frugt og vanilje. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('UNION 55 Rum Spice & Sea Salt', 'https://www.juuls.dk/rom/varekort/union-55-rum-spice-sea-salt', 309, TRUE, 70, 38, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643261.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643261-UNION-55-Rum-Spice-&-Sea-Salt.jpg', 'UNION 55 Rum Spice & Sea Salt er en rom fra Barbados. Den er lavet på melasse. Rommen er tappet ved 38%. UNION 55 Rum Spice & Sea Salt har en god fylde, og masser af kompleksitet i smagen, hvor man blandt andet finder nuancer af chokolade, honning og skumsprøjt og havbrise. Kan nydes både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate HLCF Classic', 'https://www.juuls.dk/rom/varekort/hampden-estate-hlcf-classic', 889, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643768.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643768-Hampden-Estate-HLCF-Classic.jpg', 'Max 1 flaske per kunde Denne aftapning er ekskluderet fra alle rabatkoder Hampden Estate HLCF er klassisk Jamaica-rom, når det er bedst! Ung (men tropisk lagret), potent og rimelig høj på esters.  Farve : Gylden. Duft : Mentol, grillede bananer, citrusskaller og acetone. Smagsnoter : Masser af power, tropisk frugt og kandiseret citron. Serveringsforslag : Nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa La Doma 2020', 'https://www.juuls.dk/rom/varekort/ron-zacapa-la-doma-2020', 659, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644730.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644730-Ron-Zacapa-La-Doma-2020.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Takamaka White 2021', 'https://www.juuls.dk/rom/varekort/habitation-velier-takamaka-white-2021', 629, TRUE, 70, 56, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646702.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646702-Habitation-Velier-Takamaka-White-2021.jpg', 'Vi har kun få flasker til salg, og derfor kan der købes max 1 fl. per person. Denne aftapning er desuden ekskluderet fra alle rabatkoder. Den ene af Habitation Veliers 2 aftapninger fra Seychellerne! Det lille destilleri, Takamaka, er grundlagt i 2002, men de to aftapninger til Velier er de første, der kommer 100% fra pot still - og dette er i øvrigt den første ulagrede Takamaka.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnum Series #1 Hampden HLCF 5 years 2021 Magnum', 'https://www.juuls.dk/rom/varekort/magnum-series-1-hampden-hlcf-5-years-2021-magnum', 3449, TRUE, 150, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601084.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601084-Magnum-Series-#1-Hampden-HLCF-5-years-2021-Magnum.jpg', 'Obs: 1,5 liter Ordet ”magnum” har en helt særlig betydning i vin- og spirituskredse, men i dette tilfælde er betydningen dobbelt: Velier har frigivet en serie af rom, hvor etiketterne prydes af billeder fra det berømte fotograf-kooperativ, Magnum Photos. Og ja, flasken er i magnum-størrelse. Med Magnum Series er Velier ikke bange for at indrømme, at de er skabt som investeringsobjekter: “I wanted to create valuable bottlings that could be auctioned like the greatest single malts or works of art,” fortæller Luca Gargano. “Four great rums produced by four great Master Distillers, selected by me, with an extra touch”. Det ekstra touch skulle være billederne fra Magnum, nærmere bestemt Elliot Erwitt, for Luca er også stor fotografientusiast. Rommen her kommer fra Hampden Distillery på Jamaica. Den er lagret 5 år og udvalgt og tappet af Velier ved 60% alkohol.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnum Series #1 Foursquare 16 years 2021 Magnum', 'https://www.juuls.dk/rom/varekort/magnum-series-1-foursquare-16-years-2021-magnum', 5659, TRUE, 150, 61, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601086.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601086-Magnum-Series-#1-Foursquare-16-years-2021-Magnum.jpg', 'Obs: 1,5 liter Ordet ”magnum” har en helt særlig betydning i vin- og spirituskredse, men i dette tilfælde er betydningen dobbelt: Velier har frigivet en serie af rom, hvor etiketterne prydes af billeder fra det berømte fotograf-kooperativ, Magnum Photos. Og ja, flasken er i magnum-størrelse. Med Magnum Series er Velier ikke bange for at indrømme, at de er skabt som investeringsobjekter: “I wanted to create valuable bottlings that could be auctioned like the greatest single malts or works of art,” fortæller Luca Gargano. “Four great rums produced by four great Master Distillers, selected by me, with an extra touch”. Det ekstra touch skulle være billederne fra Magnum, nærmere bestemt Elliot Erwitt, for Luca er også stor fotografientusiast. Rommen her kommer fra Foursquare Distillery på Barbados. Den er lagret imponerende 16 år og udvalgt og tappet af Velier ved hele 61% alkohol.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnum Series #1 Mount Gay 14 years old 2021', 'https://www.juuls.dk/rom/varekort/magnum-series-1-mount-gay-14-years-old-2021-1', 4719, TRUE, 150, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601088.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601088-Magnum-Series-#1-Mount-Gay-14-years-old-2021.jpg', 'Obs: 1,5 liter Ordet ”magnum” har en helt særlig betydning i vin- og spirituskredse, men i dette tilfælde er betydningen dobbelt: Velier har frigivet en serie af rom, hvor etiketterne prydes af billeder fra det berømte fotograf-kooperativ, Magnum Photos. Og ja, flasken er i magnum-størrelse. Med Magnum Series er Velier ikke bange for at indrømme, at de er skabt som investeringsobjekter: “I wanted to create valuable bottlings that could be auctioned like the greatest single malts or works of art,” fortæller Luca Gargano. “Four great rums produced by four great Master Distillers, selected by me, with an extra touch”. Det ekstra touch skulle være billederne fra Magnum, nærmere bestemt Elliot Erwitt, for Luca er også stor fotografientusiast. Rommen her kommer fra Mount Gay Distillery på Barbados. Den er lagret 14 år og udvalgt og tappet af Velier ved tordnende 60% alkohol.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnum Series #1  Saint James 15 years old 2021', 'https://www.juuls.dk/rom/varekort/magnum-series-1-saint-james-15-years-old-2021-1', 5569, TRUE, 150, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601090.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601090-Magnum-Series-#1--Saint-James-15-years-old-2021.jpg', 'Obs: 1,5 liter Ordet ”magnum” har en helt særlig betydning i vin- og spirituskredse, men i dette tilfælde er betydningen dobbelt: Velier har frigivet en serie af rom, hvor etiketterne prydes af billeder fra det berømte fotograf-kooperativ, Magnum Photos. Og ja, flasken er i magnum-størrelse. Med Magnum Series er Velier ikke bange for at indrømme, at de er skabt som investeringsobjekter: “I wanted to create valuable bottlings that could be auctioned like the greatest single malts or works of art,” fortæller Luca Gargano. “Four great rums produced by four great Master Distillers, selected by me, with an extra touch”. Det ekstra touch skulle være billederne fra Magnum, nærmere bestemt Elliot Erwitt, for Luca er også stor fotografientusiast. Rommen her kommer fra Saint James Distillery på Martinique. Den er lagret 15 år og udvalgt og tappet af Velier ved 45% alkohol.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Blanc Canne Bleue 2021', 'https://www.juuls.dk/rom/varekort/clement-rhum-blanc-canne-bleue-2021', 479, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610220.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610220-Clement-Rhum-Blanc-Canne-Bleue-2021.jpg', '2021-udgaven af Cléments ikoniske Canne Bleue! Den holder absolut kadencen med en intens, forførende duft af diverse urter, grønt græs, melon og våd skovbund. Som altid er den lavet udelukkende på sukkerrør af typen canne bleue, som giver et exceptionelt aromatisk destillat. Tappet ved 50% alkohol uden andre tilsætninger end vand. Farve : Klar. Duft : Boom! En herreintens duft af citrus (yuzu og citron), grønt græs, stjerneanis, melon og friske urter.  Smagsnoter : Grøn og saftig i smagen, som er enormt lang og kompleks, fyldt med de samme noter som duften. Serveringsforslag : Nyd den rent eller i cocktails. Klassikeren er en ti’ punch.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Paranubes Cana Morada Lot. 02-CM-24', 'https://www.juuls.dk/rom/varekort/paranubes-cana-morada-lot-02-cm-24', 459, TRUE, 70, 54.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625259.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625259-Paranubes-Cana-Morada-Lot.-02-CM-24.jpg', 'En længe ventet aftapning fra det lillebitte destilleri i Oaxacas tågeskove. Mens den ”normale” Paranubes er lavet på en blanding af 4 forskellige sorter, er denne udgave lavet udelukkende på én enkelt type sukkerrør: Caña Morada. Her får man altså lov at smage hvordan de forskellige typer adskiller sig i smag: caña morada har en meget krydret og let salt smag. Rommen er gæret på den friske saft fra sukkerrørene og er destilleret på José Luis’ to små kolonnekedler, som fyres med det tørre sukkerrørskvas. Og så er den tappet uden lagring ved smukke 54,4%. Farve : Klar.  Duft : En potent duft af grøn, frisk sukkerrørrsaft, sød kanel og havvand. Smagsnoter : Smagen er stor og intens med maritime noter og eksotiske krydderier. Lang eftersmag. Serveringsforslag : Nyd den rent eller i cocktails – fx i en Mai Tai.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Cane Island Royal New Yarmouth Single Cask #MO72', 'https://www.juuls.dk/rom/varekort/cane-island-royal-new-yarmouth-single-cask-mo72', 3005, TRUE, 70, 60.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644690.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644690-Cane-Island-Royal-New-Yarmouth-Single-Cask-#MO72.jpg', 'Cane Island Royal New Yarmouth Single Cask #MO72 er en rom fra Jamaica. Og hvilken rom! New Yarmouth er ikke et hvilket som helst destilleri. Faktisk kæmper det nok med Hampden om at være øens mest eftertragtede lige pt!Rommen er selvfølgelig tappet i fadstyrke, 60,3%, fra ét fad (nummer MO72). Cane Island Royal New Yarmouth Single Cask #MO72 har en stor fylde og masser af kompleksitet i smagen, hvor man blandt andet finder nuancer af vanilje, kokos og en let "funky" profil, som dog ikke kammer helt over.. Bør nydes rent. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Flora Antillarum Montebello Rhum Vieux 2021', 'https://www.juuls.dk/rom/varekort/flora-antillarum-montebello-rhum-vieux-2021', 4309, TRUE, 70, 41.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625001.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625001-Flora-Antillarum-Montebello-Rhum-Vieux-2021.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Master Blender''s Reserve  2022', 'https://www.juuls.dk/rom/varekort/black-tot-master-blenders-reserve-2022', 1509, TRUE, 70, 54.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642322.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642322-Black-Tot-Master-Blender''s-Reserve--2022.jpg', 'Black Tot Master Blender’s Reserve rom 2022 er en blandingsrom efter bedste britiske navy-tradition. Rommen er sammensat af melassebaseret, lagret rom fra Jamaica, Barbados, Guyana og Trinidad samt rom fra sidste års Master Blender’s udgivelse. Rommen har således mange forskellige lag og smagsnuancer, og er en fejring af roms diversitet.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Australia Beenleigh AD116 Btld for DK 2022', 'https://www.juuls.dk/rom/varekort/cdi-australia-beenleigh-ad116-btld-for-dk-2022', 839, TRUE, 70, 59.1, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640934.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640934-CDI-Australia-Beenleigh-AD116-Btld-for-DK-2022.jpg', 'Benleigh destilleriet i South East Queensland anvender forskellige gærtyper sammen med den lokale australske melasse. Dette giver en dejlig frisk karakter og sødmefuld moden frugt, som yderligere forstærkes af destillationen i kobber Pot Stills. Noter af honning, vanilje og grønt græs i eftersmagen. Rommen er tappet ved fuld fadstyrke, uden tilsætning af sukker eller farve, eksklussivt til det danske marked. Farve : Lys. Duft : Dejlig, frisk duft af moden frugt og nyklippet græs. Smag : Noter af honning, vanilje og grønt græs i eftersmagen. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Barbados Foursquare FBD15 Btld for DK 2022', 'https://www.juuls.dk/rom/varekort/cdi-barbados-foursquare-fbd15-btld-for-dk-2022', 1049, TRUE, 70, 57.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640935.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640935-CDI-Barbados-Foursquare-FBD15-Btld-for-DK-2022.jpg', 'Vi har tappet to søsterfade fra samme batch , fordi vi ved I bare elsker Barbados rom fra Foursquare destilleriet. Rommen er lige efter bogen og fyldt med masser noter af kokos, vanilje, orange og mørk chokolade, samt sprøde toffee noter. Yderst behageligt bekendtskab. Rommen er tappet ved fuld fadstyrke, uden tilsætning af sukker eller farve, eksklussivt til det danske marked. Farve : Mørk. Duft : Behagelig krydret duft. Smag : Powerfuld med noter af kokos, vanilje, orange og mørk chokolade, samt sprøde toffee noter. Serveringsforslag : Bør nydes rent. Se søsterfadet  CDI Barbados Foursquare FBD14 Btld for DK 2022 .', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI La Reunion Savanna DR120 Btld for Denmark 2022', 'https://www.juuls.dk/rom/varekort/cdi-la-reunion-savanna-dr120-btld-for-denmark-2022', 2079, TRUE, 70, 52.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640937.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640937-CDI-La-Reunion-Savanna-DR120-Btld-for-Denmark-2022.jpg', 'Os bekendt er dette fad fra Savanna-destilleriet på La Reunion, en af de ældste aftapninger nogensinde gjort fra dette destilleri. Den er af typen "traditionnel" dvs. gæret på lokal melasse og destilleret på en lille kolonne. Vi har med "konfekt fra allerøverste hylde" at gøre her. Intet mindre end eminent! Rommen er tappet ved fuld fadstyrke, uden tilsætning af sukker eller farve, eksklusivt til det danske marked. Farve : Mørk. Duft : Et væld af mørk chokolade, tørrede figner, orange og violer vælter op af glasset. Smag : Alkoholen er yderst velintegreret og frigiver langsomt noter af stjerne anis, marcipan, abrikos, figen og tobak. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Clarendon Jamaica DJC1 Btld for Denmark 2022', 'https://www.juuls.dk/rom/varekort/cdi-clarendon-jamaica-djc1-btld-for-denmark-2022', 1459, TRUE, 70, 63.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640938.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640938-CDI-Clarendon-Jamaica-DJC1-Btld-for-Denmark-2022.jpg', 'Fuld spræl af de "funky" Jamaica noter. Alt er som det skal være med masser af ananas, søde banan noter og god buldrende alkohol. Alkoholen er farligt godt integreret i smagen og man fornemmer ingenlunde de 63,2 % vol. Det er et temmelig friskt bourbonfad og du finder masser af "lagkage med vaniljecreme" i smagen. Super dejlig action-rom fra Jamaica! Rommen er tappet ved fuld fadstyrke, uden tilsætning af sukker eller farve, eksklussivt til det danske marked. Farve : Mørk. Duft : Frugtig - måske endda lidt overmoden frugt. Smag : Powerfuld! Noter af moden tropisk frugt, vanilje og masser af bourbonfad-karakter! Serveringsforslag : Bør nydes rent!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Clarendon Jamaica DJC16 Btld for Denmark 2022', 'https://www.juuls.dk/rom/varekort/cdi-clarendon-jamaica-djc16-btld-for-denmark-2022', 1819, TRUE, 70, 57.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640939.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640939-CDI-Clarendon-Jamaica-DJC16-Btld-for-Denmark-2022.jpg', 'Nobel og elegant Jamaica rom fra Clarendon Destilleriet med meget fine noter af ananas og grønt løv. Estertallet er ikke enormt men til gengæld er "nydelsesfaktoren" helt i top. Hvis dine kunder kan lide gammel olieret Jamaicarom med noter af røde æbler, mango, ingefær og fed vanilje. Unik og perfekt Jamaica rom til den kræsne gane! Rommen er tappet ved fuld fadstyrke, uden tilsætning af sukker eller farve, eksklussivt til det danske marked. Farve : Mørk. Duft : Tropisk frugt og vegetale noter. Smag : Smag af røde æbler, mango, ingefær og fed vanilje. Serveringsforslag : Bør nydes rent!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Great Whites Overproof Rum fra Vietnam 2022', 'https://www.juuls.dk/rom/varekort/cdi-great-whites-overproof-rum-fra-vietnam-2022', 469, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640585.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640585-CDI-Great-Whites-Overproof-Rum-fra-Vietnam-2022.jpg', 'The Great Whites er Compagnie des Indes’ serie af exceptionelle hvide rom. Omhyggeligt udvalgt fra destillerier i hele verden, for at vise de mest aromatiske og fyldige, hvide rom. Baseret på sukkerrørsjuice eller melasse, og destilleret på pot still eller column still, kan disse rommer variere i stilarter, smag og oprindelse, men de har alle den samme kraftfulde karakter. De aftappes altid som overproof rom ved 50° Alc./Vol. Dette er Vietnam Great White, som er lavet af sukkerrørssaft, og destilleret på en kobber-kolonnekedel i marts 2021 på Quang Nam Distillery. Farve : Klar. Duft : Aromaer af trøffel, humus, friske sukkerrør, sandeltræ og røgelse. Smagsnoter : Lidt iodiseret (som overrasker lidt), Williams pære, lidt træ, hvid te og karamel. Serveringsforslag : Prøv den rent – og prøv derefter i din daiquiri eller mai tai. Florent Beuchet fra Compagni des Indes er begyndt at tappe hvid rom af meget høj kvalitet. Den nye serie "Great Whites", har i første omgang fokus på hvid rom fra Vietnam, Jamaica & Ghana. Hvad enten rommerne er gæret på melasse eller frisk rørsukkerjuice, i kort eller lang tid, og destilleret på kolonne eller i pot still, har de det tilfælles. At de viser masser af karakter og lokale traditioner og kolorit. Kort sagt - en meget stor og spændende romoplevelse.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sepé Ron Blanco ØKO', 'https://www.juuls.dk/rom/varekort/sepe-ron-blanco-oeko', 199, TRUE, 70, 41, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643468.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643468-Sepé-Ron-Blanco-ØKO.jpg', 'Sepé Ron Blanco er en økologisk rom fra Paraguay. Den kommer fra destilleriet Fortín, men er tappet her i Danmark hos Oremandsgaard i Præstø. Rommen er sendt hertil på tank i stedet for i glasflasker, hvilket naturligvis reducerer vægten på forsendelsen – og det betyder noget når den kommer helt fra Paraguay. Da rommen ankom til Oremandsgaard blev den tappet på flasker af ”Wild Glass”, som er en glastype, der bruger 100% ”post-consumer waste” til produktionen. Desuden bliver wild glass-flasker ikke kasseret hvis der skulle være en lille luftboble eller farveforskel – så du kan godt ”risikere” at få en flaske med sin helt egen karakter. Etiketterne er lavet af genbrugspapir og proppen er af noget, der hedder Corkcoal, som også har et mindre carbon footprint end normale korkpropper. Alt i alt giver det en rom, som er lige en lille smule mere bæredygtig end de fleste andre. Selve rommen er lavet på økologisk sukkerrørssaft, som koges ind til sirup før den gæres og destilleres på kolonnekedler. Den er tappet uden tilsætningsstoffer – dvs. nul sukker eller farvestof. Farve : Klar. Duft : Tydeligt præget af sukkerrørssaft: grønne æbler, tyggevitamin, mynte og andre krydderurter. Smagsnoter : Ren og klar smag med hints af hvid glasur, uden at være sød, sukkerrørssaft, nybagt brød og grønne urter. Serveringsforslag : En rom der hører hjemme i en daiquiri, hvor den med sin semi-agricole-profil giver lidt mere funkiness – og det trænger vi da alle sammen til!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Guyana 2007 Teeling Whiskey Juuls V&S', 'https://www.juuls.dk/rom/varekort/plantation-guyana-2007-teeling-whiskey-juuls-v-s', 839, TRUE, 70, 53.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404770.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404770-Plantation-Guyana-2007-Teeling-Whiskey-Juuls-V&S.jpg', '13 år på bourbonfade i troperne, 1 år på cognac-fade i Frankrig og 7 måneder på et irsk whiskey-fad. Det er opskriften på denne fantastiske limited edition-aftapning fra Plantation Rum. Udgangspunktet er en stovt og kraftig rom fra Guyana, destilleret på pot still i 2007. Vi er glade for, at vi fik lov at tappe denne rom udelukkende til Juuls, for den smager simpelthen fantastisk! 53,6% alkohol og nul tilsat sukker. Farve : Rav. Duft : Rig og krydret duft af brændt egetræ, nellike, peber og honning. Smagsnoter : De samme krydrede noter fra duften, men også mere frugtighed i form af stenfrugt, blomme og ahornsirup. Serveringsforslag : Nyd den rent af et tulipan-formet glas.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Jamaica 2009 Orange Wine Denmark', 'https://www.juuls.dk/rom/varekort/plantation-jamaica-2009-orange-wine-denmark', 789, TRUE, 70, 53, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404776.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404776-Plantation-Jamaica-2009-Orange-Wine-Denmark.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Uitvlugt Enmore 2008 bottled 2019', 'https://www.juuls.dk/rom/varekort/el-dorado-uitvlugt-enmore-2008-bottled-2019', 1405, TRUE, 70, 47.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646370.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646370-El-Dorado-Uitvlugt-Enmore-2008-bottled-2019.jpg', 'El Dorado Uitvlugt Enmore 2008 bottled 2019 er en rom fra Guyana. Den er lavet på sukkerrørsmelasse. Den er tappet i såkaldt cask strength, som her er 47,4%. De lækre noter af varme krydderier, tobak og tørret frugt gør den til en favorit hos mange. Bør nydes rent. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Diamond Port Mourant 2010 btld 2019', 'https://www.juuls.dk/rom/varekort/el-dorado-diamond-port-mourant-2010-btld-2019', 1405, TRUE, 70, 49.1, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646371.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646371-El-Dorado-Diamond-Port-Mourant-2010-btld-2019.jpg', 'El Dorado Diamond Port Mourant 2010 btld 2019 er en rom fra Guyana. Den er lavet på sukkerrørsmelasse. Den tappes i cask strength, og her er alkoholindholdet 49,1%. Du kan forvente en flot fyldighed og noter af vanilje, varme krydderier, chokolade og egetræ. Bør nydes rent. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Port Mourant Uitvlugt Diamond 2010', 'https://www.juuls.dk/rom/varekort/el-dorado-port-mourant-uitvlugt-diamond-2010', 1405, TRUE, 70, 49.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646372.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646372-El-Dorado-Port-Mourant-Uitvlugt-Diamond-2010.jpg', 'El Dorado Port Mourant Uitvlugt Diamond 2010 er en rom fra Guyana. Den er lavet på sukkerrørsmelasse. Den tappes i cask strength, og her er alkoholindholdet 49,6%. El Dorado Port Mourant Uitvlugt Diamond 2010 har en stor fylde og masser af kompleksitet i smagen, hvor man blandt andet finder nuancer af karamel, honning og varme krydderier. Bør nydes rent. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Uitvlugt Port Mourant 2010 bottled 2019', 'https://www.juuls.dk/rom/varekort/el-dorado-uitvlugt-port-mourant-2010-bottled-2019', 1405, TRUE, 70, 51, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646373.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646373-El-Dorado-Uitvlugt-Port-Mourant-2010-bottled-2019.jpg', 'El Dorado Uitvlugt Port Mourant 2010 bottled 2019 er en rom fra Guyana. Den er lavet på sukkerrørsmelasse. Den er tappet i såkaldt cask strength, som her er 51%. I smagen finder man både egetræ og karamel og varme krydderier - og der er masser af power! Bør nydes rent. Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnifica Envelhecida Cachaca', 'https://www.juuls.dk/rom/varekort/magnifica-envelhecida-cachaca', 339, TRUE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646847.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646847-Magnifica-Envelhecida-Cachaca.jpg', 'Magnifica Envelhecida Cachaca er en Cachaca fra Brasilien, hvor den produceres ca 110 kilometer fra Rio de Janeiro. Den laves af saft fra sukkerrør, og lagres i to år på egetræ efter destillation. Farve : Gylden. Duft : Floral, grønt græs. Smagsnoter : Frugtig, krydret karamel med træ. Serveringsforslag : Nyd den ren, eller i Brasiliens nationalcocktail caipirinha.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Colon Salvadoreno Dark Aged Rum', 'https://www.juuls.dk/rom/varekort/ron-colon-salvadoreno-dark-aged-rum', 289, TRUE, 70, 55.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643201.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643201-Ron-Colon-Salvadoreno-Dark-Aged-Rum.jpg', 'Ron Colon Salvadoreno Dark Aged Rum er en blanding af forskellige rommer: 6 år gammel rom fra El Salvador, destilleret på Licorera Cihuatán, ulagrede rommer fra Jamaica-destillerierne Worthy Park, Hampden og Monymusk, samt 3 år gammel rom fra Worthy Park. Efter endt lagring på de respektive destillerier bringes rommen til Holland, hvor den aftappes. Farve : Gylden Duft : Tropisk frugt med frisk banan og ananas, samt rosin og svesker. Smagsnoter : Tropisk frugt med karamel, mælkechokolade ristede mandler og abrikos. Serveringsforslag : Bør drikkes rent med en isterning eller i en cocktail!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate HLCF Overproof Gaveæske med 2 Glas', 'https://www.juuls.dk/rom/varekort/hampden-estate-hlcf-overproof-gaveaeske-med-2-glas', 1049, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643792.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643792-Hampden-Estate-HLCF-Overproof-Gaveæske-med-2-Glas.jpg', 'Hampden Estate HLCF er klassisk Jamaica-rom , når det er bedst! Ung (men tropisk lagret), potent og rimelig høj på esters.  Her får du 2 smukke tumbler-glas fra Riedel med i købet - og "bogen", de er pakket i, indeholder både facts, historie og cocktail-opskrifter. Farve : Gylden. Duft : Mentol, grillede bananer, citrusskaller og acetone. Smagsnoter : Masser af power, tropisk frugt og kandiseret citron. Serveringsforslag : Nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('TDSC Colombian Rum 30YO Juuls Single Cask 2017', 'https://www.juuls.dk/rom/varekort/tdsc-colombian-rum-30yo-juuls-single-cask-2017', 4009, TRUE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641825.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641825-TDSC-Colombian-Rum-30YO-Juuls-Single-Cask-2017.jpg', 'The Distinctive Spirits Co. (eller TDSC) har fremtryllet to fuldstændig unikke og uhørt gamle fade med udsøgt rom fra Destilería Colombiana. Dem har vi takket ja til at tappe eksklusivt til Juuls! Rommen her er destilleret i 1987 og oprindeligt tappet i 2017, for så at blive ”re-bottled” af TDSC i 2022. Det giver en alder på 30 år, hvoraf 36 måneder i øvrigt er en finish på whiskey-fade. I alt kunne det blive til 282 flasker ved 45% alkohol. Farve : Let mahogni. Duft : Så for søren. Efter et par minutters ilt vælter en sindssygt dyb, intens og mørk duft af brun farin og brændt sukker op af glasset. Lidt efter følger bagt banan overhældt med karamel og drysset med varme krydderier. Smagsnoter : På trods af en ”næse” der svømmer i karamel og sukker, så er rommen ret tør på tungen – kraftig, kompleks og med en lang, lang eftersmag. Her fornemmes også gammelt træ, nellike og ægte kanel. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Secrete Cuba CD132 Btld for Denmark 2022', 'https://www.juuls.dk/rom/varekort/cdi-secrete-cuba-cd132-btld-for-denmark-2022', 939, TRUE, 70, 57.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640941.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640941-CDI-Secrete-Cuba-CD132-Btld-for-Denmark-2022.jpg', 'Det er desværre alt for sjældent vi får lejlighed til at smage gammel Cuba rom ved fadstyrke. Det er en skam for de fine lette rommer fra Cuba vinder utroligt meget ved at blive koncentreret. Ristede nødder, granola med honning, en overflod af karamel og vanilje findes i duft og smag, Afstemte noter af kaffe med mælk, mørk chokolade og orange noter runder meget fint denne eksil cubaner af. Kæmpe nydelse og stor elegance! Rommen er tappet ved fuld fadstyrke, uden tilsætning af sukker eller farve, eksklussivt til det danske marked. Farve : Mørk. Duft : Duft af ristede nødder, granola med honning, en overflod af karamel og vanilje Smag : Powefuld, men enormt behagelig, ligesom kaffe med mælk eller mørk chokolade. Serveringsforslag : Bør nydes rent!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Reisetbauer 4x7 X.O Prime Rum', 'https://www.juuls.dk/rom/varekort/reisetbauer-4x7-x-o-prime-rum', 649, TRUE, 50, 40.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640001.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640001-Reisetbauer-4x7-X.O-Prime-Rum.jpg', 'Reisetbauers nyeste kreation, 4X7 X.O Single Vintage Prime Rum, er en spændende blanding af rom fra Jamaica og Reisetbauers egen produktion. Hans Reisetbauer laver nogle af verdens fineste eau de vie’er, men har for nyligt kastet sig over rommen – til manges store jubel!  Han køber fair-trade melasse fra Mauritius, gærer, destillerer og lagrer den i Axberg. Denne cuvée er 50% Jamaica, 50% Axberg! Tappet ved 40,5%. Den findes også i en 70 cl-udgave, som du finder her. Farve : Rav. Duft : Harmonisk og balanceret, med noter af tropisk frugt og vanilje. Smagsnoter : Krydrede vaniljenoter, fuldmoden, tropisk frugt og let karamelagtig sødme. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sol Tarasco Charanda Rum 8 Years Single Cask 221', 'https://www.juuls.dk/rom/varekort/sol-tarasco-charanda-rum-8-years-single-cask-221', 749, TRUE, 70, 50.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625801.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625801-Sol-Tarasco-Charanda-Rum-8-Years-Single-Cask-221.jpg', 'Endelig får vi lov at smage en Full Proof-rom fra Sol Tarasco, det lille destilleri i Michoacan, Mexico. ”Full Proof” betyder, at rommen ikke er tilsat vand efter destillationen. Man kalder det også for cask strength. Det betyder, ganske enkelt, mere smag! Rommen er lavet på 100% ”High Mountain Sugar Cane”, destilleret 2 gange på små kobberkedler og lagret 8 lange år på bourbonfade. Farve : Rav. Duft : Noter af karamel, mørk chokolade, kaffe, manukahonning og gammelt træ. Smagsnoter : Tæt og intens i smagen hvor de samme noter fra duften går igen – især kaffen og chokoladen – men også rosin, sveske og varme krydderier. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Papa Rouyo White', 'https://www.juuls.dk/rom/varekort/habitation-velier-papa-rouyo-white', 999, TRUE, 70, 62, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643698.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643698-Habitation-Velier-Papa-Rouyo-White.jpg', 'Denne flaske er begrænset til én per kunde. Produktet er ekskluderet fra alle rabatkoder.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('HAMPDEN Coffret 8 Marks Collection', 'https://www.juuls.dk/rom/varekort/hampden-coffret-8-marks-collection', 1659, TRUE, 20, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643758.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643758-HAMPDEN-Coffret-8-Marks-Collection.jpg', 'Så er der guf til romnørderne! I denne kasse får du 8 ”små” flasker (20 cl) med de forskellige marks hos Hampden, så du kan smage dig igennem hele striben fra OWH til DOK. Rommen er tappet uden lagring, og alle ved 60% alkohol. Der medfølger også lidt historie og facts og Hampdens unikke produktion. Kassen indeholder: • OWH (40-80 g/hL alc.) • LFCH (80-120 g/hL alc.) • LROK (200-400 g/hL alc.) • HLCF (400-600 g/hL alc.) • <>H (900-1000 g/hL alc.) • HGML (1000-1100 g/hL alc.) • C<>H (1300-1400 g/hL alc.) • DOK (1500-1600 g/hL alc.)', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('PROVIDENCE 2019', 'https://www.juuls.dk/rom/varekort/providence-2019', 939, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643756.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643756-PROVIDENCE-2019.jpg', 'Dette produkt er ekskluderet fra alle rabatkoder​ Den første lagrede rom fra Providence og Distillerie de Port-au-Prince i Haiti ! De tre år er tilbragt på fade, der har indeholdt Caroni, og i kombination med det tropiske klima, har det har sat et tydeligt præg på rommen. Rommen er gæret på sukkerrørssirup og destillationen er foregået på en bain-marie still fra Müller. Den er tappet ved 52% alkohol. Farve : Let gylden. Duft : Florale noter (rose, geranium) blander sig med tropisk frugt som grillet ananas og banan. Smagsnoter : Tyk og cremet mundfølelse, med noter af tobak, brændt banan, blomster og varme krydderier. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Boulet de Canon No. 13', 'https://www.juuls.dk/rom/varekort/cdi-boulet-de-canon-no-13', 649, TRUE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640649.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640649-CDI-Boulet-de-Canon-No.-13.jpg', 'Serien Boulet de Canon (”Kanonkugle”) fra Compagnie des Indes er nået til sin 13. udgave. Rommen er et blend af destillater fra Nicaragua og Panama, som er ”finished” på et fad, der har indeholdt røget whisky fra øen Islay . Og som om det ikke var nok, er den efterfølgende infuseret med røget hø, hvilket giver denne rom en enormt interessant og kompleks karakter. Den er tappet ved 46% uden kølefiltrering. Farve : Mørk gylden. Duft : Spændende duft af grillet kød, karamel, tobak og aske.  Smagsnoter : Flot power og masser af røg og tørv, samt noter af krydderurter (oregano, rosmarin) og ristet malt. Serveringsforslag : Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sepé Ron Blanco 10L ØKO', 'https://www.juuls.dk/rom/varekort/sepe-ron-blanco-10l-oeko', 2369, TRUE, 1000, 41, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601868-Sepé-Ron-Blanco-10L-ØKO.jpg', 'Hele 10 liter af Sepé Ron Blanco, vores økologiske rom fra Paraguay. Den kommer fra destilleriet Fortín, men er tappet her i Danmark hos Oremandsgaard i Præstø. Rommen er sendt hertil på tank i stedet for i glasflasker, hvilket naturligvis reducerer vægten på forsendelsen – og det betyder noget når den kommer helt fra Paraguay. Selve rommen er lavet på økologisk sukkerrørssaft, som koges ind til sirup før den gæres og destilleres på kolonnekedler. Den er tappet uden tilsætningsstoffer – dvs. nul sukker eller farvestof. Farve : Klar. Duft : Tydeligt præget af sukkerrørssaft: grønne æbler, tyggevitamin, mynte og andre krydderurter. Smagsnoter : Ren og klar smag med hints af hvid glasur, uden at være sød, sukkerrørssaft, nybagt brød og grønne urter. Serveringsforslag : En rom der hører hjemme i en daiquiri, hvor den med sin semi-agricole-profil giver lidt mere funkiness – og det trænger vi da alle sammen til!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Blanc Canne Bleue 2022', 'https://www.juuls.dk/rom/varekort/clement-rhum-blanc-canne-bleue-2022', 479, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610221.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610221-Clement-Rhum-Blanc-Canne-Bleue-2022.jpg', 'Vi er nået til 2022-udgaven af Canne Bleue fra Clement, der betragtes som den første rhum agricole, der er destilleret på én slags sukkerrør. Typen Canne Bleue har fået sit navn fra de blålilla fortegninger på rørene, og den er også kendt for en ekstraordinært frugtig smag og aroma. Det er altså lidt af en luksus-rom, det her, og virkelig guf for agricole-nørder. Rommen er tappet ved 50%, og ikke tilsat sukker. Farve : Klar. Duft : Eksplosiv duft af citrusnoter a la lime eller yuzu, stjerneanis og urtete. Smagsnoter : Smagen er kraftig og intens, med florale og grønne noter, stjerneanis igen og et strejf af honning – om end den er dejligt tør. Serveringsforslag : Nyd den rent, i ti’ punch eller andre cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Last Cask Gold', 'https://www.juuls.dk/rom/varekort/el-dorado-last-cask-gold', 2985, TRUE, 70, 54.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646387.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646387-El-Dorado-Last-Cask-Gold.jpg', 'Serien The Last Casks fra El Dorado indeholder noget af det ypperligste, det legendariske destilleri i Guyana kan præstere. The Last Casks Gold er en rom fra år 2000, destilleret på El Dorados Diamond Coffey Still og lagret på gamle Uitvlugt-fade. 22 års tropisk lagring, du! Den er tappet ved 54,4% alkohol uden tilsat sukker. En rom til nørder og nørder in spe! Farve : Rav. Duft : Stor aroma af melasse og brændt sukker, ristet kokosnød og gammelt egetræ. Smagsnoter : Lakrids, moden frugt og varme krydderier. Et drøn af en rom. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Last Cask Black', 'https://www.juuls.dk/rom/varekort/el-dorado-last-cask-black', 2985, TRUE, 70, 50.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646388.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646388-El-Dorado-Last-Cask-Black.jpg', 'Serien The Last Casks fra El Dorado indeholder noget af det ypperligste, det legendariske destilleri i Guyana kan præstere. The Last Casks Black er en lidt usædvanlig rom, sammensat af en komponent som er ”redestilleret” på en Tri-Canada Still blandet med Port Mourant og Enmore. Den er tappet ved 50,3% efter 24 års tropisk lagring! Farve : Rav. Duft : Honning og mørk karamel som drypper langsomt nedover gamle jernbanesveller. Svesker, rosin, og mørk chokolade runder duften af. Smagsnoter :  Behageligt fyldig, tør og kraftig rom. Noter af tørret frugt, appelsinskal, melasse og chokolade. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado Last Cask Red', 'https://www.juuls.dk/rom/varekort/el-dorado-last-cask-red', 2985, TRUE, 70, 49.1, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646389.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646389-El-Dorado-Last-Cask-Red.jpg', 'I serien The Last Casks har El Dorado tappet noget af det fineste rom, det legendariske destilleri i Guyana har på lager. The Last Casks Red er en blanding af rom fra Diamond Coffey Still og den nu pensionerede Tri-Canada Still, begge komponenter fra 1998. Den er tappet ved 49,1%. Farve : Ravgylden.  Duft : Ristede nødder, honning, brændt karamel og egetræ. Dejlig, kompleks duft. Smagsnoter : Tæt og intens smag med noter af tørret frugt, træ, banan og karamel. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Vieux Single Batch 100% Canne Bleue', 'https://www.juuls.dk/rom/varekort/clement-rhum-vieux-single-batch-100-canne-bleue', 639, TRUE, 50, 46.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50611817.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50611817-Clement-Rhum-Vieux-Single-Batch-100%-Canne-Bleue.jpg', 'Tjek lige denne single batch rom fra Clément på Martinique. Den er lavet på frisk sukkerrørssaft, som alt fra Clément, men her kun én enkelt slags: nemlig den legendariske canne bleue. Tappet ved 46,5%. Farve : Rav. Duft : Lækker blanding af frugt og krydderi (pære, muskatnød, vanilje).   Smagsnoter : Tør rom, men dog med en vis naturlig sødme. Tropisk frugt og grønne urter. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Vieux Single Batch Chauffe Extreme', 'https://www.juuls.dk/rom/varekort/clement-rhum-vieux-single-batch-chauffe-extreme', 569, TRUE, 50, 46.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50611818.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50611818-Clement-Rhum-Vieux-Single-Batch-Chauffe-Extreme.jpg', 'Chauffe Extreme er en single batch rom fra Clément på Martinique. Den er lavet på frisk sukkerrørssaft, som alt fra Clément, men har fået en helt speciel lagring: 5 år på nye, amerikanske egetræsfade, der har fået særligt hård varme under ristningen. Rommen er tappet ved 46,9% og er ikke tilsat sukker. Farve : Rav. Duft : Flot kompleksitet med noter af kanel, friskristet kaffe og vanilje.   Smagsnoter : På tungen er rommen tør, men man fornemmer alligevel en lækker, naturlig vaniljesødme samt lakridsnoter og cappuccino. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('East London Liquor Company Rum', 'https://www.juuls.dk/rom/varekort/east-london-liquor-company-rum', 319, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644580.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644580-East-London-Liquor-Company-Rum.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Master Blender''s Reserve 2023', 'https://www.juuls.dk/rom/varekort/black-tot-master-blenders-reserve-2023', 1659, TRUE, 70, 54.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642323.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642323-Black-Tot-Master-Blender''s-Reserve-2023.jpg', 'Max 1 flaske per kunde Denne aftapning er ekskluderet fra alle rabatkoder Hvert år laver Master Blender Oliver Chilton en ny udgave af Black Tot Master Blender’s Reserve og i år er der fokus på den mørke, kraftige side af navy-rommen: Guyana! Komponenterne fra Guyana udgør i år over 30% af rommen, og det er altså rom med en alder på op til 31 år. Som noget helt nyt indeholder rommen også en komponent fra Grenada, destilleret i 1993 og lagret tropisk i 15 år og kontinentalt i 13. Jøsses! Derudover er da selvfølgelig lidt godt fra Jamaica, Trinidad og Barbados. Rommen er ikke tilsat sukker og ikke kølefiltreret – og så er den tappet ved dejlige 54,5%. Farve : Mørkt rav. Duft : Dyb, spændende duft af appelsin stukket med nelliker, ruby portvin, kanel og lakrids. Smagsnoter : Intens, tør og kraftig på tungen, hvor toffee og rosin langsomt afløses af muskatnød og lakrids. Serveringsforslag : Nydes nok bedst rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Art of Rum VAST #1', 'https://www.juuls.dk/rom/varekort/savanna-art-of-rum-vast-1', 1509, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615485.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615485-Savanna-Art-of-Rum-VAST-#1.jpg', 'Savanna ”Art of Rum” by VAST er en gammel rhum traditionnel (det vil sige melassebaseret rom) fra Reunion . I denne limited edition-serie er hver flaske og kasse udsmykket af en kunstner fra Reunion, og VAST er den første udgivelse. Den er sammensat af 2 fade med meget gammel rhum traditionnel destilleret på Savannas C20-kolonne, og to formentlig lidt yngre fade med rom destilleret på deres Savalle-kedel. Tappet ved 52% alkohol, uden tilsat sukker eller farvestof. Farve : Rav. Duft : Frisk og frugtig rom, også med let ”woody”, balsamiske og vaniljeagtige noter. Smagsnoter : Harmonisk og balanceret mellem tropisk frugt, mentol og lakrids. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Trad G', 'https://www.juuls.dk/rom/varekort/savanna-trad-g', 589, TRUE, 50, 69, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615487.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615487-Savanna-Trad-G.jpg', 'Savanna Trad G er en rom lidt udover det sædvanlige. Den intense duft og smag er resultatet af en ekstra lang gæring: hele 6 dage. Under den lange gæring udvikles aromaen til noget ganske unikt, og denne type rom – ”high ester” – er netop Savannas speciale. Rommen er lavet på sukkerrørsmelasse og tappet ved 69% - nice! Farve : Klar. Duft : Voldsomt intens duft af overmoden tropefrugt, oliven, jod og grapefrugt. Smagsnoter : Kraftige frugtnoter, en snert af havvand, oliven og grønne urter. Serveringsforslag : Brug den som EPO i dine cocktails!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier SVM 11ans Rum MMW Tropical Aging Wedderburn', 'https://www.juuls.dk/rom/varekort/velier-svm-11ans-rum-mmw-tropical-aging-wedderburn', 1205, TRUE, 70, 69.1, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643701.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643701-Velier-SVM-11ans-Rum-MMW-Tropical-Aging-Wedderburn.jpg', 'Max 1 flaske per kunde Det er et velkendt fænomen i spiritusverdenen, at det klima, hvor spiritussen lagres, har stor indflydelse på smagen. Nu får vi, for første gang nogensinde, en release hvor der sættes fokus på netop dette!  Eksperimentet er opstået i et yderst sjældent samarbejde mellem italienske Velier og E&A Scheer i Amsterdam, og de har sammen tappet fire forskellige rom i to ”sæt”. Rommene kommer alle fra samme destilleri, Monymusk, men er lagret henholdsvis ”kontinentalt” og ”tropisk” – og der er store forskelle! Dette er en 11 år gammel ”Wedderburn”-rom sammenstukket af to fade fra 2008 og 10 fra 2007, lagret udelukkende på Jamaica. Den er tappet ved fadstyrke: 69,1%. Farve : Mørkt rav. Duft : I duften finder vi en blanding af varme krydderier (nellike, kanel, kakao) og tropisk frugt som banan og abrikos. Smagsnoter : Kraftig alkohol – det kommer man ikke uden om – men åbner sig fint med frugtige noter, peber, nellike og masser af egetræ. Serveringsforslag : Bør nydes rent, gerne med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier SVM 14ans Rum EMB Tropical Aging Plummer', 'https://www.juuls.dk/rom/varekort/velier-svm-14ans-rum-emb-tropical-aging-plummer', 1260, TRUE, 70, 69.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643703_box.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643703-Velier-SVM-14ans-Rum-EMB-Tropical-Aging-Plummer.jpg', 'Max 1 flaske per kunde Det er et velkendt fænomen i spiritusverdenen, at det klima, hvor spiritussen lagres, har stor indflydelse på smagen. Nu får vi, for første gang nogensinde, en release hvor der sættes fokus på netop dette!  Eksperimentet er opstået i et yderst sjældent samarbejde mellem italienske Velier og E&A Scheer i Amsterdam, og de har sammen tappet fire forskellige rom i to ”sæt”. Rommene kommer alle fra samme destilleri, Monymusk, men er lagret henholdsvis ”kontinentalt” og ”tropisk” – og der er store forskelle! Dette er en 11 år gammel ”Plummer”-rom sammenstukket af 10 fade fra 2006, 2 fra 2004 og 4 fra 2002, lagret udelukkende på Jamaica. Den er tappet ved fadstyrke: 69,7%. Farve : Flot, mørk ravfarve. Duft : I starten er alkoholen enormt kraftig, med noter af egetræ, banan, acetone, tobak og terpentin.  Smagsnoter : Intens alkohol og varme noter af kakao, tjære, mint, diesel og hints af tropisk frugt. Serveringsforslag : Bør nydes rent, gerne med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier SVM Rum 2 bottles MMW Wedderburn 11 years', 'https://www.juuls.dk/rom/varekort/velier-svm-rum-2-bottles-mmw-wedderburn-11-years', 2005, TRUE, 70, 63.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643704.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643704-Velier-SVM-Rum-2-bottles-MMW-Wedderburn-11-years.jpg', 'Det er et velkendt fænomen i spiritusverdenen, at det klima, hvor spiritussen lagres, har stor indflydelse på smagen. Nu får vi, for første gang nogensinde, en release hvor der sættes fokus på netop dette!  Eksperimentet er opstået i et yderst sjældent samarbejde mellem italienske Velier og E&A Scheer i Amsterdam, og de har sammen tappet fire forskellige rom i to ”sæt”. Rommene kommer alle fra samme destilleri, Monymusk, men er lagret henholdsvis ”kontinentalt” og ”tropisk” – og der er store forskelle! Dette sæt indeholder 2 flasker rom, begge ”MMW Wedderburn” fra Monymusk – men mens den ene har tilbragt hele sit liv i Jamaica, er den anden lagret i Europa', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier SVM Rum 2 bottles EMB Plummer 14 years', 'https://www.juuls.dk/rom/varekort/velier-svm-rum-2-bottles-emb-plummer-14-years', 2205, TRUE, 70, 67.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643705.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643705-Velier-SVM-Rum-2-bottles-EMB-Plummer-14-years.jpg', 'Max 1 sæt per kunde Det er et velkendt fænomen i spiritusverdenen, at det klima, hvor spiritussen lagres, har stor indflydelse på smagen. Nu får vi, for første gang nogensinde, en release hvor der sættes fokus på netop dette!  Eksperimentet er opstået i et yderst sjældent samarbejde mellem italienske Velier og E&A Scheer i Amsterdam, og de har sammen tappet fire forskellige rom i to ”sæt”. Rommene kommer alle fra samme destilleri, Monymusk, men er lagret henholdsvis ”kontinentalt” og ”tropisk” – og der er store forskelle! Dette sæt indeholder 2 flasker rom, begge ”EMB Plummer” fra Monymusk – men mens den ene har tilbragt hele sit liv i Jamaica, er den anden lagret i Europa.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bayou Rum Reserve', 'https://www.juuls.dk/rom/varekort/bayou-rum-reserve', 339, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644660.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644660-Bayou-Rum-Reserve.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bayou Rum White', 'https://www.juuls.dk/rom/varekort/bayou-rum-white', 229, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644661.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644661-Bayou-Rum-White.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Lontan Blanc 57.5', 'https://www.juuls.dk/rom/varekort/savanna-lontan-blanc-57-5', 489, TRUE, 70, 57.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615491.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615491-Savanna-Lontan-Blanc-57.5.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Vieux Sajous 5 ans 2018', 'https://www.juuls.dk/rom/varekort/vieux-sajous-5-ans-2018', 1049, TRUE, 70, 57.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625229.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625229-Vieux-Sajous-5-ans-2018.jpg', 'Vieux Sajous er en lagret udgave af den populære haitianske rom, clairin, og nærmere bestemt clairinen fra Michel Sajous – en af landets absolut bedste destillatører. Hele 5 år har rommen ligget på fad i Haitis tropiske klima, og det er både romfade (fra Bielle, Mount Gay og Caroni) samt whiskyfade (single malt og bourbon). Den er tappet ved 57,5% alkohol i 2.860 eksemplarer. Farve : Gylden. Duft : Kraftig men raffineret duft af geranium, kiwi, honning og frisk sukkerrørssaft. Smagsnoter : Urtet og krydret, tæt pakket med kanel, ingefær og smeltende rørsukker – men vidunderligt tør naturligvis! Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Amparo Ron Equatorial', 'https://www.juuls.dk/rom/varekort/el-amparo-ron-equatorial', 579, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50630001.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50630001-El-Amparo-Ron-Equatorial.jpg', 'El Amparo er en pure single rum fra Ecuador. Rommen , her kendt som aguardiente, nydes lokalt i stor stil, men har indtil nu været relativt ukendt på verdensmarkedet, hvor nysgerrige romnørder ellers flittigt afsøger hver en krog. Denne aftapning fejrer 60 år og tre generationers romproduktion i familien Zorilla, som bor i byen Jipijapa vest for Andesbjergene. El Amparo bruger sukkerrør af sorten cubana negra , som høstes med machete mellem september og januar når de er omtrent 18 måneder gamle. Gæringen starter med naturlig gær og varer mellem 5 og 7 dage, hvorefter washen destilleres på en 500-liter kobber-batch still til cirka 60%. Den er altså tappet ved ”still proof” – destillationsstyrke. Farve : Klar. Duft : Superintens duft af moden banan og nyslået græs, frisk havluft og regnvåde fyrretræer. Smagsnoter : Endnu mere tropisk i smagen, igen med banan men også ananas, blomster og grønne korianderfrø. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('PROVIDENCE 2020', 'https://www.juuls.dk/rom/varekort/providence-2020', 1049, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643697.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643697-PROVIDENCE-2020.jpg', 'Nyeste udgave af Providence – Luca Garganos destilleri på Haiti – er en årgang 2020 lagret 3 år på fade, der har indeholdt rom fra selvsamme destilleri. Rommen laves på en Müller-pot still af indkogt sirup fra sukkerrør af sorten cristalline. Den er tappet ved 52% alkohol og ikke tilsat sukker. Farve : Let gylden. Duft : En ret kompleks og spændende duft af bl.a. limeskal, banan, lak og krydderurter. Smagsnoter : Tør og frisk med honningnoter, hvid chokolade, vanilje og fine blomsternoter. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Distillerie Port Au Prince White', 'https://www.juuls.dk/rom/varekort/habitation-velier-distillerie-port-au-prince-white', 939, TRUE, 70, 59, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643694.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643694-Habitation-Velier-Distillerie-Port-Au-Prince-White.jpg', 'Habitation Velier er taget et smut forbi Distillerie du Port au Prince for at hente denne sublime hvide rom, lavet udelukkende på sukkerrørssorten cristalline. Den er dobbelt-destilleret på pot still, første gang i Saint Michel de l’Attalaye hvor sukkerrørene dyrkes, og anden gang ved Distilerie du Port au Prince. Den er tappet ved ”high proof”: 59% alkohol, uden tilsat sukker. Farve : Klar.  Duft : Intense noter af guava, honning og nyslået græs. Smagsnoter : Kompleks og livlig på tungen, fyldt med tropisk frugt, ananas især, hvid peber og kokos. Serveringsforslag : Kan nydes rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Caroni Juuls full Proof Single Cask', 'https://www.juuls.dk/rom/varekort/caroni-juuls-full-proof-single-cask', 51519, TRUE, 70, 70.2, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643685.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643685-Caroni-Juuls-full-Proof-Single-Cask.jpg', 'Caroni Juuls Full Proof Single Cask 2000 er en enkeltfadsaftapning af den sjældne rom fra Caroni – et nu lukket destilleri i Trinidad. Juul’s Vin og Spiritus har allernådigst fået lov at købe et helt fad af den store kultrom, og efter 15 år i Trinidads tropiske klima har de grådige engle nået at suge hele 71% af rommen til sig! Den smule, der var tilbage, kunne tappes ved 70,2% alkohol. Et voldsomt, intenst monster af en rom! Farve : Mahogni. Duft : Superintens duft af tørrede roser, engelsk lakrids, nylagt asfalt og eukalyptus. Smagsnoter : Først kraftig alkohol, men når munden har vendt sig til det kommer bølger af smag; brændt melasse, anis, eukalyptus, solbær og mørk chokolade.  Serveringsforslag : Bør nydes rent, evt. med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Panama 11 years DK', 'https://www.juuls.dk/rom/varekort/cdi-panama-11-years-dk', 679, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640780-CDI-Panama-11-years-DK.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('PAPALIN 10 ans REUNION', 'https://www.juuls.dk/rom/varekort/papalin-10-ans-reunion', 969, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615475.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615475-PAPALIN-10-ans-REUNION.jpg', 'Den nyeste Papalin fra Velier er lidt af en smagsbombe! Den er sammensat af 4 forskellige rom, hvoraf 3 er rhum traditionnel og den fjerde en såkaldt "grande arome" - en heftig, smagstæt romtype, som sætter et markant præg på helheden. Alle komponenter er lagret tropisk og mellem 10 og 15 år gamle. Det giver næsten sig selv, at resultatet er fremragende og absolut nørdeguf! Tappet ved 50%. Farve : Rav. Duft : Dybe, krydrede og komplekse noter af mørk chokolade, kandiserede citrusfrugter og moden mango. Smagsnoter : Tør og potent med noter af tropisk frugt, ingefær og stenfrugt. Lang eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('LONG POND 2005 Cambridge STCE', 'https://www.juuls.dk/rom/varekort/long-pond-2005-cambridge-stce', 2929, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643737.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643737-LONG-POND-2005-Cambridge-STCE.jpg', 'STC♥E er et af de mest elskede marques fra Long Pond Distillery, og derfor er der altid stor opstandelse når Velier frigiver en aftapning med denne titel. Forkortelsen står for Simon Thompson Cambridge Estate, og rommen er en reproduktion af den rom, man lavede på dét destilleri (lukket i 1947). Præcis hvor hjertet kommer fra, ved vi ikke, men vi elsker det! Denne gang er det dog noget helt særligt, for der er tale om en Cambridge med intet mindre end 18 års tropisk lagring! Den holder 60% alkohol og der er tappet 3.280 flasker.  Farve : Mørkt rav. Duft : Se dét er en rigtig Jamaica-næse! Kakaopulver, kaprifolie, brændt gummi, kaffe og ingefær. Smagsnoter : Buldrer derudad med kraftige, frugtige noter (stenfrugt og tropisk frugt), honning, havsalt og karamel. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Hampden OWH 7 ans 2016', 'https://www.juuls.dk/rom/varekort/habitation-velier-hampden-owh-7-ans-2016', 1409, TRUE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643738.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643738-Habitation-Velier-Hampden-OWH-7-ans-2016.jpg', 'Så er der frisk Hampden fra Veliers populære serie, Habitation Velier. Her er det en 7 år gammel rom – tropisk lagring på bourbonfade selvfølgelig – i kategorien OWH. Den er tappet ved fadstyrke, 60%, og på de 7 år har Jamaicas grådige engle slubret hele 42% af den oprindelige volumen i sig! Man forstår godt, at den rom, der er tilbage, er både voldsomt koncentreret… og ret så kostbar. Farve : Gylden. Duft : Et brag af en ”næse” med kamfer og mynte, banan, ananas og brændt sukker. Smagsnoter : Smuk, ”moderat” Jamaica, der ganske vist har masser af tropisk frugt, men uden at være domineret af funk. Honning, tjære og gummibånd i baggrunden. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CARONI 2000 Heavy Trinidad Rum Paradise #5', 'https://www.juuls.dk/rom/varekort/caroni-2000-heavy-trinidad-rum-paradise-5', 27009, TRUE, 70, 67.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601217.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601217-CARONI-2000-Heavy-Trinidad-Rum-Paradise-#5.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Papa Rouyo 2022', 'https://www.juuls.dk/rom/varekort/habitation-velier-papa-rouyo-2022', 1129, TRUE, 70, 56.7, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643678.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643678-Habitation-Velier-Papa-Rouyo-2022.jpg', 'Papa Rouyo ligger på Guadeloupe og laver klassisk rhum agricole på håndhøstede sukkerrør af typerne Canne Jaune, Canne Rouge og Canne Matos – denne rom er lavet på ren Canne Rouge. Luca Gargano og Velier har valgt et særlig godt fad til deres serie Habitation Velier : en 1 år gammel rom destilleret i 2022 og lagret på et ex-cognacfad, tappet ved 56,7%. Et drøn af en rom fra et af de destillerier, vi helt klart skal holde øje med i fremtiden. Farve : Let gylden. Duft : Florale noter af kaprifolie, frisk ingefær, sukkerrørssagt og muskatnød. Smagsnoter : Skarptskåret og intens rom med noter af vaniljestænger, yoghurt og toffee. Lang, tør finish.  Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Blanc Canne Bleue 2023', 'https://www.juuls.dk/rom/varekort/clement-rhum-blanc-canne-bleue-2023', 479, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50610222.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50610222-Clement-Rhum-Blanc-Canne-Bleue-2023.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin SonSon Haiti', 'https://www.juuls.dk/rom/varekort/clairin-sonson-haiti-3', 529, TRUE, 70, 51, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625340.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625340-Clairin-SonSon-Haiti.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('HAMPDEN Coffret 8 Marks Collection 1 year', 'https://www.juuls.dk/rom/varekort/hampden-coffret-8-marks-collection-1-year', 2079, TRUE, 20, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643802.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643802-HAMPDEN-Coffret-8-Marks-Collection-1-year.jpg', 'Da Hampden Estate lancerede den første 8 Marks Collection, var der stor jubel blandt romnørderne. Her var endelig muligheden for at sammenligne alle ”opskrifterne” fra Hampden Estate! Siden har mange efterspurgt det samme sæt i en lagret udgave, og det er nu udkommet. Princippet er det samme: den flotte æske indeholder 8 x 20 cl rom, og starter med Hampdens ”letteste” destillat, bevæger sig op gennem rækkerne og slutter med en heftig DOK, der virkelig giver hård på brystet. Alle rommene er lagret 1 år på ex-bourbonfade – selvfølgelig tropisk lagring ved destilleriet – og tappet ved 52% alkohol. Sættet indeholder også masser af information om produktionen og Hampden generelt. Farve : Let gylden. Duft : Fra det behageligt frugtige og krydrede til det voldsomt funky. Smagsnoter : Tør, kraftig rom hele vejen igennem med fuld Jamaica-power ! Serveringsforslag : Nyd dem rent og hold din egen komparative smagning – og brug resterne i de vildeste mai tais!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Carupano XO', 'https://www.juuls.dk/rom/varekort/carupano-xo', 3559, TRUE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643337.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643337-Carupano-XO.jpg', 'Carúpano XO er en del af Carúpanos Prestige Collection. Rommen stammer fra de ældgamle ”familie-reserver” og tappes i et begrænset antal: blot 2.000 flasker om året, og så endda i en flot karaffel med tilhørende æske. En raffineret og luksuriøs rom. Farve : Mørkt rav med kobberskær. Duft : Noter af karamel, brioche, valnødder og gamle cigaræsker. Smagsnoter :  Fyldig og fedmefuld med mange af de samme noter fra duften og en eftersmag af kaffe og kokosnød. Serveringsforslag :  Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Diplomatico Planas', 'https://www.juuls.dk/rom/varekort/diplomatico-planas', 279, TRUE, 70, 47, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643340.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643340-Diplomatico-Planas.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Master Blender''s Reserve 2024', 'https://www.juuls.dk/rom/varekort/black-tot-master-blenders-reserve-2024', 1659, TRUE, 70, 54.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642324.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642324-Black-Tot-Master-Blender''s-Reserve-2024.jpg', 'Hvert år laver Master Blender Oliver Chilton en ny udgave af Black Tot Master Blender’s Reserve, og i 2024-udgave er der fokus på den frugtige side af navy-rommen: Barbados! Komponenterne fra Barbados udgør i år hele 60% af rommen, og deriblandt finder man en 22 år gammel rom fra Mount Gay! Desuden er der en god del Trinidad, lidt Jamaica og lidt Guyana . Af highlights kan nævnes en 26 år gammel Caroni, en 25 år gammel Clarendon og en knivspids 28 år gammel New Yarmouth! Wowza! Som traditionen foreskriver, er der også lidt af sidste års Master Blender’s Reserve i (knap 4%) samt lidt af den originale Navy-rom.  Rommen er ikke tilsat sukker og ikke kølefiltreret – og så er den tappet ved dejlige 54,5%. Farve : Mørkt rav. Duft : En duft med fuld knald på det tropiske: grillet ananas, mynte, jordbær, lime, chili og kokosnød. Smagsnoter : Fyldig, smørfed rom, der langsomt dækker tungen med noter af manukahonning, banan, vaniljestænger og mango. I eftersmagen er der lakrids og mørk chokolade. Serveringsforslag : Nydes nok bedst rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Jamaica Vintage 2017 Willett Cask Juuls', 'https://www.juuls.dk/rom/varekort/planteray-jamaica-vintage-2017-willett-cask-juuls', 739, TRUE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404834.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404834-Planteray-Jamaica-Vintage-2017-Willett-Cask-Juuls.jpg', '', '2026-11-08 09:30:00+01');
