INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Paranubes Cana Criolla', 'https://www.juuls.dk/rom/varekort/paranubes-cana-criolla', 459, TRUE, 70, 54.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625268.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625268-Paranubes-Cana-Criolla.jpg', 'Jose Luis Carrera dyrker 4 sorter af sukkerrør på sin plantage i Sierra Mazateca i Oaxaca. Af de 4 udgør caña criolla størstedelen af blendet i den nu legendariske rom, Paranubes. Men den er ikke blevet tappet som ”single cane”-rom før nu! Så her får du 100% caña criolla, presset og gæret naturligt over 24 timer før destillationen. Den er tappet ved 54,6% alkohol – uden tilsat vand. Farve : Klar. Duft : Grøn banan, overmoden tropisk frugt og så Paranubes’ karakteristiske maritime præg. Smagsnoter : Fyldig, ”savory” rom med grønne græsser, salt og syrlighed. Serveringsforslag : Nyd den rent eller i cocktails. Daiquiris er oplagt!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Great House Distillery Edition 2024', 'https://www.juuls.dk/rom/varekort/hampden-great-house-distillery-edition-2024', 1139, TRUE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643808.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643808-Hampden-Great-House-Distillery-Edition-2024.jpg', 'Max 1 fl. per kunde Dette produkt er ekskluderet fra alle rabatkoder Hampden Estate Great House er en rom fra et af Caribiens vigtigste og ældste destillerier. Hos Hampden produceres rom, som ikke har sin lige noget andet sted i verden! Enormt kraftig, intens og frugtig, med den blandt romnørder så populære funky karakter. Denne særlige udgave er en officiel aftapning fra destilleriet, distribueret af La Maison du Whisky og Velier , som frigives én gang om året: 2024 er den sjette udgave. Den er lagret på bourbonfade og tappet ved 57% alkohol. Farve : Gylden. Duft : Intens og livlig duft af mint, moden mango, kvæde og mørk chokolade. Smagsnoter : Masser af tropisk frugt (passionsfrugt, mango, friske mintnoter, tobak og peber. Lang eftersmag. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
