INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna BiB 3L Mafate', 'https://www.juuls.dk/rom/varekort/savanna-bib-3l-mafate', 969, TRUE, 300, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615419.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615419-Savanna-BiB-3L-Mafate.jpg', 'Mafate er en ”rhum traditionnel” fra det gamle destilleri, Savanna, på Reunion. Den er lavet på melasse og tappet uden lagring i en praktisk 3-liters bag-in-box, så du kan lave alle de cocktails, dit tørstige hjerte begærer! Farve : Klar. Duft : Tropefrugt og milde krydderier. Smagsnoter : Klassisk Savanna-intensitet, med masser af friskhed, frugtighed og en lang eftersmag. Serveringsforslag : Til cocktails, punches og rhum arrangé.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna L''Absolu 2024', 'https://www.juuls.dk/rom/varekort/savanna-labsolu-2024', 2329, TRUE, 70, 58, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615495.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615495-Savanna-L''Absolu-2024.jpg', 'Savanna L’Absolu er hvad der sker, når Savannas masterblender, Thierry Grondin, får frie hænder til at vælge præcis de fade, han bedst kan li’; hvor ingenting er off limits, end ikke lagerets juveler. Dette er 2024-aftapningen af mesterstykket: et blend af 3 rhum traditionnel lagret på cognacfade og 2 fra moscatelfade. En HERR-komponent fra cognacfad fuldender blendet. L’Absolu 2024 er tappet ved 58% alkohol. Rom i absolut topklasse fra Reunion ! Farve : Rav. Duft : Mørk, dyb og kompleks duft af brændte figner, balsamico, karamel og overmoden tropefrugt. Smagsnoter : Olieret, fyldig mundfølelse. Mørke chokoladenoter ledsages af krydderier som muskatnød og peber. Eftersmagen er imponerende lang. En rom man sent glemmer! Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Nine Leaves 4 Casks Ex-Russian Oak', 'https://www.juuls.dk/rom/varekort/nine-leaves-4-casks-ex-russian-oak', 1659, TRUE, 70, 58, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646673-Nine-Leaves-4-Casks-Ex-Russian-Oak.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM Blanc Agricole BiB 3L', 'https://www.juuls.dk/rom/varekort/rhum-jm-blanc-agricole-bib-3l', 1009, TRUE, 300, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614001.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614001-Rhum-JM-Blanc-Agricole-BiB-3L.jpg', 'Hele 3 praktiske liter af Rhum JM Blanc: en klassisk, ulagret rhum agricole med flotte og intense noter af moden, tropisk frugt (ananas, mango og banan) og lette, grønne græsnoter. Aftapningsprocenten på 50 klæder virkelig rommen. Den ekstra power mærkes både i aromaen og smagen, og så sikrer den, at der ingen risiko er for at rommen bliver væk i din mai tai! Farve : Klar. Duft : Skønne sukkerrørsnoter; græs og olivenolie, flankeret af moden ananas og mango. Smagsnoter : Sødmefuld og vældig frugtig. Dertil et salt touch samt en smule våd jord. Serveringsforslag : En oplagt rom til ti’punch eller mai tais!', '2026-11-08 09:30:00+01');
