INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Black Tot Master Blender''s Reserve 2025', 'https://www.juuls.dk/rom/varekort/black-tot-master-blenders-reserve-2025', 1659, TRUE, 70, 54.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642325.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642325-Black-Tot-Master-Blender''s-Reserve-2025.jpg', 'Alle mand på dæk! Der er rom i sigte! Black Tot Master Blender’s Reserve 2025 er lige dukket op over horisonten, og det er lidt af en skønhed i år. Som du måske ved, bliver der hvert år frigivet et nyt ”blend” i serien, og denne gang har Oliver Chillton, den bemeldte Master Blender, overgået sig selv! Sammensætningen lyder på 40% guyanarom (op til 21 år gammel), 24% barbadosrom, 13% Jamaica, 4% Trinidad og så 19% af Black Tots ”perpetual reserve”, som blandt andet indeholder rom fra de originale britiske flåderationer. De 4% fra Trinidad lyder måske ikke af meget, men de sætter sit tydelige præg – Black Tot afslører også, at der er tale om et ”sjældent fad fra et lukket destilleri”. De fleste romnørder ved nok godt, hvad det betyder… Jep, det er Caroni! Som sædvanligt er der hverken sukker eller farve tilsat, og alkoholprocenten ligger på potente 54,5. Farve : Mørkt rav. Duft : En kaleidoskopisk duft hvor lakrids og mørk chokolade smelter sammen med melasse, tropisk frugt og grapefrugt. Smagsnoter : Tæt og intens rom, med mørke noter af varme krydderier og melasse, smeltet smør og kandiseret citrus. Serveringsforslag : Nyd den rent, evt. med et par dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Renegade White Old Bacolet', 'https://www.juuls.dk/rom/varekort/habitation-velier-renegade-white-old-bacolet', 779, TRUE, 70, 55, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646703.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646703-Habitation-Velier-Renegade-White-Old-Bacolet.jpg', '', '2026-11-08 09:30:00+01');
