INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna L''Absolu 2025 Extra old rum 58%', 'https://www.juuls.dk/rom/varekort/savanna-labsolu-2025-extra-old-rum-58', 2329, TRUE, 70, 58, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615498.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615498-Savanna-L''Absolu-2025-Extra-old-rum-58%.jpg', 'Savanna L’Absolu er hvad der sker, når Savannas masterblender, Thierry Grondin, får frie hænder til at vælge præcis de fade, han bedst kan li’; hvor ingenting er off limits, end ikke lagerets juveler. Dette er 2025-aftapningen af mesterstykket: en blanding af op til 15 år gamle rhum traditionnels fra cognacfade, en 10 år gammel rhum agricole og en 11 år gammel grand arôme . Farve : Rav. Duft : Intens og aromatisk rom med grønne, krydrede noter, tropefrugt og peber og kandiseret citrus. Smagsnoter : En ambitiøs rom, der rammer hele sanseorganet med pondus. Masser af ristede nødder, varme krydderier, tobak og tørret frugt. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Lontan Straight Limited Edition 2024', 'https://www.juuls.dk/rom/varekort/savanna-lontan-straight-limited-edition-2024', 569, TRUE, 70, 74.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615499-Savanna-Lontan-Straight-Limited-Edition-2024.jpg', 'Hvis man kan sit creole , kan man næsten gætte, at Lontan betyder ”long time”. Det refererer i dette tilfælde til gæringen, som virkelig er lang på rommen her! Faktisk hele 8 dage. En lang gæring giver masser af smag, og har man først én gang smagt en rom af denne type fra Savanna, så glemmer man det næppe. Rommen er lavet på melasse fra Bois Rouge-sukkerrør. Efter gæringen er den destilleret på en kolonnekedel og tappet ved decideret ubarmhjertige 74,9% alkohol. Esterindholdet ligger på 784,5 gram per hL/AA. Der er produceret 5800 flasker. Farve : Klar. Duft : Jamen den dufter jo, som kun Grand Arôme fra Savanna dufter! Det er en blanding af ananas, varm plastic, mere ananas (også ananas-is – lidt ala Københavnerstang), sorte oliven, banan – den slags! Smagsnoter : Ufatteligt koncentreret. Et powerhouse af en rom, og ikke for sarte sjæle. Fuld knald på tropisk frugt. Den er funky på sin helt egen måde – et unikum i romverdenen! Serveringsforslag : Enhver romnørd skal prøve den her! Man kan også bruge den som ”koncentrat” i sine cocktails. Lav fx en Daiquiri på en billigere og mindre karakterfuld rom, men tilsæt 0,5 – 1 cl af Savannas Grande Arôme. Vi lover, det gør en markant forskel!', '2026-11-08 09:30:00+01');
