INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Mother Mesccia Pure Single Rum', 'https://www.juuls.dk/rom/varekort/mother-mesccia-pure-single-rum', 729, TRUE, 70, 47, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643822.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643822-Mother-Mesccia-Pure-Single-Rum.jpg', 'Mother Mesccia er en hvid rom lavet på frisk sukkerrørssaft, destilleret først én gang i Haiti og så én gang i Monaco. Idéen er baseret på en gammel tradition fra Monaco hvor søfartsfolk tog rom med hjem fra Caribien, som blev blandet med hedvinen marsala og vermouth og solgt som ”mesccia”, der betyder ”blanding”. Velier mente dog, at en moderne Mesccia ville blive bedre, hvis man i stedet for at blande rommen med hedvin lagrede den på marsala- og vermouthfade. Den friske saft fra sukkerrørene vildgærer og destilleres i Port-Au-Prince, Haiti, før den skibes til Monaco og destilleres én gang til på Destillerie de Monaco. Dette er Mother Mesccia – moderen – det vil sige den hvide rom, som endnu ikke er lagret. Farve : Klar. Duft : Frugtig og super floral duft af mirabelle, geranium og frisk sukkerrørssaft. Smagsnoter : Delikat smag med mandelnoter, citrus, pære, ingefær og mirabelle. Serveringsforslag : Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
