INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clairin SonSon Haiti', 'https://www.juuls.dk/rom/varekort/clairin-sonson-haiti-4', 529, TRUE, 70, 49.4, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625342.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625342-Clairin-SonSon-Haiti.jpg', 'Clairin SonSon fra Haiti er lavet af sukkerrørsjuice fra sukkerrørsarten ”Madame Meuze”, høstet i 2020. Sukkerrørene dækker et område på ca 25 hektar, hvor de vokser sammen med banantræer og andre frugttræer. Sukkerrørsjuicen koncentreres til sirup, hvorefter den spontant gærer med vildgær. Den destilleres af Stephan Kalil Saoud i en creolsk kobberkedel, som opvarmes af åben ild. Farve : Klar. Duft : Citrus og græs. Smagsnoter : Noter af appelsinskal, modne citroner, grønt græs og hvid peber. Serveringsforslag : Prøv den rent – og prøv derefter en centiliter eller to i din daiquiri eller mai tai.', '2026-11-08 09:30:00+01');
