INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Guyana 2004 Small Batch Velier', 'https://www.juuls.dk/rom/varekort/guyana-2004-small-batch-velier-1', 3785, TRUE, 70, 50, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643663.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643663-Guyana-2004-Small-Batch-Velier.jpg', 'Dette produkt er ekskluderet fra alle rabatkoder. Max 1 fl. per kunde. Der findes næppe mere sagnomspunden rom, end de gamle Guyana-aftapninger fra Velier, som blev frigivet med jævne mellemrum fra 2005. Der har dog været decideret tørke på Guyana-fronten fra Velier i en længere periode, så stemningen var nærmest euforisk blandt romsamlere da Velier endnu engang frigav en tropisk lagret Guyana-rom i starten af 2026, og nu er den danske allokation landet! Rommen er en blanding af 3 forskellige rom (derfor navnet Small Batch), hvoraf den yngste bestanddel er fra 2004. Der er frigivet 2.907 flasker på verdensplan. Farve : Rav. Duft : Super-rig duft der minder om moden abrikos, tarte tatin, sveske og marmelade. Smagsnoter : Fyldig og intens rom, med noter af mango, brændt banan, rum baba, rosiner, mørk chokolade og et strejf af iod. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('VIEUX VAVAL 10 ans 2016', 'https://www.juuls.dk/rom/varekort/vieux-vaval-10-ans-2016', 1849, TRUE, 70, 54.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50625344.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625344-VIEUX-VAVAL-10-ans-2016.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Magnifica Cristal Cachaca BiB ', 'https://www.juuls.dk/rom/varekort/magnifica-cristal-cachaca-bib', 1549, TRUE, 500, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646838.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646838-Magnifica-Cristal-Cachaca-BiB.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Damoiseau Rhum Vieux 10 ans', 'https://www.juuls.dk/rom/varekort/damoiseau-rhum-vieux-10-ans', 789, FALSE, 70, 42, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50616440.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50616440-Damoiseau-Rhum-Vieux-10-ans.jpg', 'Damoiseau Rhum Vieux 10 ans er en agricole-rom fra Bellevue-destilleriet på Guadeloupe. Rommen ligger 10 år på tønder konstrueret af træsorten Quercus alba før den tappes. Disse fade har et naturligt højt indhold af vanillin, og rommen får derfra diskrete krydrede og vaniljeagtige noter, flot afstemt af tropisk frugt og en robust agricole-rygrad. Farve: Dyb gylden. Duft: Forholdsvis let og elegant i duften med ananas, vaniljeis og solbærmarmelade. Smagsnoter: Sød lakrids, bananer og orangeblomstvand. Serveringsforslag: Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Myers''s Planters Punch', 'https://www.juuls.dk/rom/varekort/myerss-planters-punch', 189, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643300.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643300-Myers''s-Planters-Punch.jpg', 'Myers''s Planters Punch er en rom fra Jamaica. Den er lavet på sukkerrørsmelasse. Rommen er tappet ved 40%. Myers''s Planters Punch har en god fylde, og masser af kompleksitet i smagen, hvor man blandt andet finder nuancer af tørret frugt, karamel og vanilje. Kan nydes både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Trinidad Vintage 2003', 'https://www.juuls.dk/rom/varekort/planteray-trinidad-vintage-2003', 739, FALSE, 70, 47.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641199.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641199-Planteray-Trinidad-Vintage-2003.jpg', 'Planteray Trinidad 2003 er den sidste flaske i Terraverra-serien: en perlerække af limited edition rom fra forskellige destillerier i Caribien. Nu når Terraverra sit klimaks med den ældste aftapning i serien. Hele 22 år gammel er rommen, og heraf intet mindre end 19 år i troperne. De sidste 3 år har rommen, som det er kutyme hos Planteray, ligget på Ferrand-fade i Cognac, Frankrig. Den er tappet uden tilsat sukker, uden tilsat farvestof og ved skønne 47,8% alkohol. En drøm af en rom og en værdig afslutning på en episk serie. Farve : Rav. Duft : Fasscinerende blanding af frugtige, krydrede og let ”funky” noter, med både fersken, guave, figen og peberkorn. Smagsnoter : Fyldig og olieret rom, der viser masser af kokos, ristet eg, varme krydderier og dadler. Lang eftersmag med tobak, kakao og pære. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Den Gamle Ørn - Extra fin og Gammel', 'https://www.juuls.dk/rom/varekort/den-gamle-oern-extra-fin-og-gammel', 305, FALSE, 70, 60, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642110.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642110-Den-Gamle-Ørn---Extra-fin-og-Gammel.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Appleton Estate Signature Blend', 'https://www.juuls.dk/rom/varekort/appleton-estate-signature-blend', 259, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644350.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644350-Appleton-Estate-Signature-Blend.jpg', 'Appleton Estate Signature Blend er en lagret rom fra Jamaica. Dette er den kvintessentielle Appleton – destilleriets ”signatur”, som navnet fortæller. Det er et blend af rom af flere typer (15 forskellige) og varierende lagringstid. Alderen ligger i gennemsnit på 4 år – men den opgives ikke på flasken, og skal i stedet opspores på Appletons hjemmeside. Farve:  Let rav. Duft:  Stenfrugt som fersken og tørret abrikos, let citrus og hints af vanilje og melasse. Smagsnoter:  Flot naturlig sødme, tropisk frugt og varme krydderier. Mellemlang eftersmag. Serveringsforslag:  Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Legendario Elixir de Cuba', 'https://www.juuls.dk/rom/varekort/legendario-elixir-de-cuba', 289, FALSE, 70, 34, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643910.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643910-Legendario-Elixir-de-Cuba.jpg', 'Legendario Elixir de Cuba er en likør baseret på klassisk, cubansk rom. Rommen er gæret på melasse, destilleret på kolonnekedler og lagret i op til 7 år. Her kommer så den finurlighed, som gør det til en ”Elixir”, og ikke en rom:  i rommen udblødes rosiner, den smages til med sukkersirup og vandes ned til 34%. Resultatet er en uendeligt blød, sødmefuld og fantastisk lækker romlikør! Farve: Mahogni. Duft: Skøn duft af tørret frugt, især rosiner og svesker samt hints af vanilje og karamel. Smagsnoter: Blød, rund og sødmefuld. Fudge, vanilje og rosinnoter, samt en lang, behagelig eftersmag. Serveringsforslag: Kan nydes rent, over is eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier FOURSQUARE Supernum', 'https://www.juuls.dk/rom/varekort/velier-foursquare-supernum', 2339, FALSE, 70, 55, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601094.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601094-Velier-FOURSQUARE-Supernum.jpg', 'Nu kommer den hidtil ældste udgivelse i det meget succesfulde samarbejde mellem Foursquare og Velier. Supernum er den 12. rom i rækken, og den er blendet af to forskellige rom: den ene lagret udelukkende på bourbonfade og den anden ”double matured” på først boubonfade og så pineau de charentes-fade. Vi snakker altså hele 21 års tropisk lagring, en potent alkoholstyrke (55%) og – som altid – meget begrænsede mængder. I år desværre endnu mere begrænsede end normalt… Max 1 flaske per kunde. Dette produkt er ekskluderet fra alle rabatkoder. Farve : Rav. Duft : En dyb og kompleks duft af kandiseret frugt, blomme og abrikos, med søde krydderier og vanilje i baggrunden. Smagsnoter : Fyldig og lang i smagen, med noter af karamel, mørk chokolade, tørret frugt og valnød. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Come Hell or High Water XO Mini', 'https://www.juuls.dk/rom/varekort/come-hell-or-high-water-xo-mini', 59, FALSE, 5, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643492.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643492-Come-Hell-or-High-Water-XO-Mini.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Black Cask 2023 Barbados & Venezuela', 'https://www.juuls.dk/rom/varekort/plantation-black-cask-2023-barbados-venezuela', 379, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641026.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641026-Plantation-Black-Cask-2023-Barbados-&-Venezuela.jpg', 'Black Cask er blandt Plantations mest ikoniske udgivelser og med 2023-udgaven har Alexandre Gabriel og co. virkelig ramt plet! Rommen består denne gang af en blanding af Barbados og Venezuela, lagret både tropisk og ”kontinentalt” – dvs. hos Ferrand i Frankrig på deres egne, franske fade. Der er tilsat 20 gram sukker per liter, så rommen er sød, blød og rund i bedste Black Cask-stil, uden at kamme over. En crowd pleaser af forbløffende høj kvalitet! Farve : Dyb ravgylden. Duft : Det er virkelig en fornøjelse at stikke næsen ned i et glas som dette. Fyldt med honning, stegte bananer, toffee, kaffe og vanilje. Smagsnoter : Fløjlsblød og sødmefuld på tungen, med de samme noter som duften suppleret at karamel og varme krydderier. Serveringsforslag : Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI West Indies Blend 8 Years Old', 'https://www.juuls.dk/rom/varekort/cdi-west-indies-blend-8-years-old', 519, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640631.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640631-CDI-West-Indies-Blend-8-Years-Old.jpg', 'Compagnie des Indes West Indies er et blend af rom fra Barbados, Panama, Den Dominikanske Republik og Guyana. Rommen er lagret i minimum 8 år på bourbonfade og er hverken tilsat sukker, aromaer, farve eller kølefiltreret. Et elegant romblend som får fylde og styrke fra den pot still-destillerede Barbados-komponent. Farve: Rav. Duft: Kandissukker, honning, fersken og krydderier.  Smagsnoter: Spicy egetræ, melasse, rabarber, vanilje og lakrids.  Serveringsforslag: Kan nydes rent eller i cocktails', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Bumbu XO Rum', 'https://www.juuls.dk/rom/varekort/bumbu-xo-rum', 359, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50620520.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50620520-Bumbu-XO-Rum.jpg', 'Bumbu XO Rum er en blød, fyldig og kompleks rom, som er destilleret og lagret i Panama. Som navnet antyder, er der gjort noget særligt ud af lagringen: efter en periode på bourbonfade flyttes Bumbu XO til sherryfade , hvorfra den får noter af tørret frugt og varme krydderier, der smukt komplimenterer den sødmefulde smagsprofil. Farve : Rav. Duft : Toffee, ristet eg og vanilje. Smagsnoter : Sødme, appelsinskal, pebret krydderi og et strejf af kaffe. Serveringsforslag : Nyd den rent, som du ville nyde en likør efter maden, eller prøv den i cocktails!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Clement Rhum Single Cask Danemark 15 Ans', 'https://www.juuls.dk/rom/varekort/clement-rhum-single-cask-danemark-15-ans', 1099, FALSE, 50, 56.58, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50611833.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50611833-Clement-Rhum-Single-Cask-Danemark-15-Ans.jpg', 'Clément Single Cask Danemark er en 15 år gammel rom, tappet fra ét enkelt bourbonfad og kun frigivet i Danmark. Rommen er lavet på frisk sukkerrørssaft og tappet ved hele 56,6% alkohol – en for agricole-rom usædvanlig men absolut kærkommen feature! De ekstra procenter giver dybde og power i både smag og duft så lad os håbe på mange flere aftapninger uden ”nedvanding” i fremtiden! Farve: Mørk rav Duft: En regulær frugtsalat i duften med pære, fersken, ananas og revet chokolade! Smagsnoter: Stor og eksplosiv. Noter af kardemomme, karamelliseret sukker, koriander og kaffe. Wauw! Serveringsforslag: Bør drikkes rent, evt. med få dråber vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna Traditionnel 10', 'https://www.juuls.dk/rom/varekort/savanna-traditionnel-10', 739, FALSE, 70, 43, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615439.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615439-Savanna-Traditionnel-10.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Grogue White Rum', 'https://www.juuls.dk/rom/varekort/grogue-white-rum', 549, FALSE, 70, 45, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50630000.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50630000-Grogue-White-Rum.jpg', 'På Cap Verde laver man rom, der i stilen minder om rhum agricole eller andre cane juice-baserede typer fra Haiti eller Mexico. Det er ganske lidt, vi har set der fra i Europa indtil nu, og selvfølgelig er det Velier der har givet os dette skønne eksemplar på den gode grogue fra Barbosa Amado & Vicente. En lang, naturlig gæring og destillation på små kobber alambics giver en utroligt karakterfuld rom med saft, kraft og sukkerrør! Farve: Klar. Duft: Tydelig duft af sukkerrørssaft, frugtige noter af tomat, mango og så et hint af basilikum. Smagsnoter: Smagen har god intensitet, men er flot balanceret mellem overmoden frugt og vegetabilske noter af urter og græs. Serveringsforslag: Nyd den rent eller i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Panama DK  13 years PS99', 'https://www.juuls.dk/rom/varekort/cdi-panama-dk-13-years-ps99', 889, FALSE, 70, 56.9, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640899.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640899-CDI-Panama-DK--13-years-PS99.jpg', 'Compagnie des Indes Panama 13 Years #PS99 er en single cask-rom fra et destilleri i Panama. Den er tappet udelukkende til det danske marked, og er lagret 13 lange år på nye fade af amerikansk egetræ. Rommen er flasket ved fadstyrke, 56,9%, men er rund og charmerende – Compagnie des Indes anbefaler selv rom a la denne panamaner som en god introduktion til fadstyrke-rom for de uindviede. Farve: Rav. Duft: Kanel, mirabeller og abrikos. Smagsnoter: Blød og rund på trods af styrken, med shortbread, vanilje og modne, røde æbler. Serveringsforslag: Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Ping X Trinidad 26 years', 'https://www.juuls.dk/rom/varekort/plantation-ping-x-trinidad-26-years', 19329, NULL, 70, 53, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641282.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641282-Plantation-Ping-X-Trinidad-26-years.jpg', 'Ping X Trinidad 26 Years er sandsynligvis én af de mest eftertragtede rom fra Plantation. Og med god grund! Det er nemlig det legendariske destilleri, Caroni, som har leveret rommen i flasken. Caroni er nu lukket, og chancerne for at smage rom fra deres famøse kedler bliver færre og færre. Men Plantation Ping X er også en atypisk Caroni, idet de typiske noter af diesel, tjære og nylagt asfalt bøjer sig for en delikat karamelsødme. Ping X er frigivet i forbindelse med ejeren af Juuls Vin og Spiritus, Michael Madsens, 40-års jubilæum i branchen. Rommen er tappet i en flot karaffelflaske og leveres i en prægtig, lakeret trækasse. Farve: Mørk mahogni Duft: Meget fyldig og intens duft med ahornsirup og ristede kastanjer, sandeltræ, læder, sød lakrids og appelsin med nelliker. Smagsnoter: Tung og opulent. Et overflødighedshorn af flødekaramel, kaffe og toppen af drømmekagen. Serveringsforslag: Bør drikkes rent', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Old Jamaica Vintage Rum 26 years', 'https://www.juuls.dk/rom/varekort/old-jamaica-vintage-rum-26-years', 7739, NULL, 70, 48, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642000.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642000-Old-Jamaica-Vintage-Rum-26-years.jpg', 'Old Jamaica Vintage 1982 26 Years Old er en rom fra Jamaica tappet af den uafhængige aftapper, Ian MacLeod Distillers. Selvom Ian MacLeod primært er kendt for deres virke i whisky-branchen, har de formået at levere adskillige homeruns på romfronten. Denne gamle jamaicaner er et strålende eksempel. Ved aftapningen i 2008 kunne kun 1152 flasker trækkes fra de i alt 4 fade. Rommen er tappet ved 48% alkohol. Farve: Dyb gylden. Duft: Flot og klassisk Jamaica-næse med let overmodne bananer, tobak, lakrids og læder. Smagsnoter: Smagen er relativt elegant – det er ikke nogen ”esterbombe”, men en raffineret, old-school Jamaicaner med charmerende noter af kaffe, engelsk lakrids, egetræ, rosiner og ingefær. Serveringsforslag: Bør nydes rent, evt. med en dråbe vand.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('FLYING no 11 Jamaica rum 30 years', 'https://www.juuls.dk/rom/varekort/flying-no-11-jamaica-rum-30-years', 6189, FALSE, 70, 61.6, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50642005.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50642005-FLYING-no-11-Jamaica-rum-30-years.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Habitation Velier Forsyths WPM 2006', 'https://www.juuls.dk/rom/varekort/habitation-velier-forsyths-wpm-2006-1', 1139, FALSE, 70, 57.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643719.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643719-Habitation-Velier-Forsyths-WPM-2006.jpg', 'Forsyths WPE White er en jamaicansk rom fra destilleriet Worthy Park. Den er tappet under banneret ”Habitation Velier”, som er en serie af udgivelse fra den italienske kultaftapper, hvor romnørder får nysgerrigheden stillet (og lidt til). Rommen indeholder 597,3 gram estere per hektoliter ren alkohol, hvilket lover en funky smagsbombe der vil tiltale hardcore Jamaica-fans. Den er ikke lagret, så det flotte Worthy Park-destillat får lov at spille hovedrollen. Farve: Klar. Duft: Flamberede bananer, brændt toast og cykelslange. Smagsnoter: Sødmefuld og meget koncentreret, med en lang, frugtig eftersmag. Serveringsforslag: Kan nydes rent eller bruges til next-level tiki-cocktails!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CHAMAREL 2017 Habitation Velier', 'https://www.juuls.dk/rom/varekort/chamarel-2017-habitation-velier', 1169, FALSE, 70, 63, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643722.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643722-CHAMAREL-2017-Habitation-Velier.jpg', 'Long Pond STCE White er en Jamaica-rom aftappet i serien Habitation Velier , som udover at levere fantastiske smagsoplevelser også sætter gennemsigtighed i højsædet og tilfredsstiller selv de allermest krævende romnørders nysgerrighed. Fx bekendtgør etiketten ester-indholdet i rommen, hvilket er direkte forbundet til smagen. Her ligger vi på 674 g/hlpa – et svimlende højt niveau, der garanterer en rom med masser af funk. Farve: Klar. Duft: Noter af mentol og kamfer blander sig med krydderier som nellike og vanilje. Bagved ligger frugten og ulmer: ananas, pære og fersken. Smagsnoter: Kraftig smag med masser af kompleksitet. Grapefrugt, fersken, karry, mentol og friske surrerrør. Serveringsforslag: Kan nydes rent eller i cocktails. Lyden af navnet ” Velier ” får en helt særlig følelse frem hos romnørder. Gang på gang formår masterminded bag firmaet, Luca Gargano, at chokere og henrykke romverdenen med udgivelser der sætter nye standarder for kvalitet, gennemsigtighed og nørderi. Veliers ry for exceptionel kvalitet cementeredes allerede i ’00’erne med en perlerække af kompromisløse demerara-rom. Disse flasker er i dag højdemålet af kultrom og skifter ejere for astronomiske summer på spiritusauktioner verden over. Senere er firmaet blevet kendt for tropisk lagret Caroni, en særegen rom fra et nu lukket destilleri på Trinidad, med noter af røg, tjære og bacon. En ”acquired taste”, men når først du har den… Sammen med Foursquares Richard Seale er Luca standhaftig modstander af tilsætningsstoffer eller fusk med aldersbetegnelser og derfor sætter Veliers nyeste serie af rom, Habitacion Velier, gennemsigtigheden i højsædet. På etiketten blotlægges stolt enhver detalje om produktionen, lige fra ”angel’s share” til ester-indhold.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Mulata 5y Anejo Reserve', 'https://www.juuls.dk/rom/varekort/ron-mulata-5y-anejo-reserve', 209, FALSE, 70, 38, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644010.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644010-Ron-Mulata-5y-Anejo-Reserve.jpg', 'Ron Mulata 5y Anejo Reserve er en rom fra Cuba. Den er lavet på melasse. Rommen er tappet ved 38%. I smagen fornemmes både vanilje, egetræ og varme krydderier. Der er en fin fylde og en behagelig, lang eftersmag. God at nyde både rent eller i cocktails . Flasken indeholder 70 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Pusser''s Blue Label British Navy Rum', 'https://www.juuls.dk/rom/varekort/pussers-blue-label-british-navy-rum', 269, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644500.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644500-Pusser''s-Blue-Label-British-Navy-Rum.jpg', 'Pusser’s Blue Label, også kendt som Original Admiralty Rum, er en rom i navy-stil, inspireret af flådens oprindelige blend-opskrift, som var i brug helt op til traditionen med den daglige ”tot” blev afskaffet den 31. juli 1970. Rommen er blendet af destillater fra flere steder i Caribien, og resultatet er fyldigt, mørkt og krydret. Farve : Rav. Duft : Krydret duft af ingefær, melasse og demerarasukker, banan og egetræ. Smagsnoter : Rosiner, peanuts, tørret frugt, brun farin og brændt karamel. Serveringsforslag : Kan nydes rent eller i cocktails. At sige, at Pusser’s Rum er et historisk vigtigt rombrand er måske lidt af en underdrivelse. Det er ingen hemmelighed, at rom har spillet en yderst central rolle i den britiske flådes dagligdag. Den daglige ”tot” udskænkedes af skibets ”purser”, som også stod for at håndtere skibets pengebeholdning. Det var, selvsagt, et vigtigt erhverv, som kun betroedes mænd af en vis karakterstyrke. Navnet ”Pusser’s” kommer fra purser, og i 1979 – ni år efter den daglige romudskænkning ophørte – erhvervede Pusser’s eneretten til den oprindelige opskrift på den ægte Navy Rum. Som tak går en procentdel af salget til at støtte The Royal Naval Sailor’s Fund. For denne filantropiske dåd er grundlæggeren, Charles Tobias, blevet tildelt Den Ypperligste Orden af det Britiske Imperium. Og rommen er god!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Teeda 5 years Rum Okinawa', 'https://www.juuls.dk/rom/varekort/teeda-5-years-rum-okinawa', 729, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646750.JPG&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646750-Teeda-5-years-Rum-Okinawa.jpg', 'Teeda 5 Years Old er en rom fra Okinawa lavet på lokal sukkerrrørsmelasse, langtidsgæret og destilleret på pot stills. Lagringen foregår på egetræsfade, som enten er helt nye eller har indeholdt  awamori.  Egetræet er amerikansk, men fadene bygges af en bødker i Japan. Det endelige blend indeholder rom i flere aldre: den yngste bestanddel er 5 år, mens den ældste er hele 15 år gammel. Vi er store fans af, at Teeda opgiver den yngste bestanddel af rommen, ikke den ældste! Farve:  Gylden. Duft:  Rosin, kanel og brændt karamel. Smagsnoter:  En hint af ahornsirup, uden overdrevet sødme (her er ingen tilsat sukker), vanilje og rosinnoter. Serveringsforslag:  Denne rom anbefaler vi at nyde rent!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('HAMPDEN 2 ans 2024 DOK Cognac Cask - Mangrove buckeye', 'https://www.juuls.dk/rom/varekort/hampden-2-ans-2024-dok-cognac-cask-mangrove-buckeye', 889, FALSE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643778.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643778-HAMPDEN-2-ans-2024-DOK-Cognac-Cask---Mangrove-buckeye.jpg', 'Max 1 flaske per kunde. Dette produkt er ekskluderet alle rabatkoder. Hampden Estate Great House er en rom fra et af Caribiens vigtigste og ældste destillerier. Hos Hampden produceres rom, som ikke har sin lige noget andet sted i verden! Enormt kraftig, intens og frugtig, med den blandt romnørder så populære funky karakter. Denne særlige udgave er en officiel aftapning fra destilleriet, distribueret af La Maison du Whisky og Velier, og den er fuldt tropisk lagret og tappet ved imponerende 59% alkohol. Til nørderne har vi den vigtige info, at 2020 er en blanding af 20% <>H fra 2017 og 80% OWH fra 2013 – altså en ung, men meget kraftig rom og en ældre, lidt lettere rom. Tilsammen er de uovervindelige! Farve: Klar gylden. Duft: Klare Hampden-noter af tropisk frugt, men også chokolade, lakrids og et strejf af mentol. Smagsnoter: Super-intens. Olieret. Voldsomt stor smag: banan, ananas, medicinske noter, kanel, kakao. Serveringsforslag: Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Guyana 2008 Zebra Cask Denmark 2019', 'https://www.juuls.dk/rom/varekort/plantation-guyana-2008-zebra-cask-denmark-2019', 929, FALSE, 70, 47.1, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404664.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404664-Plantation-Guyana-2008-Zebra-Cask-Denmark-2019.jpg', 'En rom lagret på ”Zebra Cask” – okay, det kræver måske en forklaring. Plantation er kendt for at eksperimentere med fadene, og her har deres bødker begået lidt af en genistreg. Fadene er lavet af både akacietræ og kastanjetræ, og når bødkeren bygger fadene, så sætter han skiftevis en stav fra det ene træ og en stav fra det andet, hvilket giver en flot, næsten zebrastribet overflade. Fadet komplimenterer flot den kraftige Guyana-rom, som har en magisk syrlighed og friskhed, hvilket resulterer i en hel speciel fornemmelse man ikke finder i andre caribiske lande. Rommen er tappet ved 47,1%. Farve : Rav. Duft : Den helt rigtige duft af ægte Guyana-rom med masser af anis, peber, sort te og gammelt træ. Smagsnoter :  Smagen er intens, ja nærmest en lille smule hidsig på den bedste måde. God fedme og masser af kaffe og chokoladenoter i eftersmagen sammen med dejligt prikkende og søde fadtanniner. Serveringsforslag : Nyd den rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Charanda Uruapan Blanco 35%', 'https://www.juuls.dk/rom/varekort/charanda-uruapan-blanco-35', 409, FALSE, 100, 35, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625260-Charanda-Uruapan-Blanco-35%.jpg', 'Charanda Uruapan Blanco 35% er en rom fra Michoacan i Mexico. Den er lavet på sukkerrørssaft. Kan nydes både rent eller i cocktails . Flasken indeholder 100 cl.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate 2010 LROK ', 'https://www.juuls.dk/rom/varekort/hampden-estate-2010-lrok', 1559, NULL, 70, 47, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/95071100.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=95071100-Hampden-Estate-2010-LROK.jpg', 'Max 1 flaske per kunde! Denne aftapning er ekskluderet fra alle rabatkoder Hampden 2010 LROK er en kraftig, tør og funky rom fra Jamaica. Navnet LROK refererer til rommens marque, som er en betegnelse for ester-niveauet i rommen. Hos Hampden laver man mange forskellige marques, og de spænder fra den ”lette” OWH til den potente DOK. LROK, som står for ”Light Rum Owen Kelly”, betegner et indhold på 200-400 gram estere per hektoliter ren alkohol. Denne aftapning rammer 334,7 g/hLPA og er lagret 11 år i Jamaicas tropiske klima før den er tappet ved 47% alkohol. Farve : Gylden. Duft : Frugtig duft af bananchips, kamfer og citrus. Smagsnoter : Den forventelige Hampden-power, masser af tropisk frugt, strejf af vaniljestang og lakrids. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Vale Royal 2006', 'https://www.juuls.dk/rom/varekort/vale-royal-2006', 2899, NULL, 70, 65, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643724.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643724-Vale-Royal-2006.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Admiral Rodney HMS Princessa', 'https://www.juuls.dk/rom/varekort/admiral-rodney-hms-princessa', 529, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615700.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615700-Admiral-Rodney-HMS-Princessa.jpg', 'Princesa var et spansk krigsskib – et linjeskib med 70 kanoner – som den britiske Admiral Rodney overtog ved slaget ved Kap St. Vincent i 1780. Skibet bliv omdøbt HMS Princessa, og deltog under britisk flag ved Battle of the Saints. Rommen, som er opkaldt efter skibet, er et blend af 5-9 år gammel rom fra St. Lucia Distillers, lagret på bourbonfade og portvinsfade.   Farve : Let rødlig gylden. Duft : Dejlig kompleks duft: tobak, vanilje, brun farin og ristet eg. Smagsnoter : Smørkaramel, egetræ og varme krydderier.   Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Admiral Rodney HMS Monarch', 'https://www.juuls.dk/rom/varekort/admiral-rodney-hms-monarch', 579, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615705.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615705-Admiral-Rodney-HMS-Monarch.jpg', '... Admiral Rodney HMS Monarch Rum er et godt, gennemmodnet og vellavet produkt, som byder på pæn dybde og en god kompleksitet. Og hvis man har en sød tand, så vil jeg sige, at det er en af de bedre sødet romaftapninger på markedet. - Romhatten.dk En søstærk rom fra St. Lucia, udviklet og tappet eksklusivt til Danmark! Admiral Rodney HMS Monarch er opkaldt efter skibet af samme navn, som bl.a. deltog i Slaget om Skagerrak. Rommen er lavet på melasse og destilleret på kolonnekedler, hvorefter den er lagret på både bourbonfade og portvinsfade, hvilket giver den fyldige rom masser af rød frugt og et strejf af sødme. Farve : Mahogni. Duft : Noter af rosiner og vanilje og et touch af røde bær. Smag : Blød og sødmefuld med behagelig farin, konfekt og kandiseret frugt inden en lang eftersmag stjæler showet med hint af egetræ og varme krydderier i en balanceret og kompleks oplevelse. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Admiral Rodney HMS Royal Oak', 'https://www.juuls.dk/rom/varekort/admiral-rodney-hms-royal-oak', 679, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615710.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615710-Admiral-Rodney-HMS-Royal-Oak.jpg', 'Admiral Rodney HMS Royal Oak er en rom fra St. Lucia Distillers. Rommen er opkaldt efter skibet HMS Royal Oak, som var ét af de første til at gå i kødet på franskmændene ved Battle of the Saints – og det skal jo hædres! Blandingen består af rom mellem 7 og 12 år, destilleret på en coffey still og lagret udelukkende på bourbonfade.   Farve : Som lyst rav. Duft : Noter af tørret frugt (tænk rosin, sveske), egetræ og tobak. Smagsnoter : I munden er rommen krydret, med noter af blandt andet vanilje, chokolade, karamel og kanel.   Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('HAMPDEN 2 ans 2024 C<>H Cognac Cask - Jamaican calisto', 'https://www.juuls.dk/rom/varekort/hampden-2-ans-2024-ch-cognac-cask-jamaican-calisto', 889, FALSE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643777.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643777-HAMPDEN-2-ans-2024-C<>H-Cognac-Cask---Jamaican-calisto.jpg', 'Max 1 flaske per kunde. Dette produkt er ekskluderet fra rabatkoder.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Neisson Le Rhum Bio Par Neisson ØKO', 'https://www.juuls.dk/rom/varekort/neisson-le-rhum-bio-par-neisson-oeko', 629, FALSE, 70, 52.5, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615165.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615165-Neisson-Le-Rhum-Bio-Par-Neisson-ØKO.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron 1914 Ediciòn Gatún', 'https://www.juuls.dk/rom/varekort/ron-1914-edicion-gatun', 529, FALSE, 70, 41.3, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50632100.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50632100-Ron-1914-Ediciòn-Gatún.jpg', 'Ron 1914 Edición Gatún er en klassisk Panama-rom med både fylde, dybde og sødme. Navnet henviser til det år, Panamakanalen åbnede, og denne særlige udgave er sammensat af flere komponenter med en alder på mellem 15 og 22 år. De er alle lavet på melasse, og 80% er destilleret på kolonnekedel. De sidste 20% kommer fra en kobber-pot still, som giver en lidt tungere rom med en mere kraftig smag, og blandingen af de to typer ender i perfekt balance. Lagringen foregår på brugte bourbonfade hvorfra der kommer noter af karamel og brun farin, vanilje og ristet kokos. Farve : Mørkt rav. Duft : Masser af karamel og tørret frugt, strejf af ingefær, læder og appelsin.  Smagsnoter : Ligger blødt og varmende på tungen med noter af brun farin, kokos og kakao, som fører ind i en krydret finish med hints af ingefær og tobak. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('CDI Leviathan Multi Distilleries 1973+1996 Vintage', 'https://www.juuls.dk/rom/varekort/cdi-leviathan-multi-distilleries-1973-1996-vintage', 3879, FALSE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640931.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640931-CDI-Leviathan-Multi-Distilleries-1973+1996-Vintage.jpg', 'Florent Beuchet har gjort det igen og er kommet på en dristig, premium-aftapning med Compagnie des Indes Leviathan. Dette er en nummereret flaske i et begrænset oplag på 500 eksemplarer verden over. En trækasse ledsager den for at give den al den elegance, den fortjener. Blandingen består af 2 nøje udvalgte fade: 56,1% af dens sammensætning er en landbrugsrom fra Guadeloupe, destilleret i 1973. 43,9% er en melasse rom fra Panama, destilleret i 1996. Kombinationen af disse to exceptionelle rom giver den rigtige balance mellem kompleksitet og sødme. Farve : Gylden. Duft : Aromaer af umodne kirsebær, figner og kaffe. Smag : Først eksplosiv eukalyptus, efterfulgt af ristede aromaer og toner af læder, træ, tobak og krydderier. En ganske syrlig, tør finish med et alkoholisk præg, sammen med bitter appelsinskal, lakrids og mørk chokolade. En oplevelse! Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Barbados Extreme no 5 WIRD Vintage 2000', 'https://www.juuls.dk/rom/varekort/plantation-barbados-extreme-no-5-wird-vintage-2000', 3109, FALSE, 70, 47.8, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404478.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404478-Plantation-Barbados-Extreme-no-5-WIRD-Vintage-2000.jpg', 'OBS. Grundet begrænset lager og stor efterspørgsel bliver bestillinger af Extreme indsamlet via kontaktformular, og der trækkes lod blandt alle henvendelser.  Du skriver dig op ved at udfylde formularen her på siden. Max ét lod per person. Forsøg på snyd medfører ekskludering fra lodtrækningen. De heldige bliver kontaktet på mail mandag d. 4. Juli 2022 Den længe ventede 5. Edition af Plantations Extreme-serie er landet! Destination er denne gang Barbados og Ferrands eget destilleri: West Indies Rum Distillery. De 3 aftapninger er alle udsmykket med den lokale kunstner Alex Mars’ illustrationer af livet på øen. Årgang 2000 er en legendarisk årgang fra lige netop West Indies Rum Distillery, og det er derfor kun passende at den er inkluderet her. Rommen blev på ganske unik vis destilleret på både vulcan chamber still, gregg pot still og en kolonne-still. De første 5 år lagrede den på bourbonfade i tropisk klima, hvorefter rommen blev flyttet til Europa. Her lå den 14 år på bourbonfade og 2 år på Ferrands cognacfade, før den blev tappet ved 47,8% i kun 929 eksemplarer – alle uden tilsat sukker eller farvestof. Farve : Mørkt rav. Duft : Dyb og kompleks duft med noter af honning, citrongræs og oolong-te. Smagsnoter : Tæt og frugtig i munden, hvor man bl.a. finder tropisk frugt (guava), jordbær, grapefrugt og hasselnødder. Serveringsforslag : Bør nydes rent.   Max 1 fl. per kunde Denne aftapning er ekskluderet fra alle rabatkoder', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Plantation Barbados Extreme no 5 WIRD Vintage 2007', 'https://www.juuls.dk/rom/varekort/plantation-barbados-extreme-no-5-wird-vintage-2007', 2079, FALSE, 70, 58, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90404479.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90404479-Plantation-Barbados-Extreme-no-5-WIRD-Vintage-2007.jpg', 'OBS. Grundet begrænset lager og stor efterspørgsel bliver bestillinger af Extreme indsamlet via kontaktformular, og der trækkes lod blandt alle henvendelser.  Du skriver dig op ved at udfylde formularen her på siden. Max ét lod per person. Forsøg på snyd medfører ekskludering fra lodtrækningen. De heldige bliver kontaktet på mail mandag d. 4. Juli 2022 Den længe ventede 5. Edition af Plantations Extreme-serie er landet! Destination er denne gang Barbados og Ferrands eget destilleri: West Indies Rum Distillery. De 3 aftapninger er alle udsmykket med den lokale kunstner Alex Mars’ illustrationer af livet på øen. Dette er den yngste af de tre: en årgang 2007 destilleret på både pot og kolonne-still. Den er lagret 2 år på bourbonfade i troperne, 10 år på bourbonfade i kontinentalt klima og til sidst 2 år på franske cognacfade. Der er tappet i alt 2.857 flasker ved 58% alkohol, og den er hverken tilsat sukker eller karamelfarve. Farve : Dyb ravfarvet. Duft : Fyldig og spicy i duften, med noter af friskrevet muskatnød, kanel, kaffe og flødekaramel. Smagsnoter : De krydrede noter fortsætter med peber, tobak og citronskal. Så melder velkendte Barbados-elementer sig: ristet kokos, vanilje, mandel og flødechokolade. Lang, balanceret eftersmag. Serveringsforslag : Bør nydes rent.   Max 1 fl. per kunde Denne aftapning er ekskluderet fra alle rabatkoder', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rhum JM 2011 Millesime 2022', 'https://www.juuls.dk/rom/varekort/rhum-jm-2011-millesime-2022', 839, FALSE, 70, 41.87, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50614507.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50614507-Rhum-JM-2011-Millesime-2022.jpg', 'Der er altså ingen, der laver rom som Rhum JM. Denne 2011’er er den forventelige, aristokratiske Martinique-stil med elegance, raffinement og friskhed, som JM mestrer bedre end nogen anden. Rommen er tappet brut de fût , på dansk: ved fadstyrke. Det betyder, at selvom alkoholprocenten er ”helt nede” i 42%, så er der ikke tilsat vand. Det er blot den naturlige fordampning i destilleriets kældre for foden af Mont Pelee. Ikke kun en rom for nørder, men en rom som kan skabe nørder! Farve : Dyb gylden. Duft : Stor aromatisk dybde: dadler, figner, muskatnød og ingefær. Smagsnoter : Mellemfyldig smag, til den tørre og krydrede side, med tørret frugt, lys tobak, peber og muskatnød. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Fortin Takuaree ØKO', 'https://www.juuls.dk/rom/varekort/ron-fortin-takuaree-oeko', 429, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643460.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643460-Ron-Fortin-Takuaree-ØKO.jpg', 'Mesterlig hvid rom fra Fortín i Pirebebuy, Paraguay. Lavet på den friske saft af økologisk dyrkede sukkerrør og ganske enkelt eminent i cocktails!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Rum of the World - Belize Juuls Limited Edition', 'https://www.juuls.dk/rom/varekort/rum-of-the-world-belize-juuls-limited-edition', 569, FALSE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50640501.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50640501-Rum-of-the-World---Belize-Juuls-Limited-Edition.jpg', 'Rum of the World - Belize Juuls Limited Edition er en single cask rom fra La maision & Velier som er aftappet eksklusivt til Juul''s Vin & Spiritus. Den er destilleret på Travellers Distillery i 2017. Lagret 4,5 år i tropisk klima og 0,5 år i Europa, og derefter personligt udvalgt af Max Scott, brand manager hos Juul''s Vin & Spiritus.  Aftappet ved 46% alkohol uden tilsat karamelfarve eller sukker, i et meget begrænset oplæg af kun 560 flasker. Farve : Gylden. Duft : Behagelig duft spækket med søde krydderier, nybagte småkager, tropisk frugt og noter af appelsinskal. Smag : En fantastisk, balanceret rom med god, krydret karakter. Noter af melasse, lys karamel og honning. Serveringsforslag : Bør nydes rent. Label design af Marko Colors Geometry.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('National Rums Of Jamaica CAMBRIDGE STCE', 'https://www.juuls.dk/rom/varekort/national-rums-of-jamaica-cambridge-stce', 1629, FALSE, 70, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643766.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643766-National-Rums-Of-Jamaica-CAMBRIDGE-STCE.jpg', 'Max 1 flaske per kunde Denne aftapning er ekskluderet fra alle rabatkoder Denne rom er en reproduktion af STC♥E-mark fra Cambridge-destilleriet, beliggende i Trelawny Parish og lukket i 1947. Denne blev destilleret ved Long Pond i 2010. Continental Flavored-stilen er en af de fire klassifikationer, der bruges i Jamaica, som identificerer rom med 550 - 1600 gr/hlpa estere på tidspunktet for destillation. STC♥E-mark er forkortelsen af Simon Thompson Cambridge Estate og refererer specifikt til rom med 550 - 700 gr/hlpa. Efter 12 års lagring, fuldt ud i det tropiske klima, er Angel''s Share > 55%. Kun 4900 flasker produceret og tappet ved 57% vol. Farve : Mørk. Duft : En rig og veludviklet duft med aroma af moden banan, saltet butter caramel og bivoks. Smag : Fyldig og cremet, men tør. Noter af toffee, valnød, ananas og kakifrugt. En lang og berusende finish med hints af crème brulée, tjære og kamfer. Serveringsforslag : Bør nydes rent. The National Rums of Jamaica LTD er et romproducerende og -eksporterende selskab, der er ejet i fællesskab af Jamaicas regering, West Indies Rum Distillery Ltd. i Barbados og Demerara Distillers i Guyana. Det består af Long Pond Distillery og Clarendon Distillery. Long Pond-destilleriet administrerer råmaterialerne og fermenteringsprocessen og har nu ansvaret for at gengive marks, der tidligere er lavet af andre destillerier, der nu er lukket.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('TDSC Colombian Rum 37YO Juuls Single Cask 2017', 'https://www.juuls.dk/rom/varekort/tdsc-colombian-rum-37yo-juuls-single-cask-2017', 4109, FALSE, 70, 46, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50641826.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50641826-TDSC-Colombian-Rum-37YO-Juuls-Single-Cask-2017.jpg', 'The Distinctive Spirits Co. (eller TDSC) har fremtryllet to fuldstændig unikke og uhørt gamle fade med udsøgt rom fra Destilería Colombiana. Dem har vi takket ja til at tappe eksklusivt til Juuls! Den ældste af de to er destilleret helt tilbage i 1980. Rommen blev oprindeligt tappet i 2017, hvorefter den blev ”re-bottled” i 2022 i kun 276 eksemplarer fra én vatted barrel. Undervejs har den fået en 36 måneder lang finish på high rye-whiskeyfade og holder stadig flotte 46% alkohol. Farve : Let mahogni. Duft : Dyb og dyster duft af kaffe, ristede marshmallows, karamel og et hint af lakrids. Smagsnoter : Mørke, kraftige noter af brændt sukker, gamle træfade og julekrydderier. Serveringsforslag : Bør nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Hampden Estate Pagos #4 High Esters', 'https://www.juuls.dk/rom/varekort/hampden-estate-pagos-4-high-esters', 819, FALSE, 70, 52, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643752.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643752-Hampden-Estate-Pagos-#4-High-Esters.jpg', 'Max 1 flaske per kunde Dette produkt er ekskluderet fra alle rabatkoder Hvis interessen er stor, trækker vi lod blandt alle henvendelser torsdag d. 9/2 2023 Denne rom i serien Habitation Velier kommer fra destilleriet Clarendon / Monymusk på Jamaica. Navnet MMW refererer til en romkategori hos Monymusk der defineres af et esterindhold i omegnen af 300 målt i gr/hL AA, og det betyder masser af smag! Rommen er destilleret i 2015 og tappet ved 59% alkohol efter 7 års tropisk lagring. Fuld styrke og nul sukker som altid. Farve : Rav. Duft : Intens aroma med strejf af chokolade, moden, tropisk frugt og gamle gummibånd. Smagsnoter :  Kraftig og bredskuldret rom med noter af knust kardemomme og muskatnød, banan og vanilje. Serveringsforslag : Nydes rent eller i den ekstra-luksuriøse Mai Tai!', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Velier FOURSQUARE Fidelitas', 'https://www.juuls.dk/rom/varekort/velier-foursquare-fidelitas', 2329, FALSE, 70, 55, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/90601093.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=90601093-Velier-FOURSQUARE-Fidelitas.jpg', 'Max 1 flaske per kunde. Denne aftapning er ekskluderet fra alle rabatkoder Fidelitas er det nyeste skud på stammen i serien af ultra-eftertragtet rom lavet i samarbejde mellem Foursquare Distillery og Velier. Dette års release er nummer 10 i serien, og den er den hidtil ældste med hele 20 års tropisk lagring: de første 19 år ligger den på bourbonfade, efterfulgt af 1 år på marsalafade. Den er tappet ved 55% i blot 2.160 eksemplarer. Farve : Kobber. Duft : Koncentreret duft af toastede nødder (hasselnød, mandel), kanel, vanilje og appelsinskal.   Smagsnoter : Mægtigt dyb og balanceret. Ristet kokos blandet med tonkabønne, muskatnød og sort peber. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sol Tarasco Charanda Anejo - Hongos', 'https://www.juuls.dk/rom/varekort/sol-tarasco-charanda-anejo-hongos', 559, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Images/juuls/defaultbottle.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50625851-Sol-Tarasco-Charanda-Anejo---Hongos.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Port of Caribbean XO Rum', 'https://www.juuls.dk/rom/varekort/port-of-caribbean-xo-rum', 429, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/506420330.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=506420330-Port-of-Caribbean-XO-Rum.jpg', 'Lad Port of Caribbean henføre dig til en gesjæftig, caribisk havneby hvor store sejlskibe læsses til lyden af sydende jerngryder og enorme tønder med rom, der rulles hen over kajen, hvor havbrisen blander sig med duften af Havana-tobak, overmodne mangoer og svulmende sække med allehånde og muskatnød. Der er intet, der kan sætte gang i minder og fantasi, som smage og dufte! Efter mange år på gamle bourbonfade har denne luksuriøse spiritus udviklet så betagende noter af vaniljestænger, tyk melasse, tropisk frugt og eksotiske krydderier, at en lille smule caribisk dagdrømmeri er helt på sin plads når man får den i glasset. God rejse! Farve : Mahogni. Duft : Et overflødighedshorn af varm karamel, vaniljestænger, moden, tropisk frugt, allehånde og kanel. Smagsnoter : Fyldig, cremet og sødmefuld. Rammer tungen blidt med noter af melasse, kokossukker, varme krydderier og karamel. Eftersmagen er lang og rund. Serveringsforslag : Nydes rent.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sepé Ron Blanco mini ØKO', 'https://www.juuls.dk/rom/varekort/sepe-ron-blanco-mini-oeko', 59, FALSE, 5, 41, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643474.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643474-Sepé-Ron-Blanco-mini-ØKO.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Sepé Ron Anejo mini ØKO', 'https://www.juuls.dk/rom/varekort/sepe-ron-anejo-mini-oeko', 69, FALSE, 5, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643475.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643475-Sepé-Ron-Anejo-mini-ØKO.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Beenleigh 10 Years Old 2013', 'https://www.juuls.dk/rom/varekort/beenleigh-10-years-old-2013', 859, FALSE, 70, 59, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615612.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615612-Beenleigh-10-Years-Old-2013.jpg', 'Max 1 flaske per kunde Dette produkt er ekskluderet fra alle rabatkoder Beenleigh er Australiens ældste destilleri. Og når det gælder rom, er det formentlig også landets bedste. Alligevel har Beenleigh altid været ret vanskeligt at få fat på i Danmark, men heldigvis er der begyndt at dryppe lidt ind fra Velier en gang i mellem! Rommen her er destilleret i 2013 og lagret på bourbonfade i tropisk klima indtil den blev tappet i 2023 ved hele 59% alkohol. Yderst begrænsede mængder. Farve : Dyb gylden. Duft : Livlig, frugtig duft af passionsfrugt, guava, jasmin, moden melon og vanilje. Smagsnoter : Smagen er kraftig og krydret, med noter af ingefær, granatæble, figen og kardemomme. Serveringsforslag : Nyd den rent, og prøv gerne med en dråbe køligt vand eller to.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Ron Zacapa Heavenly Cask La Pasion 2023', 'https://www.juuls.dk/rom/varekort/ron-zacapa-heavenly-cask-la-pasion-2023', 709, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50644753.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50644753-Ron-Zacapa-Heavenly-Cask-La-Pasion-2023.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Savanna HERR 2023 Limited Edition', 'https://www.juuls.dk/rom/varekort/savanna-herr-2023-limited-edition', 569, FALSE, 50, 57, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50615479.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50615479-Savanna-HERR-2023-Limited-Edition.jpg', 'Savannas ”HERR” er en af romverdenens store kuriositeter. Og nej, den er ikke tysk, men fra øen La Réunion i det Indiske Ocean. Navnet er en forkortelse for ”High Ester Rum Réunion”, og betegner en stil, hvor der er skruet herremeget op for smagen! En lang gæring efterfulgt af destillation på pot stills og ingen fadlagring giver et kanonslag af en rom – nok ikke for nybegyndere! 2.700 flasker på verdensplan. Farve : Klar. Duft : Højeksplosiv duft af moden ananas og anden tropefrugt, gummi, jordbærmarmelade og Stillehav. Smagsnoter : Superintens, floral og frugtig. Kæmpe smag af eksotisk frugt, funk og bolsjeblanding. Lang, tør finish. Serveringsforslag : Kan nydes rent – af nogle – eller bruges i cocktails.', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Angostura Caribbean Rum 7 Years Old', 'https://www.juuls.dk/rom/varekort/angostura-caribbean-rum-7-years-old', 259, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50643610.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50643610-Angostura-Caribbean-Rum-7-Years-Old.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('El Dorado 3 years', 'https://www.juuls.dk/rom/varekort/el-dorado-3-years', 199, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50646280.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50646280-El-Dorado-3-years.jpg', '', '2026-11-08 09:30:00+01');
INSERT INTO stg_juuls_dk (name, url, price_dkk, in_stock, volume_cl, abv, image_url, description, scraped_at) VALUES ('Planteray Sealander VSAR VAP med 2 glas', 'https://www.juuls.dk/rom/varekort/planteray-sealander-vsar-vap-med-2-glas', 429, FALSE, 70, 40, 'https://www.juuls.dk/admin/public/getimage.ashx?Image=/Files/Images/Products/50648081.jpg&Width=480&Height=0&Format=jpg&Quality=75&Crop=0&filename=50648081-Planteray-Sealander-VSAR-VAP-med-2-glas.jpg', 'Endelig er Plantation Sealander kommet sikkert i havn! Hele 3 markante rom-øer har lagt kedler til denne unikke rom: Mauritius, Fiji og Barbados. Dermed spænder rommen også over 3 verdenshave: Atlanterhavet (Barbados), Stillehavet (Fiji) og Det Indiske Ocean (Mauritius). Komponenten fra Mauritius er lavet på frisk sukkerrørssaft, mens de to andre er lavet på melasse. Der er altså tale om lidt af et world blend , som på trods af vidt forskellige ophav har nået en vidunderlig harmoni. Farve : Rav. Duft : Milde noter af bagt pære, kvæde, mørk melasse, tonkabønner og et strejf af røg. Smagsnoter : På én gang delikat og fyldig, med stor sødme og noter af kløverhonning, vanilje og sveske. Serveringsforslag : Nydes rent eller evt. med en isterning.', '2026-11-08 09:30:00+01');
